window.__D("text/hemshech-ayin-beis/c011",{"p":[[3601331032,"ובפרט בההתבוננות איך שכולא קמי' כלא חשיב כו' (שזהו בהשגת הנשמות וכמ\"ש בתו\"א ד\"ה בכ\"ה בכסלו), שעי\"ז תתלהט נפשו ברשפי האש התשוקה ליקר תפארת גדולתו כו' כמ\"ש בסש\"ב פ\"נ, ומזה בא לידי צמאון (דתחלה הוא בבחי' תשוקה ואח\"כ נעשה בבחי' צמאון) וחולת אהבה ובחי' כלות הנפש כו' שז\"ע המס\"נ דק\"ש שע\"י הקדמת האה' ברשפי אש בברכת אהבת עולם באים לידי מס\"נ באחד בק\"ש כו', שכ\"ז הוא בבחי' אה' פנימי' ממש שנשרף כל מציאותו ברשפי אש זה כו' (וכמו השרפים שכל מהותם הוא הרשפי אש כו'), ובאש זה נשרף גם הנה\"ב וכמ\"ש בכל לבבך בשני יצריך כו', והו\"ע החקיקה מבפנים שנעשה ג\"כ בבחי' כלי כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ואלה שמות בנ\"י את יעקב, דהנה ישראל ויעקב שניהם הם בבחי' המוחין דישראל הוא לי ראש ויעקב יו\"ד עקב שזהו המוחין, רק דישראל הוא עצמי' המוחין שלמעלה מהמשכה עדיין, ויעקב הוא בחי' המוחין כמו שהן בהמשכה שז\"ע יו\"ד עקב כו', והיינו דישראל זהו בחי' פנימי' המוחין שלמעלה מהמדות ויעקב בחי' חיצוני' המוחין שנמשכים במדות כו', ובישראל זהו בחי' ישראל סבא וישראל זוטא שזהו בחי' ז\"א כמ\"ש כי נער ישראל כו' והן בחי' המוחין שבמדות כו', וגם בפנימי' המוחין יש מדות אלא שהן פנימי' המדות דגילוי המוחין אין זה בבחי' המשכה ממש כו' כנ\"ל. וזהו מ\"ש ואלה שמות בנ\"י הבאים כו' ב\"פ, דהנה כתי' ירד ירדנו שיש ב' ירידות וכן בעלי' כתי' אעלך גם עלה כו', והענין דהנה נודע דכשם שיש מצרים בלעו\"ז כמו\"כ יש מצרים בקדושה והן מצרים וגבולים שזהו כללות השתל' העולמות כו', וידוע דעולמות בכלל הן ב' מדרי' עלמין סתימין דלא אתגליין ועלמין דאתגליין והן בחי' מח' ודבור דמאותיות המח' נתהוו עדאתכ\"ס ומדבור עדאת\"ג כו', וזהו\nהירידה היינו הירידה דבחי' ישראל בחי' פנימי' ועצמי' המוחין שהירידה היא בבחי' מח' לבד כו', והירידה הב' היא דבחי' יעקב דהיינו חיצוני' המוחין והיא הירידה בבחי' דבור העליון כו', וזהו מ\"ש ואלה שמות בנ\"י הבאים מצרימה בפ' ויגש היינו ירידה הא', וכפל הדבר בפ' שמות שזהו ירידה הב' כו'. וזהו דשם נא' יעקב ובניו שיעקב בכלל בנ\"י להיות דישראל הנא' שם הוא בחי' פנימי' המוחין, לגבי מדרי' זו יעקב שזהו בחי' מוחין שבמדות הוא בחי' בן דז\"א ב\"ן לאו\"א כו', וכאן בפ' שמות נא' את יעקב, דישראל הנא' כאן הוא בחי' ישראל זוטא, לגבי מדרי' זו יעקב אינו בבחי' בן כ\"א בבחי' אח כו'. וזהו ואלה שמות בנ\"י שכפל הדבר להיות שזהו הירידה בבחי' דבור כו', ולכן שם נא' יעקב ובנ\"י דיעקב בכלל בנ\"י וכאן את יעקב שהוא בבחי' אח כו'.\n<span data-k=\"ks\"><b>קיצור.</b> דהנה פסוד\"ז וברכת ק\"ש וק\"ש הן רוח רעש אש, רוח התפעלות המדות בפסוד\"ז מהפלאת הענין, והוא בלי מבוקש רק רוממות הנפש, ורעש בברכת יוצר מההתחדשות בהתבוננות דקדוש, וגם מההפלאה שבלתי מושג, שג\"ז התחדשות ומ\"מ הוא בבחי' פנימי יותר מבחי' רוח, ולכן יש בזה מבוקש להיכלל באוא\"ס ב\"ה, ואש בברכת אה\"ע, והוא מבחי' הבינה (דחכ' הוא בחי' הביטול בקרירות), והוא ההתבוננות איך דאיהו ממכ\"ע וסוכ\"ע שמשיג ומכיר יקר תפארת</span>"],[3601331033,"<b>גדולתו</b> ית', ועי\"ז יתלהב ברשפי אש האהבה והתשוקה ליקר תפארת גדולתו, ומזה בא לידי צמאון וחולת אהבה וכלות הנפש בק\"ש (ובאש זה נשרף גם הנה\"ב להיות כלי לאלקות). ובהנ\"ל יובן מ\"ש ואלה שמות בנ\"י, ישראל ויעקב פנימיות המוחין וחיצוניות המוחין וגם בפנימיות המוחין יש מדות וז\"ע בנ\"י."],[3601331034,"<h3>בס\"ד. ש\"פ וארא, העת\"ר</h3>\n<b>וידבר</b> אלקים אל משה ויאמר אליו אני הוי' וארא אל אברהם כו' ושמי הוי' לא נודעתי להם, וצ\"ל מהו מודיע לו אני הוי' הלא כבר הודיע לו ש' הוי' כמ\"ש בפ' שמות, ובאמת כבר הי' ידוע הש' דהוי' למשה ולישראל מקודם, ומש\"א משה ואמרו לי מה שמו מה אומר אליהם פי' הרמב\"ן ז\"ל שלא שאל ידיעת השם כ\"א שאלתו הי' לידע מאיזה מדה היא השליחות אם מהמדה שממנה נסים שבדרכי הטבע או מהמדה שהנסים הם למעלה מהטבע, וא\"ל כה תאמר לבנ\"י הוי' אלקי אבותיכם שלחני אליכם כו', אבל עצם השם הי' כבר ידוע להם, וכשבא לפרעה בא עם הש' הוי' וכמ\"ש כה אמר הוי' אלקי ישראל כו', ופרעה א' לא ידעתי את הוי' דמשם אלקים ידע ועל שם הוי' אמר לא ידעתי שלא רצה לידע מש' הוי', וא\"כ אינו מובן מה מודיעם לו עתה אני הוי' וכתי' לכן אמור לבנ\"י אני הוי' כו'. גם צ\"ל מש\"א וארא אל אברהם כו' ושמי הוי' לא נודעתי להם והלא מצינו כ\"פ ש' הוי' אצל האבות כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דג' מדרי' דתפלה פסוד\"ז ברכת ק\"ש וק\"ש הן בחי' רוח רעש ואש דכולם הם בבחי' המדות רוח הוא\nבחי' התלהבות המדות בבחי' מקיף שבא מההתבוננות בענינים שהן בעצם למעלה מהשגה כו', רעש הוא מהתחדשות דבר ומהפלאת הענין ע\"כ הוא בבחי' רעש, ומ\"מ ה\"ז בבחי' התפעלות פנימי יותר מרוח, ואש הוא בחי' אהבה פנימיות שבא מבחי' השגה גמורה בגדולת ה' כו'.\n<b>שצט)</b> והנה בהג' ענינים דרוח רעש ואש כתי' לא ברוח הוי' לא ברעש כו', והענין דהנה רוח הוא בפסוד\"ז בהתבוננות דהתהוות העולמות שנתהוו מרוח פיו ית', הרי אין זה רוח הוי' כ\"א רוח אלקי', וכידוע דמש' הוי' לא הי' אפשר להיות התהוות העולמות רק מש' אלקים וכמ\"ש בראשית ברא אלקים, ובש' הוי' הוא בחי' ה' אחרונה והו\"ע בהבראם בה' בראם שאינו רק הבל רוח חיצוני שנק' אותא קלילא דלית בה מששא כו', ואחרי הרוח רעש שזהו בברכת יוצ\"א בהביטול דמלאכים ונשמות בהתבוננות דקדוש שהוא בחי' קדוש ו' והיינו המשכת הארה מבחי' קדש העליון להיות בבחי' ממכ\"ע וסוכ\"ע כו', שבזה הוא ההתבוננות דקדושת אוא\"ס ב\"ה ואיך שאין קדוש כה' כו' וכמ\"ש בלק\"ת ד\"ה צאו\"ר הב', ולא ברעש הוי' שהרי זהו רק בחי' ו\"ה לא בחי' י\"ה כו', וגם הוא\"ו"],[3601331035,"הוא רק בבחי' מקיף שז\"ע קדוש ו' כו', ואחרי הרעש אש בחי' האהבה דרשפי אש דברכה שני' דק\"ש וק\"ש כו', לא באש הוי' דעיקר ש' הוי' הוא היו\"ד דש' הוי' כנודע, וי\"ל דהיו\"ד דש' הוי' מורה על התמידות וההווה וכמו ככה יעשה איוב שעושה תמיד כו', וזה עיקר ש' הוי' שהוא הי' הוה ויהי' כא' וע\"ז מורה ענין התמידות דהיינו שלמעלה מהזמן, וכן ההוה מורה ע\"ז וכמ\"ש הרמב\"ן בפי' הפסוק ואמרו לי מה שמו שהעבר והעתיד הוא בבורא בהוה כו', דהי' הוא עבר ויהי' עתיד כו' מורה על הזמן, אבל הוה הוא שאינו בעבר ועתיד וה\"ה למעלה מהזמן, וע\"כ היו\"ד הוא עיקר שם הוי' כו', ופנימיות הענין הוא להיות דש' הוי' הוא באצי' והעיקר הוא היו\"ד שזהו בחי' אצי' כו', והרשפי אש הוא מבחי' בינה ה' ראשונה דהוי' ואינו נמשך בזה היו\"ד דש' הוי'. אמנם אי' בת\"ז אית רעש ואית רעש אית רעש דלא ברעש הוי' ואית רעש דברעש הוי' כו', והיינו דמ\"ש לא ברוח ורעש ואש ה' זהו בבחי' רוח רעש ואש דבי\"ע, אבל כל המדרי' האלו ישנם ג\"כ באצי' והן בחי' בי\"ע דאצי' כו', ושם כולן הן בבחי' ש'\nהוי' כו', וי\"ל דהרי באצי' אבא עילאה מקננא באצי' דבכל המדרי' דאצי' מאיר בחי' היו\"ד דש' הוי' וע\"כ אצי' הוא בבחי' ביטול ואחדות כו', שזהו ההפרש בין בי\"ע לאצי' דבבי\"ע כל המדרי' האלו הן בבחי' מורגש, הן בחי' ההתלהבות דרוח והן בחי' הרעש ה\"ה במורגש בבחי' יש כו', וגם בחי' האהבה ברשפי אש דק\"ש ה\"ה במורגש וכידוע דאהוי\"ר דק\"ש הן בחי' חו\"ג המגולים, דזהו ההפרש בין ק\"ש לשמו\"ע דשמו\"ע הוא בחי' עה\"ח שזהו חו\"ג המכוסים באימא, וק\"ש בחי' חו\"ג המגולים שהן האהוי\"ר דבהתגלות הלב שזהו בבחי' מורגש כו', אבל באצי' הכל הוא בבחי' ביטול ובלתי מורגש כו', וכמ\"ש בלק\"ת ד\"ה ששים המה מלכות בענין ונהר יוצא מעדן דבאצי' בחי' בינה היא בבחי' אחדות עם בחי' החכ' רק בבריאה ומשם יפרד כו', והיינו לפי שבאצי' מאיר בחי' היו\"ד דש' הוי' ע\"כ שם הכל הוא בבחי' ביטול כו', וזהו דכל המדרי' הם שם בבחי' ש' הוי' כו'. וב' מדרי' הנ\"ל זהו בחי' חיצוני' המוחין ובחי' פנימי' המוחין דבעבודה בבחי' חיצוני' המוחין (שזהו העבודה דנשמות דבי\"ע) הכל הוא בבחי' יש\nומורגש כו', אבל בהעבודה דבחי' פנימי' המוחין הוא בבחי' ביטול כו', דהעבודה בבחי' פנימי' המוחין עיקרה הוא בנשמות דאצי' (וי\"ל שזהו בנשמות דבחי' אצי' שבבי\"ע, כי אצי' ממש הרי מבו' בסש\"ב פל\"ט שזהו למעלה מבחי' השכל והשגה כו', דגם בבחי' המוחין זהו למעלה גם מבחי' פנימי' המוחין כו' וכמשי\"ת, והעבודה דבחי' פנימי' המוחין שזהו עצם בחי' נשמה י\"ל שזהו בחי' אצי' שבברי' כו'), שהן בבחי' ביטול בתכלית כו'. והענין הוא דהנה ידוע שיש בחי' קלא דאשתמע וקלא פנימאה דלא אשתמע, ויש להבין בחי' קלא דלא אשתמע איך שייך לקרותו בשם קול מאחר שהוא בפנימיות דלא אשתמע לזולתו כלל, אך הנה ידוע דקול הוא שמורכב מג' בחי' אמ\"ר כו', וכשם שהקול היוצא בהתגלות מורכב מאמ\"ר כמו\"כ גם ההבל פנימי דפנימי' הלב מורכב ג\"כ מאמ\"ר, רק שהוא אמ\"ר פנימאה שאינו מורגש אל הזולת כו' (עמשנת\"ל פשל\"ה ושל\"ו), וכמ\"ש בזהר ע\"פ אין אומר ואין דברים דקאי על מ\"ש קודם יום ליום יביע אומר קאמר ע\"ז אין אומר כו', דלאו איהו כאמירן דעלמא דאשתמע ואמר זה לא אשתמע כו', וכמ\"ש בסידור בשבת ברכות ע\"פ זה, וזהו שמצינו ל' צעקה גם בפנימי' הלב וכמו צעק לבם אל"],[3601331036,"ה', וידוע ההפרש בין צעקת הקול לצעקת הלב דצעקת הקול הוא שבא בצעקה בקול פשוט בהתגלות ובמורגש כו' (שזהו למעלה מהקול שבא בדבור כו', ונק' ג\"כ קלא פנימאה כו', ומ\"מ הוא שבא בבחי' מורגש בעצמו ולזולתו כו'), וצעקת הלב הוא שהלב עצמו צועק מפנימי' הלב ועומקו ביותר שאינו בא כלל בקול ואינו מורגש כלל בעצמו ולזולתו כו', ומ\"מ מה שנק' בש' צעקה היינו שזהו כמו צעקת הקול שמורכב ג\"כ מאמ\"ר כו' (וצ\"ל שזהו מ\"מ כאשר בא מאיזה ענין פנימי כמו איזה השגה וכמו בפנימי' המוחין כו', אבל בבחי' צעק לבם דבתשובה אמיתי' מעומק לעומק כו', ה\"ז בבחי' פשיטות לגמרי בלי שום הרכבה כו').\n<span data-k=\"ks\"><b>קיצור.</b> והנה כתי' לא ברוח הוי' כ\"א רוח אלקים והוא ה' אחרונה, ולא ברעש דברכת יוצר ה' כי הוא רק בחי' קדוש ו', ולא באש דק\"ש ה' שזהו בחי' ה' ראשונה, ועיקר הוי' הוא היו\"ד שמורה על התמידית, הי' הוה ויהי' והוא בחי' אצי', ואי' בת\"ז אית רעש דברעש הוי' והיינו בחי' רוח רעש אש דאצי' דאבא מקננא בכללות האצי' והוא בחי' ביטול ובלתי מורגש, וכמו ק\"ש חו\"ג מגולים ושמו\"ע חו\"ג מכוסים, והוא בחי' פנימיות המוחין והוא בחי' קלא פנימאה שמורכב מאמ\"ר פנימי וכמו צעק לבם (ובתשו' הוא בבחי' פשיטות לגמרי ובפנימיות המוחין הוא בבחי' אמ\"ר פנימי).</span>\n<b>תיו)</b> ומאחר שגם בקלא פנימאה שבתוך נקודת הלב יש בחי' צעקה פנימי' וה\"ה מורכב מאמ\"ר פנימאה כו', הרי יובן שימצא גם שם ג' מדרי' הנ\"ל דרוח רעש ואש רק שכ\"ז הכל בבחי' הפנימי' שבלב כו', וכמו התפעלות רשפי אש בפנימי' נקודת הלב הוא אש פנימי ביותר שלא נראה וניכר מגודל עומקו כו' (בל\"א דיא הארץ קלייעט אינוועניק טיף זייער), והיינו לפי שחיצוני' הלב הוא בבחי' יש ומציאות בעצם ובבחי' התגלות, דהא בהא תלי' דלפי שהוא בבחי' מציאות לכן הוא בבחי' התגלות כו', וע\"כ גם הרשפי אש הוא בהתגלות כו', אבל פנימי' הלב שאינו בבחי' מציאות יש כו' ע\"כ גם הרשפי אש דפנימי' נקודת הלב אינו בהתגלות במורגש כו', ועם היות שהרשפי אש הוא בתוקף ביותר מבחיצוניות הלב, ה\"ה טמיר ונעלם בלב ואינו ניכר כו'. וכמו\"כ בהתפעלות רעש שבא מהתחדשות דבר (וכמשנת\"ל פ' שצ\"ח שהרעש הוא מדבר חדש כו', וכמו\"כ הוא גם בבחי' פנימי' המוחין די\"ל דגם בנשמות הגבוהות הרי קדושת העצמות הוא בבחי' התחדשות ובלתי מושג ממש שהרי לית מח' תפיסא בי' כו', ובפרט שבבחי'\nפנימי' המוחין להיות שהן בבחי' הפשטה מלבושי השגה הרי נרגש יותר ההפלאה כו', ועם היות שגם ההנחה היא באופן אחר בפנימי' המוחין מ\"מ גם ההפלאה נרגש יותר כו', וע\"כ שייך גם שם ענין הרעש מההתחדשות דבר כו', גם י\"ל בהשגה והתבוננות דה' אחד ענין ההתחדשות בזה הוא שזהו ההיפך לגמרי מכמו שנראה ונגלה בעולם כו', רק י\"ל שיש בזה הפרש אם ההתבוננות היא בהאחדות מצד האוא\"ס ב\"ה אם מצד העולמות כו', והכל הוא בענין ה' אחד שמצד העולמות (לא מה שהוא ית' יחיד ומיוחד בעצם כו'), רק אם ההרגש בההתבוננות היא איך שאוא\"ס ב\"ה גם שמהווה עולמות ה\"ה יחיד ומיוחד שלא יש עוד דבר ח\"ו, או שההרגש הוא איך שהעולמות גם שנתהווה ה\"ה"],[3601331037,"בטלים ומיוחדים בתכלית כמו קודם שנתהוו כו', דכאשר ההרגש הוא מצד העולמות נרגש בזה ביותר ההתחדשות שזהו ההיפך מכמו שהעולם הנראה כו', וע\"כ בה' אחד שמצד אוא\"ס ב\"ה ה\"ז בבחי' רשפי אש וכאשר הוא מצד העולמות ה\"ז בבחי' רעש כו'), אבל הוא בעומק ופנימי' המוח (מצד פנימי' ההשגה כו') ובפנימי' הלב ביותר שירעש נקודה הפנימי' שבלב בלי יוכר לזולתו כלל רק הוא בתוך תוכו כו' (וכפחד פנימי שיחרד ויפחד בתוך פנימי' הלב עצור וכנוס בלי היכר כלל כו', וכמו ויחרד כל העם אשר במחנה שזהו בחי' חרדה פנימי' כו', דמ\"ש וירא העם וינועו ויעמדו מרחוק ה\"ז בחיצוניות בהתגלות היראה כו', אבל מ\"ש ויחרד העם ה\"ז חרדה ופחד פנימי כו'). וכמו\"כ התעוררות רוח ברוח החיים שבפנימי' הלב כו', והיינו שהוא חי בהענין דהענין האלקי הוא אצלו עם חיות גדול והוא חי בהענין (ער לעבט אין דעם) שאין זה חיות בהתפעלות כו', וכמו איש חי בעצם היינו שבכל ענין הוא חי ואין זה בהתפעלות, וכמו\"כ הוא בבחי' רוח החיים שהוא חי בהענין האלקי כו', וזהו בחי' רוח רעש ואש שהכל הוא\nבבחי' פנימי' עומק הלב כו'. ובזה ג\"כ המדרי' חלוקות דבחי' רעש הוא פנימי יותר מבחי' רוח ובחי' אש יותר פנימי מרעש כו', אך בכללות הכל הוא בבחי' פנימי' כו', והיינו דבבחי' פנימי' המוחין שהיא ההשגה וההתבוננות בעצם הענין האלקי בלי לבושי השגה באיזה ענין שמתבונן אם בפסוד\"ז או בהתבוננות דברכת ק\"ש וק\"ש כו' ה\"ז תופס בהעצם שמאיר בעומק ופנימי' מוחו ולבו כו', וע\"כ הכל הוא בבחי' פנימי' בתכלית הביטול בבחי' בלתי מורגש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויש בזה רוח רעש ואש והכל בפנימי' דהרשפי אש עם היותו בתוקף ביותר ה\"ה טמיר ונעלם בלב ואינו ניכר כלל, והרעש הוא מהתחדשות קדושת העצמות, ומהביטול דעולמות שהו\"ע ה' אחד שזה היפך מהנגלה (ואם ההרגש הוא האחדות דאוא\"ס (הגם שמהווה) הוא בבחי' אש, ואם הרגש האחדות דהעולמות הוא בבחי' רעש), והוא ירעש בפנימיות מוחו ולבו וכמו חרדה פנימיות, ורוח הוא בחי' רוח חיים שבלב שהוא חי בכל הענין אלקי וכמו איש חי בעצם.</span>\n<b>תא)</b> והנה יש מדרי' עליונה מזה והיא הכוונה פנימי' שבמוח, והיינו התפעלות הנפש בגוף נקודת המושכל קודם שבא לידי השגה, והוא בחי' האין של ההשכלה האלקית שנתפס בזה העצם האלקי כו', דהנה בחי' פנימי' המוחין הנ\"ל ה\"ז בא בסדר דהשגה ממש רק שאינו בלבושי ההשגה כ\"א בעצם הענין אבל כמו שהענין בא בהשגה כו', וא\"כ ה\"ה תופס רק בפרטי הענין לא בעצם הענין היינו בעצם נקודתו האמיתית, דכל השגה ה\"ה בהפרטים של הענין לא בהעצם כו', א\"כ ה\"ז תופס רק בפרטי הענין כו', וע\"כ גם מה שתופס בהאלקות שבהענין אין זה בעצם אור האלקי כ\"א כמו שבא בהשגה שזהו הנק' הענין האלקי היינו ההתפשטות מה שבא בהשגה כו', ועם היות שזהו למעלה הרבה מבחי' חיצוני' המוחין שהיא ההשגה ע\"י לבושי ההשגה, שזהו מה שתופס את הענין אלקי ע\"י לבוש ומסך שהן הלבושים וההסברים שע\"י תופס הענין, שגם בהרגש הענין האלקי בזה הוא כמו דרך מסך כו' (והדוגמא מזה למעלה הוא דאימא עילאה"],[3601331038,"מקננא בכורסי' דרך המסך שבין אצי' לברי' כו'), משא\"כ בפנימי' המוחין ה\"ה תופס בעצם הענין האלקי שלא ע\"י לבושים כו', מ\"מ מאחר שהתפיסא הוא ע\"י השגה וההשגה היא בהפרטי' לבד וגם כל השגה הוא בחי' יש כו', אינו תופס בעצם האלקי ממש כו', אבל בנקודת המושכל שלמעלה עדיין מהשגה, הרי ידוע דבנקודת ההשכלה מאיר דקות הענין שכלי ועצם המושכל (מה שאח\"כ כשמביא את הענין לידי השגה עם היות שזהו שמבאר ומפרט פרטי הנקודה אין עצם המושכל מאיר בזה כו', ולכן באמת בריבוי ההשגות מפני שמתרחק מעצם המושכל (היינו שהמושכל מתעלם) יכול לבא לידי טעות או עיקום ר\"ל שהפרטים אינם כפי אמיתת עצם הענין, וצריכים בכל עת לשמור עצם נקודת המושכל שלא יטעה כו' וכמ\"ש במ\"א ונז' ג\"כ לעיל פקצ\"א, וזהו מצד התעלמות עצם המושכל בההשגה וכ\"ש שדקות הענין מתעלם בההשגה כו'). וכמו\"כ הוא באלקות דבנקודת המושכל נרגש עצם האלקי שבהענין, דכשם שבהשכלת הענין הרי בנקודת ההשכלה מאיר עצם המושכל, כמו\"כ בהאלקי נרגש בזה עצם אור האלקי המאיר אצלו בגילוי ממש כו', ותוכן הכוונה\nבזה הוא שבנקודת המושכל הוא יודע היטב כל הענין כמו שהוא לאמיתתו ומרגיש בזה את העצם האלקי כו'. דהנה השגה דבינה ה\"ה מבארת את הנקודה דחכ', והוא שבנקודת ההשכלה אינו יודע עדיין את הענין לאמתתו וכ\"ש איך ומה הוא כו', להיות שזהו עדיין בבחי' נקודה כללית ע\"כ הגם שמאיר אצלו עצם המושכל ודקות הענין כ\"ז הוא בבחי' כללות עדיין כו', ובהשגה דבינה הוא שמתבאר ומתפרט הענין ומשיג אותו היטב ואיך ומה הוא כו', וגם בבינה מתברר הנקודה דחכ' שיכול להיות בה בהעלם איזה הטי' שאינו אמת וע\"י ההשגה מתברר הדבר כו', וכמו שאנו רואין לפעמים נופל לאדם איזה השכלה ונראה לו שהוא טוב וכשמביא זאת לידי השגה רואה שאינו כן, וכמו\"כ בנקודת ההשכלה יכול להיות בהעלם הטי' שאינו אמת ומתברר ע\"י הבינה כו', וכידוע דעיון דבינה הוא מקום הבירור כו' וכמ\"ש בתו\"ח ד\"ה אלה תולדות נח, הנה כ\"ז הוא בסדר ההשתל' דחו\"ב דראשית גילוי השכל הוא בבחי' נקודה כללית ועדיין אינו יודע את הענין כו', וידיעת והשגת הענין ובירור הדבר הוא ע\"י השגה דבינה כו', אבל במי שהוא\nבמדרי' זו דבחי' נקודת החכ' והיינו בבחי' כוונה פנימי' שבמוח הוא שבנקודת המושכל (קודם שבא לידי השגה ממש) הוא יודע את הענין לאמתתו, ואינה אצלו בבחי' נקודה כללית לבד, כ\"א שיודע את הענין בהפרטים שבו אלא שאינו בבחי' פרטים ממש כמו בהשגה כ\"א תוכנם ותמציתם שמאירים בדרך ממילא היינו לא שנכנס בהענינים הפרטי' (שאם יכנוס בהפרטים ה\"ה ניתק מעצמות הענין), כ\"א שבהנקודה הוא תופס את הענין עם הפרטים שבו, ואינם בבחי' פרטים מורגשים רק שידיעת הענין הוא כמו שידוע ומושג מהפרטים שבו כו', וכמו בנקודת התמצית שבא לאחר השגה שהוא מה שיודע עומק המושג כמו שבא מהשגת הפרטים (שזהו בחי' האין של היש דהשגה והוא מה שהיש דהשגה בא לבחי' אין כו', הרי לא יש בזה הפרטים דז\"ע נקודת התמצית ששולל את הפרטים ובא רק אל הנקודה של המושכל איך הוא מושג מהפרטים שזהו עומק המושג כו', וידוע שמאיר בזה עצם ענין המושג כו'), כמו\"כ הוא בנקודת המושכל קודם שבא לידי השגה שתופס בתחלה את הענין לא רק בכללות כ\"א כמו שידוע מהפרטים שלו (שאינם בבחי' פרטים מורגשים כו')."],[3601331039,"<span data-k=\"ks\"><b>קיצור.</b> ולמעלה מזה הוא הכוונה פנימיות שבמוח, והוא נקודת המושכל האלקי, דהנה פנימיות ההשגה עם שתופס בהעצם ה\"ז רק בעצם הענין האלקי דהיינו ההתפשטות, ונקודת המושכל תופס בעצם האלקי (כמו שבנקודת ההשכלה מאיר עצם השכל), וענין נקודת המושכל הוא שבנקודה א' (והיא נקודת החכ') יודע הדבר לאמיתתה וא\"צ לביאור ולברור וללבון הבינה, כי היא אצלו לא נקודה כללית כ\"א יודע את הפרטים שבה, ואינם פרטים מורגשים כי לא נכנס בזה כלל רק שהנקודה עצמה היא בבחי' מרחב שבהנקודה יודע את הענין כמו שבא מהפרטים (ואם יבוא אל הפרטים לא יהי' אצלו התחדשות בזה), ובדוגמא כמו נקודת התמצית שבאה אחר השגת הפרטים.</span>\n<b>תב)</b> ויובן זה יותר מתפיסת הענין בדרך קצרה שהרי לעולם ישנה אדם לתלמידו בדרך קצרה דבהשפעת השכל מרב לתלמיד הרי משפיע לו תחלה כללות הענין בדרך קצרה שהוא בבחי' מועט המחזיק את המרובה כו', וכידוע דענין דרך קצרה זאת אינה העלמת דברים לקצר ולהעלים כו', אלא הענין הוא שיכלול כל ההשפעה ההיא בדברים קצרים שיהי' מיעוט הדברים מחזיקים כל האורך ורוחב שיש בהפרטים שבאותה ההשפעה כו', וכמ\"ש הרמב\"ם בפ\"ב מהל' דעות ה\"ד שיהיו דברי האדם מועטים ועניניהם מרובים, וכמו ל' המשנה שבהדברי' המועטי' יש בהם כל אריכות הפלפול שבגמ', וכמא' אילפא מי איכא מידי בברייתא דלא פשיטנא לה ממתניתין כו', והרי מ\"מ מהדברים הקצרים אינם יודעים את הפרטים עדיין, וכמו לידע פרטי הדברים הנעלמים בהמשנה ה\"ז ע\"י אריכות הגמ' כו', אך מי שהוא חכם גדול ויש לו חוש בהשכלה ה\"ה מקבל את הענין תיכף ויודע אותו, והיינו דכאשר שומע איזה דבר מושכל תיכף כאשר שומע הדברים הקצרים ה\"ה משיג אמיתית הענין מתוך הדברים הקצרים ויודע היטב מה הוא הענין המושכל\nוהכוונה בזה (ער ווייס וואס דאס איז און וואס מי מיינט אין דעם) וא\"צ להאריכות כלל, כי האריכות לא יחדש לו דבר שכבר יודע הוא את הענין ויכוון כל האריכות מעצמו, והרי בידיעה והשגה זו ה\"ה משיג את הפרטי' הנעלמים בדברים הקצרים, שהרי אם משיג רק קיצור הענין כמו שהוא בגלוי בהדברים קצרים ואינו יודע את הפרטים הרי אין זה השגת אמיתי' הענין, אבל כשמשיג את המרובה המוחזק בהמיעוט הרי יודע אמיתתה של דבר, ומ\"מ הרי אין כאן האריכות ממש כ\"א מה שמשיג כל הפרטי' כמו שהן בהכלל היינו בהדברים הקצרים ה\"ה משיג את עצם הענין המושכל למעלה הרבה מההשגה שע\"י אריכות הפרטים שתופס בזה רק התפשטות הענין לא העצמי, וכאן הרי תופס את העצמי, ותפיסת העצמי אינו רק בבחי' כללית שאין זה ידיעה והשגה ממש לאמתתו של ענין, וכאן הרי יודע אותו גם מהפרטי' שלו הנעלמים בהדברים קצרים שמאיר אצלו בגילוי, ומה הוא הגילוי ה\"ה העצמי של המושכל כו', דבנקודת ההשכלה כשהוא בדרך כללית לבד יש בזה עצם המושכל אבל אינו יודע עדיין מה הוא, הרי אין זו גילוי והגילוי הוא\nדוקא בהשגת הענין שאז יודע מה הוא, אך הידיעה הוא רק בהתפשטות הענין לא בהעצם, אבל כאשר בהדברים הקצרים יודע הוא את הנעלם ונרמז בזה ולא שבא ונכנס בהפרטים כ\"א מה שבהמועט יודע את המרובה ה\"ז אצלו בגילוי ממש שהרי יודע את הענין מה הוא,"],[3601331040,"והגילוי הוא העצמי כו'. וכמו\"כ יובן בנקודת ההשכלה כשנרגש בזה גם הפרטים ה\"ז ידיעת אמיתתו של הענין (יותר מכמו שהוא בנקודה כללי' לבד כו' כנ\"ל), וגם יודע ומרגיש איך ומה הוא כו', והידיעה היא בגוף ועצם הענין המושכל עוד ביותר מבהדברים קצרים הנ\"ל שזהו קיצור הבא לאחר האריכות כו' (דגבי המשפיע הי' הענין תחלה באריכות ומשנה לתלמידו בדרך קצרה כו', והרי אינו דומה דברים הקצרים האלו להנקודת ההשכלה בעת שהשכיל את הענין שהאיר אצלו עצם המושכל, ואח\"כ כשבא אצלו בענינים פרטי' הרי נתעלם עצם המושכל כו', וא\"כ אח\"כ כשמביא את הענין בדברים קצרים אין בזה גילוי העצמי כמו שהי' בנקודת ההשכלה כו', וגבי המקבל הרי זה מה שמקבל מזולתו ומשיג בחוש ההשכלה וההשגה שלו לא שהוא בעצמו השכיל את הענין כו'), אבל בנקודת ההשכלה שזהו הברקת וראשית התגלות השכל הרי מאיר בזה העצמי יותר הרבה מבהדברים קצרים כו', ויודע את העצמי כמו שהוא לאמתתו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע דהנה משארז\"ל לעולם ישנה אדם לתלמידו בדרך קצרה זהו בבחי' מועט המחזיק את המרובה, והרי המקבל תופס בזה את העצם אבל אינו יודע אותו, וכשיודע אח\"כ מהאריכות הרי תופס רק את ההתפשטות אבל אם בהדברים קצרים יודע את המרובה המוחזק בזה הרי יודע את הענין ומה הוא תופס בזה הרי את העצמי, שהרי לא נכנס כלל אל אריכת הפרטים, כ\"א שבהדברים קצרים יודע הכל, וכמו\"כ הו\"ע נקודת המושכל ועוד שמאיר בזה העצמי יותר מפני שזהו קודם שבא אל הפרטים (משא\"כ בדברים קצרים הנ\"ל) ושהשכיל הוא בעצמו בכח חכמתו.</span>\n<b>תג)</b> ויובן מזה ענין הכוונה פנימי' שבמוח דהיינו מי שיש לו חוש ההשכלה באלקות לידע את הענין האלקי בנקודת ההשכלה גם מצד הפרטי' שבו ואינו מצטרך להשגת הפרטים (גם בדרך הפשטה שזהו בחי' פנימי' המוחין כו'), כי כבר יודע את הענין בנקודת ההשכלה כמו שהוא לאמיתתו כו', הרי תופס בזה את עצם האור האלקי היינו הנקודה העצמיות שנרגש ומאיר אצלו העצמי בבחי' גילוי ממש כו', והתפעלות הנפש בזה הוא בבחי' התפעלות עצמי למעלה הרבה מהתפעלות המדות גם בבחי' פנימי' שלהם הבאה מבחי' פנימי' המוחין כו', והוא שעצם נקודת המוח ועצם נקודת הלב מתפעל על עצם האלקות הידוע ומושג אצלו בבחי' נקודת ההשכלה כו'. והתפעלות זאת הו\"ע קולו של משה שלמעלה מקול הלוים (דקול הוא התגלות התפעלות הנפש וכמו כל שיר וניגון שבא מהתפעלות והתלהבות הנפש וכמו כל בעלי השיר יוצאין בשיר כו', וז\"ע מזמור שיר ליום השבת וכמ\"ש בכתהאריז\"ל דעיקר השירה הוא בשבת לפי שאז הוא עליית העולמות כו', והעלי' וההתכללות הוא ע\"י שיר וניגון כו', וכן כל התפעלות ועליית הנפש\nהוא ע\"י השיר כו', ובא מכוונה והתפעלות פנימי וכמו שאנו רואים דאיזה פנימי' שבנפש שא\"א לגלות בדבור ה\"ז מתגלה ע\"י השיר וכמו עונג פנימי או אהבה פנימי' ועצמי' כו' (וכמו נשיקין שבא מאהבה פנימי' כמו\"כ הוא בשיר וניגון כו'), וז\"ע שיר השירים שהיא התגלות האהבה הפנימי' והעצמי' דהקב\"ה לכנס\"י וכן מכנס\"י להקב\"ה שבא בשיר דוקא כו', וכן כוונה פנימי' שבמוח ה\"ז בא בשיר וניגון כו', ויש בזה חילוקי מדרי' לפי אופן הכוונה הפנימי' כו'), דשיר"],[3601331041,"הלוים הוא שבא מהכוונה שבמוח (וכידוע דלוים הם בחי' בינה) רק שבא בניגון מסודר לפי אופן הכוונה וכמא' שיודעין לכוון בשיר כו', היינו שיהי' השיר כפי אופן הכוונה כו', וזהו בבחי' פנימי' בינה כו', שהרי אומרים שירה על היין דיין מגלה פנימי' הנפש וכמו נכנס יין יצא סוד כו' (וכמ\"ש במ\"א מה שע\"י היין פניו מאדימין שהוא התגלות החיות פנימי כו'), והיינו בבחי' פנימי' המוחין בהשגת עצם הענין האלקי שלא ע\"י לבושי השגה כו', ומ\"מ ה\"ז בא בניגון מסודר לפי שבא מהשגה עכ\"פ, וכנ\"ל פ' ת\"א דגם פנימי' המוחין ה\"ז השגת פרטי הענינים רק בבחי' השגה פנימי' כו', וע\"כ גם השיר והניגון בא בתנועות מסודרות כו'. אבל קולו של משה הוא בחי' השיר שבא מהכוונה פנימי' שבמוח שהוא בעצם נקודת המושכל, ועם היות שיש בזה ג\"כ הרגש הפרטים הרי כ\"ז הוא בעצם הנקודה כו', וההתפעלות בזה היא התפעלות עצמית נקודת המוח ונקודת הלב שמתפעל על עצם אור האלקי כו', ה\"ז בא בשיר וניגון בלתי מסודר רק בתנועה א' פתאומית, דהיינו בלתי מכוונת שאינו מסודרת כלל מפני שאין בזה\nפרטים כ\"א באה מעצם הנקודה כו'. וכמו רע\"מ הי' מנגן בכל מיני ניגון בצלותא דהיינו לא בניגון מסודר כו', ופי' בכל מיני ניגון היינו כמו תנועה אחת הכוללת כל מיני ניגון פרטי, וכמו שבהכוונה פנימי' הוא בבחי' הפרטים כמו שהן בעצם הנקודה כו', כמו\"כ הניגון הוא תנועה א' הכוללת הכל כו'. וכוונה פנימי' זאת זהו בבחי' החכ' שהיא בחי' חי' כנודע, רק שזהו לא בחי' ראי' דחכ' שלמעלה מהשגה לגמרי כ\"א בחי' נקודת ההשכלה בבחי' הפנימי' שבה וכמו שהיא בבחי' הפרטי' הנעלמים בה כו'. ויש עוד מדרי' שלמע' מזה והוא בחי' יחידה שבנפש שזה מה שעצמות הנשמה עולה בשיר בבחי' תענוג עצמי שלמעלה מהשגה לגמרי גם לא כמו הכוונה פנימי הנ\"ל שזהו עכ\"פ ידיעת האלקות, וגם זאת היא בחי' ידיעה כמו השגה מאחר שהוא ידיעת הענין בהפרטי' שבו כו' (רק שאינו כמו השגה פנימי' שזהו שהפרטים באים בהתגלות ממש ובציור השגה ממש דהיינו שמשיג את הענין האלקי כו' שאינו תופס בהעצם ממש כו', משא\"כ בהכוונה פנימי' שאין זה בבחי' השגה ממש רק ידיעת הענין מהפרטים שבו וכמו קודם שבאו\nלידי השגה שמאיר בהם העצמי כו' כנ\"ל, ומ\"מ ה\"ז ידיעה וכמו השגה כו'), אבל בחי' יחידה הוא בחי' העונג עצמי דעצם הנשמה בעצמות א\"ס כו', וכמו הרשב\"י שאמר בחד קטירא אתקטרנא כו' וכמ\"ש בה' תתהלל נפשי בעצמות הוי' ממש כו' (ומה שיכול להיות ממדרי' זו בכ\"א מבו' בקונט' ההתפעלו' שזהו שכאשר שומע איזה ענין אלקי תדבק נפשו האלקי' ותמשך מאליו וממילא גם שאינו מבין כלל כו' שזהו רק מפני שיש לו תענוג עצמי באלקות מבחי' יחידה שבנפש כו', ער האט בעצם א געשמאק אין אלקות שזהו סיבת הדביקות שנדבקה נפשו בזה גם שאינו מבין כו', ומ\"מ זהו דוקא כאשר שומע איזה השגה אלקית, כי זהו מה שמבחי' יחידה נמצא בבחי' המוחין שהתענוג העצמי באלקות (דער גישמאק) הוא במוחין דמשו\"ז תדבק ותמשך נפשו כו').\n<span data-k=\"ks\"><b>קיצור.</b> וז\"ע פנימיות הכוונה שבמוח, והוא בחי' פנימיות החכ' שבנפש, רק לא בחי' ראי' כ\"א שכלי, אך עצם המושכל באלקות, שתופס בזה עצם האור האלקי, ומתפעל בעצם נקודת המוח והלב בבחי' עלי' ודביקות בעצם</span>"],[3601331042,"<b>האלקות</b>, והו\"ע קולו של משה (דכל עלי' ודביקות הוא בשיר וניגון שבזה מתגלה האהבה והדביקות פנימי, והו\"ע שה\"ש), דשיר הלוים הוא מהשגה פנימיות דבינה, דלהיות שזהו השגה, ה\"ז בשיר מסודר, וקולו של משה היא תנועה א' פתאומית, וזהו רע\"מ הי' מנגן בכל מיני ניגון בצלותא תנועה א' הכוללת הכל, וזהו בחי' חי', ולמעלה מזה בחי' יחידה, שהיא עליית הנשמה בבחי' שיר פשוט, והוא דביקות עצם הנשמה בעצם א\"ס, בחד קטירא אתקטרנא, בה' תתהלל נפשי, והוא שתדבק נפשו בהשגה אלקית מפני שיש לו בעצם טוב טעם באלקות (ובעבודה הו\"ע אהבה בתענוגים מה שעצם נפשו מתענג על עצם אלקות למעלה מבחי' העונג דנקודת המושכל הנ\"ל).\n<b>תד)</b> ובכ\"ז יובן ענין התחברות שרש הנשמה עם הנשמה שבגוף כו', דהנה הנשמה המלובשת בגוף הוא בחי' נר\"ן דנשמה היא בחי' השגה כו', אמנם בחי' פנימי' המוחין וכ\"ש בחי' הכוונה פנימי' שבמוח זהו שרש ומקור הנשמה, שהרי מדרי' אלו זהו בנשמות דאצי' כו', וכמשנת\"ל פ' שצ\"ט דפנימי' המוחין זהו בנשמות דאצי' שבבי\"ע והכוונה פנימי' הנ\"ל פ' ת\"ג זהו בנשמות דאצי' ממש כו', וכן בכל נשמה הוא בחי' אצי' שבה בחי' מקיף דחי' כו', ומ\"מ ה\"ז בא כפי חוש הנשמה שבגוף דהיינו בנקודת ההשכלה דוקא לא בבחי' ראי' דחכ' כ\"א בהשכלי דחכ', וגם בבחי' ידיעה מהפרטי' שזהו כמו השגה כו', וזהו התפעלות הנפש בגוף נקודת המושכל דזהו דוקא כאשר נקודת ההשכלה אצלו לא בבחי' נקודה כללי' לבד כ\"א שנרגש בה גם הפרטי' דהיינו ידיעת הענין מהפרטים קודם שבא לידי השגה (והוא שהנקודה גופא היא אצלו בהתרחבות כו'), כי כאשר נקודת ההשכלה היא בבחי' כללי' ה\"ז רק התבוננו' כללי' וידוע שאין זה התבוננות אמיתי כו', אבל הכוונה פנימי' שבמוח הוא למע' מהתבוננות פרטי' כי א\"צ\nלהפרטים דבנקודת ההשכלה ה\"ה יודע את הפרטים, וה\"ז כמו השגה ולמעלה מזה כו' (וגם בחי' יחידה שבאה בבחי' הדביקות בענין אלקי ששומע גם שאינו מבין כו'), ה\"ז מה ששרש ומקור הנשמה מאירה בהנשמה המלובשת בגוף כו', וי\"ל שזה בא לאחר שמגיעים לבחי' שרש ומקור הנשמה, והיינו בהסולם דתפלה דראשו מגיע השמימה שבא לבחי' רעו\"ד כו', אז ביכולתו לבא למדרי' זו שתהי' עבודתו בבחי' פנימי' המוחין (בבחי' רוח רעש ואש פנימי ועצמי בלתי מורגש וניכר כו') ובבחי' כוונה פנימי' שבמוח כו', וגם זאת שיהי' לו תענוג עצמי באלקו' (א עצם גישמאק אין אלקות) גם שאינו מבין ומשיג כלל כו'. וז\"ע אדם א' דם דא' הוא בחי' א\"ס אלופו ש\"ע היינו בחי' א\"ס שבנפש שזהו שרש ומקור הנשמה כו', ובא בבחי' דם שזהו הנשמה המלובשת בגוף כו', דדם הוא בחי' בינה דאהי' ברבוע כו', וכמשנת\"ל פ' שצ\"ח דמוח בינה מתפשט בחלל השמאלי שבלב כו' (ועמ\"ש בלק\"ת ד\"ה לסוסתי ברכבי הא' דדם הו\"ע האורות המתלבשים בכלים כו' וזהו בחי' בינה כו', וכמ\"ש במ\"א דחכ' היא למעלה מהכלים והיא מדרי' הד' שבאור\nכו') והיינו הנשמה המלובשת בגוף כו', וא' דם הוא התחברות שרש הנשמה שמאירה בבחי' או\"פ בנשמה המלובשת בגוף כו', והוא שהכחות פנימי' נעשים במדרי' נעלית ביותר ע\"י גילוי העצמות בהם וכמו בכוונה פנימי' שבמוח ובתענוג עצמי שבמוחין כו', וזהו בחי' אדם כו'."],[3601331043,"<b>ועפ\"ז</b> יובן מ\"ש וידבר אלקים כו' ויאמר אליו אני הוי', דהנה הוי' ואלקים זהו אצי' ובי\"ע, וכנודע דעולמות בי\"ע הן ש' אלקי' וכמ\"ש בראשית ברא אלקים כו' ואצי' הוא ש' הוי' כו', ותכלית הכוונה הוא שיהי' חבור הוי' ואלקים דהיינו שהש' הוי' יאיר בגילוי בש' אלקי' והוא התחברות האצי' עם בי\"ע כו', וזהו ע\"י התורה כדאי' במד\"ר ע\"פ כל אשר חפץ ה' עשה משל למלך שגזר שבני רומי לא ירדו לסוריא ובני סוריא לא יעלו לרומי עמד ובטל הגזרה, כך מתחלה השמים שמים לה' והארץ כו', עמד ובטל הגזרה ואני המתחיל וירד ה' על ה\"ס ומשה עלה כו', וזהו שע\"י נעשה התחברות אצי' עם בי\"ע והוא שבי\"ע יהי' כמו אצי' כו', וזהו שהמשיך משה שהכלים דבי\"ע יהיו בבחי' איהו וגרמוהי חד כמו הכלים דאצי' כו' וכמ\"ש בתו\"א ד\"ה בעצם היום הזה יצאו כו'. וזהו שהודיע למשה באומרו וידבר אלקי' אל משה כו' אני הוי' דהכוונה הוא שהוי' יאיר בש' אלקי' ויהי' האלקי' כמו הוי' כו', ולזה צריכים הקדמת יצי\"מ כו', וזהו ג\"כ לכן אמור אל בנ\"י אני הוי' להיות גילוי ש' הוי'\nכו'. וזהו וארא אל אברהם כו' ושמי ה' לא נודעתי להם, דמ\"ש ש' הוי' אצל האבות זהו בחי' אצי' שבבי\"ע לא בחי' אצי' ממש כו', וגם מה שהאבות המשיכו מבחי' אצי' לבי\"ע וכמשנת\"ל דהמשכת האבות הי' מאצי' (שמלאו החסרון דבחי' מל' כו' כמשנת\"ל באורך) לא הי' באופן כזה שבי\"ע יהי' כמו אצי' כו', וזהו דאברהם אברהם פסיק טעמא בגווייהו דנשמת אברהם בברי' אינה כמו באצי', וזהו דברי' אינו כמו האצי' כו', והיינו לפי שלא המשיכו מבחי' עצמות האצי' רק מבחי' בי\"ע שבאצי' כו', אבל משה משה לא פסיק טעמא בגווייהו מפני שהמשיך מבחי' עצמות אצי' בבי\"ע להיות בי\"ע כמו אצי' כו'. וזהו וידבר אלקים אל משה ויאמר אליו אני הוי', שאין זה שהודיע לו את השם הוי' שזהו הי' כבר ידוע למשה ולישראל, רק הודיע לו דתכלית הכוונה הוא להיות התחברות ש' הוי' עם שם אלקים דהיינו שאלקים יהי' כמו הוי' כו', דבנפש הוא התחברות הנשמה שבגוף עם שרש הנשמה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו התחברות שרש הנשמה עם הנשמה שבגוף, דפנימיות המוחין ה\"ז ג\"כ למעלה מהארת הנשמה המלובשת בגוף, וכ\"ש הכוונה פנימיות שזהו אצי' שבנשמה בחי' חי', ויחידה בחי' עצם הנשמה, ומ\"מ הכוונה פנימיות היא בבחי' שכלי, וגם בחי' יחידה הנ\"ל הוא בבחי' חוש השכל והחכ' (וי\"ל שזהו מה שעצם הנפש הוא בחי' חכ' וכמשנת\"ל פ' ר\"ג) וז\"ע ההתחברות, וי\"ל שכ\"ז בא אחר בחי' רעו\"ד, וז\"ע א' דם, דם בחי' חיצוניות בינה, והיא הארת הנשמה שבגוף, וא' הוא בחי' א\"ס שבנשמה, שכשמתחברים זהו בחי' אדם. ובזה יובן מ\"ש וידבר אלקים כו' אני הוי' התחברות הוי' באלקים גילוי בחי' אצי' בבי\"ע דהיינו התחברות שרש הנשמה והנשמה שבגוף.</span>"],[3601331044,"<h3>בס\"ד. ש\"פ בא, העת\"ר</h3>\n<b>ויאמר</b> ה' אל משה בא אל פרעה כי אני הכבדתי את לבו כו', ומשמע דכי אני הכבדתי את לבו ה\"ז נתינת טעם על מ\"ש בא אל פרעה, וצ\"ל מהו הנתינת טעם בזה. ובזהר דל\"ד ע\"א אי' לך אל פרעה מיבעי לי' מהו בא, דאעיל לי' אידרין בתר אידרין לגבא תנינא חדא עילאה תקיפא דכמה דרגין משתלשלין מיני' כו', וצ\"ל מה\"ע בא אל פרעה לגבי תנינא חדא עילאה כו', ומהו דאעיל לי' אידרין בתר אידרין כו'. ולהבין זה ילה\"ק משנת\"ל דאדם הוא א' דם ובכללות הוא הנה\"א והנה\"ב דנה\"ב נק' דם דכי הדם הוא הנפש ונה\"א נק' א' להיותו אלקות והוא חלק הקב\"ה כו', וההתחברות דא' דם הו\"ע שלום בפמשמ\"ט דהנה\"ב מתחבר עם הנה\"א ונעשה כלי לאלקו' כו', ובנשמה גופא ענין א' דם הוא הנשמה המלובשת בגוף שזהו מבחי' מוח בינה המתפשט בחה\"ש שבלב המלא דם והו\"ע אהי' בריבוע בגימט' דם כו', וא' הוא שרש הנשמה שזהו בחי' א\"ס שבנשמה, וההתחברות הוא שתתחבר הנשמה שבגוף עם שרש הנשמה שנעשה עילוי בהנשמה שבגוף מבחי' שרש הנשמה והיינו שהכחות פנימי' נעשים בעילוי יותר ע\"י גילוי העצמות בהם כו'.\n<b>תה)</b> והנה אופן ההתחברות דהא' עם הדם שזהו התחברות האדם עם אלקות ביאר באו\"ת) והקב\"ה עשה כמה צמצומים דרך כמה עולמות כדי שיהי' אחדות עם האדם שלא יכול לסבול את בהירתו (דבכדי שהאדם למטה יהי' ביכולתו לקבל את האור אלקי צ\"ל כמה צמצומים דרך כמה עולמות כו'. והענין הוא כמשנת\"ל פ' שפ\"ד דהאוא\"ס שלפני הצמצום הגם שהוא בבחי' שייכות אל העולמות מ\"מ אינו בערך העולמות שיהי' בהם בבחי' אור וחיות פנימי, כ\"א ע\"י הצמצום שהי' באוא\"ס ונמשך קו דק וקצר שהוא בבחי' או\"פ כו', אמנם מ\"ש שלא יכול לסבול את בהירתו הכוונה היא גם על האו\"פ היינו אור הקו שאין האדם יכול לקבל את האור והגילוי מצד עוצם הבהירות כו', וצ\"ל כמה צמצומים בהאו\"פ והוא צמצום דא\"ק וצמצום הדיקנא וכמ\"ש בסש\"ב ח\"ב פ\"ט בהג\"ה, והצמצומים צ\"ל דרך העולמו' דוקא שבזה מתעלם האור כו', דהרי הצמצום הראשון זהו רק שהי' הצמצום באוא\"ס ב\"ה ונמשך אור הקו בבחי' גילוי ממש ולא הי' בזה התעלמות האור כו', והגם שהצמצום גופא הוא סילוק והעלם האור כו' הנה זהו בהאוא\"ס גופא\nשנתעלם האור, וההתעלמו' הוא שמתעלם בעצמות האור לא שנתעלם באיזה דבר כ\"א מה שנתעלם במקורו כו', ואח\"כ כשנמשך הקו ה\"ז גילוי אור בלי התעלמות כו', והגם שנכלל האור תחלה בנקודת הרשימו שהיא נקודה העלמית כו', וידוע דרשימו הו\"ע האותיות כו', מ\"מ זהו האותיות דאוא\"ס שלפני הצמצום כו', וכמא' גליף גליפו בטה\"ע שגם לפני הצמצום היו אותי' אלו ונתגלו ע\"י הצמצום כו', ועם היות שע\"י הצמצום נעשו בבחי' מציאות אותיות כו', דקודם הצמצום לא היו בבחי' מציאות כלל וע\"י הצמצום נעשו בבחי' מציאות כו' וכמ\"ש במ\"א, מ\"מ הרי אין זה התהוות דבר וכמ\"ש במ\"א שזהו רק מה שנתגלה בחי' המציאות כו', שע\"י העלם האור נתגלה בחי' המציאות כו', ולהיות שזהו האותיות דלפני הצמצום ע\"כ מה שנכלל האור"],[3601331045,"בנקודת הרשימו אין זה העלם עדיין כו', וגם מה שנמשך בבחי' קו שזהו כדוגמת ההמשכה דרך שערות כו' וכמ\"ש בזהר האי חוטא כו' אקרי מזל כו', הרי כ\"ז הוא כמו שנמשך מלמעלה מאוא\"ס שלפני הצמצום, רק להיות שההמשכה היא דרך דילוג הצמצום ה\"ז כמו המשכה דרך שערות כו', וכמו השערות שהן דרך הפסק הגולגולת כמו\"כ הקו שנמשך דרך דילוג הצמצום ה\"ז כמו המשכה דשערות כו' (ובאמת לגבי אוא\"ס ה\"ז ג\"כ התעלמות אבל להיות שאין זה בבחי' התהוות דבר הרי האור מאיר בגילוי ממש כו'). אבל כשנתהווה בחי' א\"ק שזהו בחי' התהוות דבר כו' ונק' בריאה דכללות כו', ה\"ז בחי' העלם הראשון שהאור הקו מתעלם בו כו', שזהו כל ענין התהוות העולמות בשביל שיתעלם האור כו', שהרי תכלית הכוונה הוא שיהי' בחי' אור וגילוי כו', רק בכדי שיהי' האור בבחי' גילוי היינו שיהי' באפשר לקבל את האור ע\"ז הוא התהוות העולמות בבחי' מציאות והו\"ע התהוות הכלים כו', בכדי שיתעלם האור ויהי' באפשר לקבל כו' (וע\"ד מ\"ש במ\"א בענין וברכך ה' אלקיך בכל אשר תעשה כו' דלכאור' למה צריכים לעשי' מאחר\nדוברכך ה' אלקיך כו', והענין הוא דצריכים לבוש העשי' בכדי שיהי' החיות באופן כזה שיהי' בבחי' חיות אל האדם כו', דבלא לבושים יהי' חיות רוחני וכמו מזון המלאכים שהוא ג\"כ מזון אבל אינו בערך האדם להיות מזון אליו, וע\"ז צריכים לבושי העשי' כו', דבאמת ברכת ה' היא תעשיר והעשי' היא רק כלי לבד, רק שע\"י הכלי עי\"ז נעשה האור באופן כזה שיהי' בבחי' חיות אל האדם כו', וזהו ג\"כ ענין התהוות העולמות שנתעלם בהם האור שיהי' בערך הנבראים שבהעולם כו'), וההעלם הראשון הוא בחי' א\"ק כו'. וידוע דא\"ק הוא ממוצע בין אוא\"ס לעולמות, וענין הממוצע דא\"ק נת\"ל פ' קס\"ה שזהו שהוא ראשית ההתהוות שהכל נתהווה בבחי' א\"ק כו', ועם היות שזהו שאינם בו בבחי' מציאות כלל כו' וכמשנת\"ל שם, מ\"מ מאחר שהכל נתהווה בזה הרי התעלמות האור בא\"ק הוא שיהי' בערך כל העולמות וההשתל' כו', דמאחר שכל העולמות נתהוו בא\"ק הרי בזה שאור הקו מתעלם בא\"ק ה\"ז כללות התעלמות האור שיהי' בערך כל העולמו' וההשתל' כו'. ומ\"מ בא\"ק הוא בבחי' העדר המציאות לגמרי וע\"כ בא\"ק מאיר אור הקו\nבגילוי ממש כו', ואח\"כ בעקודים הוא התחלת הוויות הכלים כו' (ועמשנת\"ל פ' קל\"ב), ועם היותה בבחי' כלי א' מ\"מ ה\"ה בחי' כלי עכ\"פ כו' וע\"כ האור הוא בבחי' עשר אורות כו', והיינו שאינו בבחי' פשיטות לגמרי ושייך בו עשר אורות כו', ועם היות שהן בעקודים בתכלית ההתכללות והאחדות שהן עקודים בכלי אחד כו', מ\"מ ה\"ה עשר אורות כו'. וכן מתעלם האור ממדרי' למדרי' דרך העולמות שנמשך כו', דבנקודים הן עשר אורות בעשר כלים כו', ועם היות שהאור לא הי' בהתלבשות בהכלים, מ\"מ ע\"י אחיזת האור בהכלים הרי נעשה בבחי' מציאות כו' (וכמשנת\"ל באורך בענין תהו ותקון כו'). וכאשר נשברו הכלים דתהו הרי הכלים דתקון הן מה שנתבררו משברי הכלים דתהו כנודע דכלים אלו הן בבחי' מציאות יותר כו', ואינו דומה להכלים שלמעלה מזה שהן רק בבחי' אצי' מאוא\"ס ב\"ה בבחי' המשכה מלמע' כו', משא\"כ כלים דתיקון שהן מבירורים דכלים דתהו הגם שהבירור הי' בדרך מלמעלמ\"ט ע\"י בחי' ש' מ\"ה המברר כו', מ\"מ מאחר שהן מברורים דתהו ה\"ה בבחי' מציאו' יותר והאור מתעלם בהם יותר כו', וידוע שיש כמה עולמות למע' מאצי' וכמו בגולגלתא"],[3601331046,"יתבין תליסר אלפין עלמין כו', שבכ\"ז האור מתעלם ממדרי' למדרי' כו'. וסוד הדיקנא שהן בחי' שערות דמו\"ס שזהו בחי' ש' ב\"ן דמו\"ס המתברר מש' מ\"ה שבו והן הבירורים הנק' דורדי' כו' וכמ\"ש בבה\"ז פ' נשא, וא\"כ אין זה כמו הקו שנק' מזל שזהו בבחי' המשכה מלמעלה, אבל מזלות דח\"ס זהו מהבירורים כו', וא\"כ מתעלם האור ביותר כו', עד שבא האור בע\"ס דאצי' בבחי' ציור אדם בהתלבשו' אורות בכלים כו', דעיקר הכלים הן באצי' והאור בא בהם בבחי' התלבשו' ממש כו', ואח\"כ בסדר ההשתל' דעולמו' בי\"ע שבכל עולם ועולם מתעלם האור עד שנעשה באופן כזה שהאדם יוכל לקבל את האור כו', וז\"ע הצמצום דרך כל העולמות שבהם מתעלם האור כו'. וי\"ל ג\"כ דהכוונה במ\"ש דרך כל העולמות הוא על המשכת האור דרך מסכים ופרסאות שנק' ג\"כ עלמין כו' וכמשי\"ת, וכ\"ז הוא בכדי שיהי' בבחי' אחדות עם האדם והיינו דבחי' א\"ס אלופו ש\"ע יהי' בבחי' התלבשות פנימי בנשמות, דלולא זאת א\"א שיתקבל האור בנשמות למטה, וע\"ז היו הצמצומים דרך כל העולמות בכדי שיהי' האור בבחי' התלבשות פנימי בנשמות שז\"ע\nבחי' אדם כו' וכמשנת\"ל מפ' שצ\"א ואילך. והנה זהו בבחי' המשכת האור מלמעלה שבא בכמה צמצומים בכדי שיוכל להתקבל באדם כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה אופן ההתחברות ביאר באו\"ת והקב\"ה עשה כמה צמצומים דרך כמה עולמות, והוא הצמצומים בהאו\"פ והוא דרך העולמות דוקא, דהנה צמצום הראשון הוא התעלמות האור במקורו, והתעלמות הקו ברשימו ה\"ז בחי' האותיות שלפני הצמצום שע\"י הצמצום נעשה בבחי' מציאות, והקו עצמו עם היותו בבחי' שערות עד\"מ ה\"ז המשכה מלמעלה, אבל העולמות הוא שנתהוו, והכוונה בהם להעלים האור בכדי שיוכל להתקבל, וא\"ק הוא העלם הראשון, ובא\"ק נתהווה הכל כמו\"כ הוא כללות העלם הקו, ובעקודים הוא הוויות הכלי, ודיקנא הוא בחי' שערות שע\"י בירורים (לא כמו הקו), וכלים דאצי' הוא מבירורי שבה\"כ, ה\"ז בחי' העלם האור, וכ\"ז הוא בכדי שיהי' בבחי' או\"פ בנש\"י.</span>\n<b>תו)</b> אמנם בכדי שהאדם יהי' כלי אל האור עז\"א) והאדם צריך לפרוש א\"ע מכל הגשמיות עד שיעלה דרך כל העולמות (ענין הפרישות מכל הגשמיות זהו תחלת העבודה בכדי שיוכל להיות כלי לאור האלקי כו', כי כל איש אשר בו מום לא יקרב כו', והיינו חשכת וחומריות הגוף ונה\"ב המונעים ומעכבים מלהתקרב אל אלקות כו', וצ\"ל תחלת הכל לפרוש א\"ע מעניני החומרי' וכמ\"ש שכחי עמך ובית אביך כו', והיא הכפי' בפועל לצאת מהרגילות שלו בחומרי' בכלל, שהרי האדם בתחלה הוא חומרי, כי הנה\"ב הרי אקדמי' טעניתי' שבא קודם לנה\"א, וכנודע דהתגלות הנה\"א הוא בהיותו בן י\"ג שנה וקודם לזה הוא בהעלם, והנה\"ב הוא בהתגלות כו', וע\"כ הוא חומרי שמוטבע ומורגל בענינים החומרי' שלו, וע\"כ צ\"ל הכפי' בפועל לצאת מהחומריות בכלל, או במי שהוא מורגל באיזה פרט ביותר שמוכרח להיות העזיבה בזה, והיא ההגדרה שמגדיר א\"ע בכח ועוז גם כשאין עדיין גילוי אור בנפשו, הנה מי שמנדבו לבו להתקרב לאלקות (דבאמת זהו חיוב על האדם להתקרב אל ה' ולאהבה אותו וכמ\"ש ועתה ישראל מה ה' אלקיך"],[3601331047,"שואל מעמך כ\"א ליראה את ה' ולאה' אותו כו'), צ\"ל ראשית דבר ההגדרה בענינים שמוטבע ומורגל בהם מצד חומריות הנה\"ב לפרוש מהענינים אלו כו', ועי\"ז ויתאו המלך יפיך בגילוי אור האהבה בתפלה כו' וכמ\"ש בתו\"א בד\"ה רני ושמחי הא'. ואח\"כ בסדר התפלה הרי אין עומדין להתפלל אלא מתוך כובד ראש שהיא ההכנעה והשפלות והלב הנשבר ע\"י שהוא ממארי דחושבנא בפרטי מחדו\"מ שלו ובפרטי נגעי לבבו כאו\"א כפי אשר ידע בנפשו כו', ושעי\"ז נתרחק נפשו מאלקות כו' ואיך שרע ומר עזבו את ה' כו', וידוע שלזה צ\"ל הרגש האלקי וכל מה שירגיש יותר את היוקר דאלקות יהי' מרירות נפשו ביותר על הריחוק מהאלקות כו', ובפרט במה שגרם הכובד גם בהראש והיינו במאן דשרי' על רישי' כו', והו\"ע גלות השכינה שגורם כו', דבכ\"ז יתמרמר נפשו מאד וישבר רוחו בקרבו שזהו שבירת החומרי' לא רק בבחי' יציאה לבד כ\"א שבירת כללות החומריות כו', ולהיות שזהו ע\"י אור וגילוי בנפשו ע\"כ צ\"ל תחלה ענין שכחי עמך הנ\"ל דאז יכול להיות גילוי אור והרגש אלקי בנפשו כו', כי ע\"י היציאה מהחומריות מתגלה בו\nאור הנה\"א שיוכל להיות השגה אלקית ושירגיש היוקר האלקי כו', וגם זאת שהמרירות יגיע ללבבו זהו ע\"י היציאה מהחומרי' כו', וע\"י שבירת החומרי' שבהמרירות שקודם התפלה מתגלה אור נפשו האלקי' ויכול לעלות במעלות התפלה כו', ובסדר התפלה דפסוד\"ז הוא ג\"כ החקיקה מבחוץ ע\"י ההתבוננות בהתהוות יש מאין שעי\"ז מתעלה במעלה עליונה יותר כו' וכמשנת\"ל פ' שצ\"ב, דעלי' זו צ\"ל בבחי' קיום לא רק לפי שעה לבד היינו רק בשעת ההתבוננות דפסוד\"ז, כי בעבודה אמיתית כאשר עושה עלי' בנפשו שמתעלה במעלה העליונה ה\"ה עומד במעלה ומדרי' זו כל היום והיינו שכל היום הוא למעלה מהדברי' החומרי' כו', וזהו לפי שפעל ועשה שבירת החומרי' בהכובד ראש שקודם התפלה ע\"כ עליותיו בתפלה הן בבחי' קיום בנפשו כו', וגם עצם העלי' דתפלה תלוי בהיציאה ושבירת החומרי' והפרישה מהגשמי' כו' כנ\"ל. ואח\"כ יעלה דרך כל העולמות כו', והיינו בסדר והדרגה דבחי' רוח רעש ואש דנה\"א בפסוד\"ז וברכת ק\"ש וק\"ש שנת\"ל מפרק שצ\"ד ואילך שהן בג' עולמות בי\"ע כו' שצ\"ל בסדר המדרי' מלמטלמ\"ע כו', ועי\"ז\nנעשה כלי אל אלקות כו', דבכל מדרי' מהג' מדרי' הנ\"ל הנה ע\"י העבודה שלו כפי אותו העולם נעשה כלי אל האור שנתצמצם בהעולם ההוא כו'. אמנם נר' הכוונה במ\"ש שהעלי' היא דרך העולמות על בחי' אהבת עולם שזהו ביכולת האדם בכח עצמו כו', וע\"ז הוא הצמצום שהאלקות צמצם עצמו כבי' להתלבש בהעולמות כנ\"ל פ' ת\"ה, בכדי שבהאור האלקי שבבחי' התלבשות יוכל להיות עבודת האדם בכח עצמו, וזהו שיהי' עלי' שלו דרך כל העולמות היינו ע\"י האור האלקי המתלבש בעולמות כו', וכידוע דאהבת עולם היא האהבה שנלקחה מהעולמות דהיינו כאשר מתבונן איך שבעולמות יש כח אלקי המהווה את העולמות ומתלבש בתוכם להחיותם וכמ\"ש ואתה מחי' את כולם כו', ומבשרי אחזה אלק' שיש בו חיות המחי' אותו כו', כמו\"כ בכל דבר יש כח אלקי המהווה ומחי' אותו כו', וכמשנת\"ל בפרקים הנ\"ל פרטי ההתבוננות בזה, ועי\"ז יתפעל בלבו באהבה נגלית המושכת את לבו לאהבה את ה' לרצות בהאלקות שבכל דבר (שלא ירצה בחיצוני' וגשמי' הדבר כ\"א בהאלקי כו', שהרי האדם מקבל חיות מהדברים הגשמי', אך להיות שלא על הלחם לבדו יחי' האדם"],[3601331048,"כ\"א על כל מוצא פי ה' כו', וע\"כ אין רצונו לקבל חיותו מהגשמי כ\"א מהחיות האלקי שיתוסף לו חיות עי\"ז בתורה ועבודה כו'), ושיאיר האור האלקי בגילוי בכל דבר כו' (והוא שיהי' התגברות הצורה על החומר כו', והיינו שגם בדבר הגשמי יהי' נראה בהם האלקי יותר מהגשמי כו', שהרי קודם החטא לא הי' העולם גשמי ולא הי' מסתיר על אלקות (אדרבה הי' נראה גילוי אלקות בעולם כו', וי\"ל כמו שע\"י התלבשות אלקות בעולמות עי\"ז דוקא הוא הגילוי דאלקות כו' וכנ\"ל בענין והקב\"ה עשה כמה צמצומים, כמו\"כ העולם התחתון קודם החטא הי' ע\"י גילוי האלקות שנראה ונגלה האור האלקי שראו כל הנבראים מציאות אלקות כו', דבאמת כן גם עתה שהעולם מגלה אלקות למי שנותן דעתו ע\"ז (אז מיא טראגט זעך צוא דער צוא), וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה כו' מרוב אונים ואמיץ כח איש לא נעדר כו', דהתמדת הקיום שלהם א\"א להיות בשום אופן בהנבראים מצ\"ע שה\"ה הווים ונפסדים כו', ורואים בזה כח הא\"ס כאלו רואים בראי' חושי' כו' וכמשנת\"ל פ' של\"ב ושל\"ג, וכמו בהשגחה פרטי' דעל כל פסיעה\nופסיעה רואין השגחתו ית' על כל פרט ופרט כו', וכשיתן דעתו יותר יראה איך שכ\"ז הוא לכוונה מיוחד' והיא כוונה אלקי' הבא מכ\"ז כו', רק שעכשיו צריך ליתן דעתו ולבו לזה, וקודם החטא הי' נראה לכל גילוי אלקות כו'), וע\"י החטא הוא שנתגשם העולם ונעשו עניני העולם דברי תאוה המעוררים תאוות האדם כו', ועם היות שזהו מחומרי' האדם שהרי מי שאינו חומרי אינו מתעורר בתאווה כלל מהענינים החומרי' כו', מ\"מ ה\"ז ג\"כ מצד חומריות וגסות העולם כו', וכאשר יהי' התגברות הצורה כו' הוא שלא יהי' נראה לדבר תאוה ואדרבה שיהי' נראה בו האלקות כו'). וזהו שע\"י ההתבוננות והנחת הענין איך שהאלקות הוא המהווה ומחי' את העולם ה\"ה רוצה בהאלקות שבכל דבר היינו שאינו רוצה בהגשמי להתענג בו בתענוגי בנ\"א ולא לקבל חיות גשמי כ\"א הוא רוצה בהאלקות שבכל דבר, וגם רוצה שבכל דבר יהי' גילוי אלקות כו', ואח\"כ יתבונן איך שכ\"ז הוא הארה לבד כו', שהרי כללות ההתהוות הוא מבחי' מל' דמלך שמו נק' עליהם בחי' שם והארה לבד כו', אבל עצמות אוא\"ס קדוש ומובדל דלכן אני ה' לא\nשניתי כו', ובאמת גם ההארה המתלבשת בעולמות היא קדוש ומובדל מהם (והו\"ע קדוש דנשמות כמשנת\"ל פ' שצ\"ז), דאין זה כמו חיות הנשמה בגוף שנתפסת ממש בגוף ומתפעלת ממקרי הגוף כו', אבל האור האלקי גם שמתלבשת בנבראים אינו נתפס בהם וה\"ה קדוש ומובדל מהם כו', וז\"ע אין קדוש כהוי' שזהו בד\"כ בבחי' אלקות גם בבחי' ממכ\"ע וגם במה שמתלבש בנבראים כו' (ומה שבבחי' תפיסא ממש זהו בהחיות שמבחי' הכלים דבי\"ע כו'), עד שבק\"ש ה\"ה מתבונן בה' א' איך שהוא ית' אחד בז' רק בשמים ובארץ, דהיינו אפי' בהשתל' שמים וארץ רוחני' וגשמי' דעולמו' בי\"ע שהן עולמו' נפרדים ה\"ה מתאחדי' ביחודו ית' כו', כי למעלה מהשתל' שמים וארץ לא שייך לו' עליו ית' ל' אחד כ\"א יחיד שהוא מיוחד בעצם כו', רק מצד ההשתל' שייך לומר ל' אחד דעם היותם בבחי' עולמות ונראים לדבר נפרד הנה זהו רק כמו שנראה לעינינו אבל באמת הם בטלים ומיוחדים כו', וגם לגבי אוא\"ס ה\"ה בבחי' עולמות שנתהוו ומ\"מ ה\"ה כמו קודם שנתהוו מפני שבטלים בתכלית לגבי אוא\"ס ב\"ה כו', ואופן הביטול י\"ל שזהו הביטול דהעדר תפיסת מקום דמשו\"ז הן כלא כו' וכמ\"ש כל דיירי ארעא כלא חשיבי, הרי הביטול"],[3601331049,"דהעדר תפיסת מקום ה\"ז בבחי' ביטול דכלא חשיב כו', ונת\"ל פ' ר\"פ שגם מצד המתבטל הוא שאינו בבחי' מקום וערך בעצמו לגבי הגדול המובדל בערך כו'. והנה מה שהמתבטל אינו תופס מקום בעצמו זהו כשמרגיש את הדבר שממנו הוא בטל, והעולמות הלא אינם מרגישים את האוא\"ס כו', אך הענין הוא שהביטול דה' אחד ה\"ז כמו שהוא בידיעתו ית', והיינו מה שמורגש בהנשמה איך שהוא בידיעתו ית', ובידיעתו העולמות מרגישים את האוא\"ס ב\"ה וא\"כ באותה המדרי' דכל דיירי ארעא כלא חשיבי ה\"ה מרגישים איך שהם כלא וה\"ה בטלים בבחי' העדר תפיסת מקום בעצמם כו', או שהביטול הוא משום דאוא\"ס מאיר לאחר הצמצום כמו לפני הצמצום וע\"כ העולמות בטלים בתכלית כו', וכמשנת\"ל פ' שצ\"ב בהמשל דהשפעת השכל כו'. וז\"ע ה' אחד הביטול דעולמות איך שהן בטלים כו', וזה מרומז בתי' אחד שהח' וד' הן ז\"ר וארץ וד' רוחות העולם דבד\"כ הן ששה קצוות מעלה ומטה וד' רוחות כו', שכולם בטלים לגבי אוא\"ס אלופו ש\"ע כו', הן ו\"ק רוחני' והן ו\"ק גשמי' שמשתלשלי' זמ\"ז וגבוה מעל גבוה כו' כולם בטלים ומתייחדים\nביחודו ית' באוא\"ס ב\"ה השורה בהם ומקיף עליהם כו', ועז\"נ הנה מקום אתי הוא מקומו ש\"ע ואין העולם מקומו כו', שהרי לפניו ית' אינו שייך שום מקום וזמן ומאחר שהוא מקומו ש\"ע וא\"כ הרי גם בחי' המקום וזמן בטל בתכלית שאינם בבחי' מקום וזמן כו'. וכאשר יתבונן היטב בדברים האלה ויהיו נקבעים בלבו אזי לא יחפוץ כלל חפץ ורצון אחר זולתו ית', וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ והן תענוגים גשמי' ותענוגי' רוחני' שהכל הם בבחי' מקום וזמן כו', וכאשר נקבע בלבו איך שאוא\"ס למע' ממקום וזמן ואיך שהוא מקומו ש\"ע שהמקום וזמן גופא בטל ממש עד שאינו בבחי' מקום וזמן כו', אזי לא יחפוץ בכ\"ז רק לדבקה בו ית' לבדו כו', וכ\"ז הוא בחי' אהבת עולם בהתבוננות דפסוד\"ז וברכת ק\"ש וק\"ש שזהו בכח הנברא מצ\"ע כו', ובד\"כ הוא בחי' חיצוני' הלב והיינו בחי' חיצוני' המוחין שנת\"ל).\n<span data-k=\"ks\"><b>קיצור.</b> והאדם צריך לפרוש א\"ע מכל הגשמיות, והו\"ע שכחי עמך ובית אביך, שזהו בתחלת העבודה בכפי' בפועל לצאת מהחומריות הרגילות והטבעית, ואח\"כ בכל יום בכובד ראש קודם התפלה במרירות והכנעה וע\"י הרגש האלקי ממה שנתרחק ואח\"כ בפסוד\"ז בחקיקה מבחוץ, עד שיעלה דרך כל העולמות בחי' רוח רעש אש שהן בי\"ע, ובד\"כ הוא בחי' אה\"ע בהתבוננות האלקות שבעולמות, ועי\"ז ירצה בהאלקות שבכל דבר, ושבכל דבר יאיר אור אלקי, שכן הי' קודם החטא שע\"י העולם נראה אלקות וכן גם עכשיו במי שאינו חומרי כ\"כ שנראה אלקות בהשגחה פרטיות, ואח\"ז יתבונן איך שהכל הוא הארה והעצמות קדוש ומובדל, וגם ההארה היא בבחי' קדוש ובק\"ש בה' אחד איך שהעולמות בטלים בבחי' העדר תפיסת מקום, וגם מפני גילוי האוא\"ס ה\"ה בטלים במציאות והביטול היא בהעולמות כי בידיעתו ית' הוא שמורגש האוא\"ס בהעולמות, וכ\"ז הוא העבודה בהאדם בכח עצמו.</span>\n<b>תז)</b> ויהי' אחדות עם הקב\"ה עד שיבוטל במציאות (והיינו בעבודה דבחי' פנימי' המוחין שנת\"ל פ' תי\"ו, והוא בחי' רוח רעש ואש דאצי' שזהו בחי' אחדות הן בבחי' אצי' שבבי\"ע וכ\"ש בבחי' אצי' ממש שזהו בחי' כוונה פנימי'"],[3601331050,"שבמוח שנת\"ל פ' ת\"א, וכידוע דאצי' בכלל הוא עולם האחדות כו', ובנשמה האחדות הוא התחברות שרש ומקור הנשמה שזהו בחי' א\"ס שבנשמה עם הנשמה המלובשת בגוף כו' וכמשנת\"ל. והנה עיקר האחדות בכללות הוא בהאהבה כרשפי אש והוא האהבה שכמעלת הזהב על הכסף כו' שנת' בסש\"ב פ\"נ, דהנה כסף הוא אהבה מל' נכסוף נכספתי כו', אך היא אהבה שבקרירות וכמו האה' טבעית שיש בכאו\"א לדבקה בו ית' בכל לב ונפש כו' וכמשנת\"ל שהכל חפצים באלקות בעצם ובטבע, וכמשנת\"ל פ' שס\"ו בענין אית רצון ואית רצון שיש רצון עצמי וטבעי בנשמה לאלקות רק שאינו מרגיש את הרצון בעצמו היינו בציור אדם שלו שהן הכחות הגלוים כו', מפני כי האהבה וההתקשרות הזאת היא בהעלם בתוך נקודת הלב ונק' בש' אה' מוסתרת כו', וגם היא מוסתרת בלבושי הגוף ונה\"ב המעלימים ומסתירים עלי' כו', ועם היות שאינה מקבלת העלמות והסתרים והיינו שגם בריבוי ההעלמות וההסתרים ישנה להאהבה בעצם וכמשנת\"ל שם, והראי' דגם בפושעי ישראל יש בהם האהבה ומתגלית לעתים כו' כמשנ\"ת שם, מ\"מ הרי אינה נרגשת בו כלל כו', ועם\nכי ישנה להאהבה בעצם אינה מונעה את ההעלם דנה\"ב שיכול להיות מ\"מ בריבוי העלמות ביותר ר\"ל, דהאהבה שע\"פ טו\"ד הרי אינה מנחת ההעלמות דנה\"ב אדרבה פועלת הביטול בנה\"ב כו', והאהבה טבעית אינה מונעה ההעלמות כו', וזהו לפי שהאהבה היא בהעלם בנקודת הלב כו', וגם כשהיא בהתגלות במקצת ה\"ה בקרירות שאין בה התפעלות ורשפי אש כו', וכמו באהבת אח ואחות שהוא אה' טבעית ומ\"מ יכול להיות שיהיו מרוחקים זמ\"ז ויהי' פירוד ביניהם, עם היות שהאהבה ישנה גם אז כו', וכן גם באהבת הבן אל האב עם היות שהוא אהבה עצמי' וטבעי' מ\"מ הרי אין האהבה נרגשת תמיד בלב הבן, ויכול להיות בזה ריחוק וכמו אוי לבנים שגלו מעל שלחן אביהם כו', ואינו דומה כמו האהבה ברשפי אש שזהו עד\"מ אהבת איש ואשה שאין בזה שום ריחוק, ואם יהי' בזה ריחוק וכמו אתתא אתתרכית מבעלה כו' אז נפסק אהבתם וכמו בגט פטורין שנק' ספר כריתות שכורת אהבתם כו' (ומהקב\"ה לכנס\"י אינו באופן כזה שגם שדנן בשלוחין ובגירושין מ\"מ אהבתו ית' אליהם וכמ\"ש אי זה ספר כריתות אמכם כו', והיינו שהריחוק הוא רק\nמנש\"י וכמ\"ש הן בעוונותיכם נמכרתם כו' וכמ\"ש במד\"ר משפטים פל\"א), אבל באהבת הבן אל האב הרי האהבה ישנה תמיד ואין בה הפסק כלל ומ\"מ יכול להיות ריחוק כמו זה\"ג כו', וזהו מפני שהאהבה היא בהעלם ובקרירות כו', וגם בהתגלות האהבה כאשר היא מן המיצר וכמו ויצעקו אל ה' בצר להם כו', הן במיצר גשמי מעבודה קשה בשעבוד פרנסה ובביטושים ר\"ל שעי\"ז מתעורר נקודת הלב לה' כו', ופרעה הקריב שהקריב לבן של ישראל לאבשבש\"מ כו', ובפרט בהמיצר ברוחני' שמר לו מאד ריחוקו מאלקו' כו', אם שהוא במה שאין לו שום אור וחיות אלקי בנפשו ואינו מרגיש שום חיות בתורה ותפלה, שגם כשמתבונן בענין אלקי ה\"ז בקרירות מאד שאין בזה שום טוב טעם וחיות ולא שום התפעלות פנימי כו', וכן בעסק התורה הגם שיודע שזהו חכמתו ית' ומתבונן בזה מ\"מ אינו מתפעל בנפשו כו', ומאד צר לו מזה וצועק במר נפשו (אם שהיא בקלא דאשתמע או בצעקה פנימי' בקלא דלא אשתמע ובהתעוררות ר\"ר על נפשו כו') שחפץ ומבקש שתשוב רוחו ונפשו האלקי' אליו ויחי' בחיי האלקות כו', ובפרט כאשר המיצר הוא מההעלמות"],[3601331051,"וההסתרים ומהפגמים אשר פגם בנפשו שהצעקה היא ביותר כו'. ובכ\"ז עם היות שהצעקה היא מנקודת לבו מ\"מ כאשר היא רק ממה שצר לו ואינו מרגיש בזה איך שנתרחק מאור פני מלך חיים כו', והיינו שאין אצלו הרגש אלקי שירגיש מעלת האלקות ויקר תפארת גדולתו ממה שנתרחק כו', אינו מתפעל בנפשו בבחי' רשפי אש הצמאון האמיתי לאלקות, והצעקה היא בקרירות עדיין ואינה בבחינת התפעלות אמיתי בנפשו כו' כי זה רק הרגש עצמו בלא הרגש אלקי כו', והגם שזהו מה שנפשו האלקי' צועקת וצר לה כו', ה\"ז רק חיצוני' הנפש (היינו הרצון שבנפש כו') מפני שזהו כמו שהנה\"א עושה דבר ע\"פ חושי הגוף ונה\"ט כו', שהרי הנה\"א צריך להיות בו רק הרגש האלקי, וא\"כ מה שצועק ע\"ז שלו צר דהיינו בהרגש עצמו ה\"ז כפי חושי הגוף, אין בזה התפעלות פנימי ואמיתי כו' וממילא אינו פועל ישועות נפשו להיות מאיר נפשו באור וחיות אלקי כו'. וע\"כ הוא נשאר במיצר ועוצב זה ואין לו שמחה בנפשו (שזהו סימן על חיות אלקי כו') או שנעשה כמיואש ר\"ל ועמשנת\"ל פ' ש\"א, והסבה לזה מפני שניצוץ האלקי שבו והיינו\nנקודת נפשו מעוטף ומלובש מרצונות אחרים (ויכול להיות שזהו בהעלם והוא מפני שלא טיהר נפשו מח\"נ וכה\"ג, ע\"כ הגם שאינו נמשך אחרי רצונות זרות ומ\"מ עצם נפשו היא נעלמה ונסתרה כו', וכמ\"ש במ\"א בענין איני יודע באיזה דרך מוליכין כו', דעם היות שעובד את ה' בכחות הגלוים במוח ולב מ\"מ יכול להיות אשר עצם נפשו הוא בתוך הקלי' כו', וכ\"ש אם נכווה באש זר בחמימות התאוה הרי ידוע שזה מקרר את הרשפי אש דנה\"א כו' וכמ\"ש בלק\"ת ד\"ה ענין הנסכים), ומצד העלם נקודת נפשו אינו נרגש בו הרגש האלקי כ\"א הרגש עצמו וע\"כ האהבה גם כשבאה בהתגלות ה\"ה בקרירות כו' (כן נ\"ל כוונת הענין בלק\"ת ד\"ה ואשה כי תדור כו'). אבל כאשר האהבה היא ברשפי אש ע\"י ההתבוננות בגדולת א\"ס ב\"ה הממכ\"ע וסוכ\"ע כו' ובפרט בבחי' עצמות א\"ס שלמעלה מסובב וממלא כו' (וכמ\"ש בד\"ה ויושט המלך לאסתר), ה\"ז בבחי' רצון אמיתי ורצון א' לה' לבדו וכמו ואל אישך תשוקתך שאין זה אה' עצמי', ה\"ה אהבה ברשפי אש ואין בזה שום רצון זר כלל כו', כמו\"כ ברוחני' האהבה דרשפי אש אין בזה שום רצון זר כו',\nואין בזה שום צד פירוד ח\"ו ומתקשר ומתאחד באלקות כו', וזהו מפני שאהבה זו היא אה' פנימי' ואמיתית כי אם לא תהי' האהבה באמת הרי אינה אהבה כלל שהרי אינה אהבה טבעית כו', וא\"כ הרי האהבה היא רק כשישנה להאהבה, ואז ה\"ה אהבה אמיתית כו', וגם דבאהבה זו לא יש דבר המפריד כי האהבה דרשפי אש גם דבחי' חיצוני' הלב שנת\"ל פ' שצ\"ח (בחי' אש דברי') נעשה ג\"כ ביטול הרצונות זרות, והוא בחי' אש אכלה אש דהתלהבות רשפי אש דנה\"א (הבאה ע\"י השגה והתבוננות דהיינו בחי' התלהבות פנימי בחי' אהבה כו') שורף ומכלה את האש הטבעי דנה\"ב כו', ובכל פעם שמגביר בחי' אש האלקי ה\"ז מקרר ומכלה את האש הטבעי כו', רק שזה בדרך אתכפי' לבד כו', ובבחי' אהבה כרשפי אש דפנימי' הלב שנת\"ל פ' תי\"ו (בחי' אש דאצי') ה\"ז מכלה את האש דנה\"ב בבחי' אתהפכא חשוכא לנהורא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויהי' אחדות עם הקב\"ה עד שיבוטל במציאות, זהו בבחי' רוח רעש ואש דאצי' ובבחי' כוונה פנימיות שבמוח, והוא בנפש האחדות עם שרש</span>"],[3601331052,"<b>הנשמה</b>, ועיקר האחדות היא בהאהבה כרשפי אש, דהאהבה הטבעית היא בהעלם ואינה מונעת ההעלמות וגם כשהיא בהתגלות ה\"ה בקרירות כאח ואחות, והצעקה מהמיצר דהריחוק אם זהו רק מה שצר לו (שלא יש הרגש האלקי) מה שהנה\"א עושה דבר כפי חושי הגוף ואין זה פנימי ואמיתי, ואהבה ברשפי אש שמהתבוננות ממכ\"ע וסוכ\"ע ועצמות אוא\"ס שמתפעל ברצון אמיתי ואין שום רצון זר המפריד וכאהבת איש ואשה וזה שורף ומכלה את האש זר דנה\"ב.\n<b>תח)</b> והנה ידוע שיש בחי' אש ה' ואש י' (והן בחי' אש שחורה ואש לבנה נהורא אוכמא ונהורא חיוורא דנהורא אוכמא הוא האש הנאחז בהפתילה ששורף ומכלה את הפתילה ונהורא חיוורא הוא האש הלבן שלמעלה מהפתילה כו', והיינו דבחי' נהורא אוכמא זהו בחי' רשפי אש דנשמה השורף ומכלה את האש דנה\"ב כו', ונהורא חיוורא הוא הרשפי אש דנשמה עצמה כו'), והן בחי' גבורות דאימא וגבורות דאבא, דגבורות דאי' הוא שבא ע\"י השגה והתבוננות בגדולת ה' שעי\"ז נעשה בחי' ההתלהבות ברשפי אש כו', דרשפי אש זה בא בהתלהבות מורגשת עכ\"פ, דגם האש דפנימי' הלב שנת\"ל פ' הנ\"ל שהוא טמיר ונעלם בלב מ\"מ הרי הלב בוער ברשפי אש כו' וזהו מפני שהיא בבחי' השגה לבד כו', וע\"כ עם היותה בבחי' אחדות (משום שאין שום דבר המפריד כנ\"ל, וכמו ביחוד איש ואשה שאין דבר המפריד דהוא בבגדו והיא כו' והיינו הלבושי' דנה\"ב שלא יפרידו כו'), מ\"מ ה\"ז כמו שני דברים המתאחדים והאהבה היא כמו לדבר הזולת ממנו כו', והיינו מפני שמה שתופס באלקות זהו ע\"י השגה שאין זה עצם האור האלקי רק כמו\nשהוא מושג כו', ובנפש ה\"ז ג\"כ לא עצם אור הנשמה כ\"א בחי' השגת הנשמה כו', ולמעלה זהו בחי' אצי' שבבי\"ע (וכמשנת\"ל פ' שצ\"ט דהעבודה דפנימי' המוחין הוא מבחי' אצי' שבבי\"ע) שזהו מבחי' הכלים דאצי' כו', וגם באצי' זהו בחי' בי\"ע שבאצי' שמבחי' הבינה ולמטה דשם הוא בחי' הכלים כו', והוא בחי' היחוד דאיהו וגרמוהי, שזהו כמו שני דברים המתאחדים כו'. אבל העבודה שלמעלה מהשגה והיא בחי' כוונה פנימי' שבמוח בגוף נקודת המושכל שתופס בזה בעצם אור האלקי כו' וכמשנת\"ל פ' ת\"א ונמשך ונדבק בעצם אור האלקי כו', הנה הרצוא בזה אינו בבחי' התלהבות והתפעלות מורגשת כלל (והיא בבחי' אחדות ודבקות ממש שנדבק ומתאחד בעצם אור האלקי כו'), וז\"ע אש י' בחי' גבו' דאבא שאינו נק' כלל בשם אש כ\"א בשם אור, וכידוע ההפרש בין אש המזבח לאש המנורה דאש המזבח הוא בחי' אש השורף ומכלה את הקרבן, ואש המנורה הוא בחי' אור המאיר כו', והרי היחוד דאיהו וחיוהי הוא בבחי' יחוד ממש שמתייחדים כדבר א' ממש כו', והיינו מפני שהאור הוא בבחי' אין ע\"כ הוא בבחי' יחוד ממש,\nוכמו\"כ הוא בהעבודה בבחי' כוונה פנימי' שבמוח שתופס בעצם אור האלקי שנעשה בבחי' אין בבחי' ביטול במציאות ממש ומתייחד ממש באוא\"ס ב\"ה כו'. וזהו שיהי' אחדות עם הקב\"ה שזהו בכלל בבחי' האהבה דכרשפי אש, ועד שיבוטל במציאות בבחי' הכוונה פנימי' שבמוח כו'), ואז יקרא אדם (דאדם הוא בחי' השלמות והיינו בחי' א' דם והיינו התחברות שרש ומקור הנשמה עם הנשמה המלובשת בגוף בבחי' אחדות כו', ובזהר בסבא דמשפטים דצ\"ד סע\"ב אי' זכה יתיר יהבין לי' הוי' בשלימו דאתוון כו' דאיהו"],[3601331053,"אדם באורח אצי' דלעילא ואתקרי בדיוקנא דמארי', וכ' הרמ\"ז דעד כאן מדבר באצי' שבבי\"ע כו', וכאן הכוונה על מדרי' אצי' עצמה והיא בחי' נפש דאצי' בחי' מל' שזהו בחי' אדם שעל הכסא שהוא בחי' זכר לגבי בחי' בי\"ע כו', והיינו בכוונה פנימי' שבמוח שזהו בנשמות דאצי' ממש כמשנת\"ל פת\"ג, ובבחי' זו הוא בדיוקנא דמארי' דהיינו כמו בחי' אדם דאצי' דאדמה לעליון, כמו\"כ נשמות דאצי' הן בדוגמא שלמעלה ממש כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש בא אל פרעה דאעיל לי' כו' לגבי תנינא חדא עילאה תקיפא ופי' במק\"מ שזהו בחי' אריך דקלי', והוא בחי' עצמו' הקלי' כו' דכמה דרגין משתלשלין מיני' שזהו התפשטות שלהם כו', והנה גבי משה כתיב ראה נתתיך אלקי' לפרעה בחי' שר ומושל לפרעה לשבור גם את התוקף דעצמו' הקלי' כו', דהרי נת\"ל פ' ת\"ז דבחי' אה' דרשפי אש שורף ומכלה את האש זר דסט\"א כו', וזהו בבחי' התפשטות הקלי', אך משה שהי' עבודתו בבחי' כוונה פנימי' שבמוח שז\"ע קולו של משה שלמע' מקול הלוים כו' כמשנת\"ל פ' ת\"ג, והיינו דמשה הוא מבחי' החכ' כי מן המים משיתיהו והי' בבחי' מ\"ה בבחי' ביטול במציאות ממש כו', ע\"כ הי' ביכולתו לשבור גם תוקף הקלי' כו', ולהיות שהעבודה צ\"ל כסדר המדרי' תחלה בחי' אש דבי\"ע ואש דאצי' שזהו בחי' גבורות דאימא ואח\"כ בחי' גבורות דאבא כו', ז\"ע דאעיל לי' אדרין בתר אדרין שהן מדרי' החיצוני' בחי' התפשטות הקלי' שע\"י העבודה בבחי' אש דבי\"ע וכן בי\"ע שבאצילות הוא שפועל הביטול בבחי' ההתפשטות לבד כו'. וזהו דאי' שם בזהר דמשה\nדחיל ליקרב לי' וקריב רק ליאורין דילי' דהיינו בחי' ההתפשטות לבד כו', אבל כאשר בא לעצם מעלתו ומדריגתו אז ביכולתו לשבור גם עצמות קליפת פרעה כו', ועז\"א כי אני הכבדתי את לבו והיינו דג\"ז מאת ה' הוא שיש בזה כוונה עליונה שעי\"ז יהי' יתרון אור והו\"ע ואכבדה בפרעה ובכל חילו כו', ובשביל זה נתהוו הקליפות, וכידוע הקושי' דלמה היתה זאת מלפניו ית' להיות כל מציאות הקלי' והסט\"א, אך באמת זהו בשביל יתרון האור שנעשה עי\"ז כו', ומשו\"ז יכולים לשבור ולבטל אותן מפני שג\"ז מאת ה' שיש גם בזה כוונה פנימי' כו', ובד\"כ הו\"ע שאין לך דבר חוץ ממנו כו', והתהוותם הוא מבחי' העדר הרצון דדין לא אהני' לי' כו' וכמ\"ש במ\"א, אך מ\"מ יש בזה כוונה פנימי' כו', ומשו\"ז ביכולת לשבור כו', רק שזהו בכחו של משה דוקא, להיותו מבחי' החכ' כו', וכמו מלחמת מדין שהי' צ\"ל ע\"י משה דוקא להיות שמדין הוא עצם בחי' היש דתהו ובכדי לבטל עצם היש זהו ע\"י משה דוקא כו' וכמ\"ש במ\"א, כמו\"כ הוא שבירת קלי' פרעה הוא ע\"י משה דוקא כו', וז\"ש כי אני הכבדתי את לבו שזהו נתינת\nטעם מה שבאפשר לשבור קלי' פרעה משום שאני הכבדתי כו', רק שזה צ\"ל ע\"י משה דוקא כו', וזהו בא אל פרעה לשבור בחי' עצמות הקלי', כי אני הכבדתי את לבו להיות עי\"ז ואכבדה בפרעה ובכל חילו כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה יש אש ה' ואש יו\"ד, אש ה' פנימיות המוחין, אצי' שבבי\"ע או בי\"ע שבאצי' שבזה הוא כשני דברים המתאחדים, ואש יו\"ד הכוונה פנימיות שבמוח בחי' אצי' עצמו, בחי' גבורות דאבא אש המנורה שנק' אור,</span>"],[3601331054,"<b>והוא</b> בבחי' אחדות ממש כמו איהו וחיוהי חד, ואז יקרא אדם בשלימות א' דם בהתאחדות בהקב\"ה, והוא בדיוקנא דמארי' אדמה לעליון. ובזה יובן מ\"ש בא אל פרעה, משה בחי' כוונה פנימיות שבמוח, קולו של משה הי' בכחו לשבור תוקף הקלי' דפרעה."],[3601331055,"<h3>בס\"ד. ש\"פ בשלח, העת\"ר</h3>\n<b>אז</b> ישיר משה ובני ישראל את השירה הזאת לה' ויאמרו לאמר, וצ\"ל מה\"ע אז ישיר והול\"ל וישירו משה ובנ\"י מהו אומרו אז ישיר, גם מה\"ע ישיר דהול\"ל שרו משה ובנ\"י. ובגמ' סנהדרין צ\"א ב' אמרו מכאן לתחה\"מ מן התורה, וצ\"ל מהו שייכות תחה\"מ לקי\"ס דגבי שירת הים מרמז ענין תחה\"מ. גם מהו כל האריכות דאת השירה הזאת ויאמרו לאמר כו'. ובמד\"ר פ' כ\"ג אי' ההד\"ת נכון כסאך מאז א\"ר ברכי' בשם ר\"א אע\"פ שמעולם אתה לא נתיישבה כסאך ולא נודעת בעולמך עד שאמרו בניך שירה, משל למלך שעשה מלחמה ונצח ועשו אותו אגוסטוס כו', מה יש כבוד בין מלך לאגוסטוס מלך עומד על הלוח ואגוסטוס יושב, כך אמרו ישראל להקב\"ה באמת עד שלא בראת עולמך היית אתה ומשבראת עולמך אתה הוא אלא כבי' עומד שנא' עמד וימודד ארץ, אבל משעמדת בים ואמרנו שירה לפניך נתיישבה מלכותך וכסאך נכון הוי נכון כסאך מאז באז ישיר, וצ\"ל מה\"ע דבאז ישיר נתיישבה מלכותך, ומה\"ע נתיישבה מלכותך וכסאך נכון כו'. ולהבין כ\"ז ילה\"ק משנת\"ל בהמא' דאו\"ת והקב\"ה עשה כמה צמצומים שיהי' אחדות עם האדם\nכו', והאדם צריך לפרוש א\"ע מכל גשמי' עד שיעלה דרך כל העולמות ושיהי' אחדות עם הקב\"ה עד שיבוטל במציאות, ונת' שזהו אופן התחברות האדם עם האלקות שזהו ע\"י שהאלקות נתצמצם דרך כל העולמות דוקא היינו דרך הכלים שעי\"ז מתעלם האור ממדרי' למדרי' בהשתל' דעקודים נקודים וברודים שהן כלים דתיקון וכלים דאצי' ובהשתל' דבי\"ע עד שיהי' בערך האדם כו'. והאדם בכדי שיהי' כלי צריך לפרוש א\"ע מכל גשמיות שיהי' בבחי' קירוב לאלקות כו', עד שיעלה דרך כל העולמות בהעבודה דאהבת עולם כו', ושיהי' אחדות עם הקב\"ה בהאהבה דרשפי אש שהוא אהבה פנימי' ובהסרת כל דבר המפריד כו'. ונת' שיש ב' בחי' אש ה' ואש י' שזהו בחי' גבורות דאבא שהוא בחי' ביטול במציאות ממש שבזה מתאחד ממש באוא\"ס כו', ואז הוא בבחי' אדם בשלמות דכמו שאדה\"ע אדמה לעליון כמו\"כ האדם הוא בדוגמא שלמעלה כו', ואח\"ז אומר באו\"ת).\n<b>תט)</b> וזהו ועל דמות הכסא שהוא ית' מכוסה שם (הנה בזה בא לבאר מ\"ש ועל דמות הכסא דוקא דמות כמראה אדם דבחי' דמות כמראה אדם הוא על דמות הכסא דוקא. דהנה ענין מראה אדם הוא שנתצמצם אוא\"ס בבחי' ציור"],[3601331056,"אדם דאצי' דהיינו ע\"ס דאצי' בבחי' התחלקות ובבחי' התלבשות אורות בכלים שזהו שנתחדש בעולם האצילות, דהרי למע' מאצי' אין שם התחלקות ע\"ס עדיין כו', וכמו עד\"מ בכחות הנעלמים שבנפש שאור הנפש מאיר בכולם בשוה כו', וכמו שאנו רואין בהתגלות הכחות הנעלמים כמו בעת השמחה שמתגלים כולם יחד, וכמו התגלות המוחין להשכיל השכלות עמוקות וכן התגלות המדות כו', דבכחות הגלוים הרי בעת התגלות המוחין הוא למעלה מענין המדות, ובהתגלות המדות אינו בבחי' מוחין שהמדות מבלבלים אל המוחין כנודע, ובעת השמחה כולם הם בהתגלות וכולם בתוקף האור והגילוי כו', והיינו מפני שמקבלים כולם מעצם הנפש המאיר בכולם בשוה כו', וכאשר אינן מתגלים אינם במציאות כחות, דעם היות שהן כח החכ' כח הבינה וכח החסד כו', הרי אינם במציאות ניכרות כלל דהכל הוא בבחי' התכללות בעצם הנפש כו'. דכמו\"כ הוא בעולמות הא\"ס שלפני האצי' שהאוא\"ס מאיר בגילוי בכל הספי' בשוה דכולם מקבלים מעצמות אוא\"ס המאיר בכולם בשוה ואין בהם בחי' מיעוט ממדרי' למדרי' כו', דזהו\"ע שלמעלה מאצי' הוא\nלמעלה מהשתל'. דענין השתל' הוא עד\"מ השלשלת שהטבעות אחוזות זו בזו דסוף וקצה של הטבעת העליון הוא בראשו של התחתון כו', שהדמיון מזה הוא ברוחני' שהמדרי' משתלשלות אלו מאלו דחיצוני' שבעליון נעשה פנימי' אל התחתון כו', דבזה בהכרח מתמעט האור אחרי שהתחתון מקבל רק מסוף ומדרי' התחתונה של העליון שזה נעשה בחי' הראש של התחתון כו'. והמדרי' שלמעלה מאצי' ה\"ז למעלה מהשתל' שאינם משתלשלים זמ\"ז והאור מאיר בכולם בשוה כו', וכמו בהכחות נעלמים שאינם מקבלים זמ\"ז שאין הבינה מקבלת מהחכ' וכן המדות אינם מקבלים מהמוחין כו' וכמ\"ש במ\"א, וכמו\"כ הוא במדרי' שלמע' מאצי' שאינם משתל' זה מזה כו', וא\"כ אין כאן ירידת האור כו'. וגם הספי' הן בבחי' התכללות באוא\"ס ב\"ה שאינם במדרי' ניכרות כלל כו', ויש הפרש בין התכללות דא\"ק והתכללות דעקודים כו' וכמשנת\"ל פ' שפ\"ה, אבל כ\"ז הוא בבחי' התכללות כו'. ובאצי' הוא שבאו הע\"ס בבחי' התגלות דז\"ע האצי' בחי' הפרשת הארה מאוא\"ס המאציל דהיינו בחי' הגילוי כו', ואופן המשכתן והתגלותן הוא שמשתלשלים זמ\"ז שעי\"ז\nהוא ירידת האור שמתמעט ממדרי' למדרי' כו', וזהו בחי' ציור אדם דעיקר ציור אדם הוא התגלות הכחות ובסדר והדרגה דוקא כו'. ולכן התחלת פרצוף אדם הוא מהחוטם, וכמארז\"ל אין מעידין אלא על פרצוף פנים עם החוטם, כי מן החוטם מתחיל התלבשות הכחות בכלים בבחינת התחלקות ובסדר והדרגה, וכמו תרין נוקבין דחוטמא תרין עיינין תרין אודנין תרין ידין כו', משא\"כ בפדחת שלמע' מהחוטם אין בו עדיין היכר האדם. וכמו\"כ הוא בציור אדה\"ע שבא בהתחלקות שזהו דוקא בהתגלות הספי' ובהתלבשות בכלים ועי\"ז הוא ג\"כ סדר והדרגה שלהם כו', וזהו בחי' מראה אדה\"ע דאצי' כו' (וזהו שגבי תורה כתי' וממדבר מתנה דמדבר הוא אשר לא ישב אדם שם, והיינו שהתורה היא למעלה מבחי' ציור אדם דאצי' הגם שנא' בה זאת תורת האדם כו' וכמשי\"ת). והכוונה בזה שנתלבש האוא\"ס בציור אדם הוא בכדי שיהי' הגילוי בבי\"ע כו', והיינו שיתהוו עולמות בי\"ע ויהי' בהם ג\"כ גילוי אור אלקי כו', שזהו שעלה ברצונו ית' לברוא את העולם להיטיב לברואיו שיכירו גדולתו כו', והוא שגם נבראים שהן בבחי' יש ומציאות יכירו גדולתו ית' ויהי'"],[3601331057,"בהם גילוי אור אלקי כו', ולהיות העבודה למטה בבחי' אתכפי' חשוכא לנהורא דכך עלה ברצונו ית' להיות לו ית' נח\"ר בזה דאתכפי' סט\"א כו' וכמ\"ש בסש\"ב פ' ל\"ו, שע\"י שהאדם למטה עושה הכפי' בהחומריות שלו נמשך עי\"ז גילוי אלקות וכמא' כד אתכפי' סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין כו', ובפרט כאשר הכפי' היא ע\"י עבודה פנימי' בהשגה והתבוננות אלקי שעי\"ז מאיר אור האלקי בבחי' פנימי' כו', דבד\"כ ע\"י כפי' בפועל נמשך ג\"כ גילוי אלקות ואפשר עוד מדרי' עליונה ביותר, רק שאינו בבחי' פנימי (רק מה שנותן כח כו'), וע\"י עבודה פנימי' שהיא בבחי' גילוי אור בנפשו ועושה בחי' ביטול בהחומריות כו', מאיר בו האור האלקי בבחי' או\"פ כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו ועל דמות הכסא שהוא ית' מכוסה שם, דהנה מראה אדם הוא בע\"ס דאצי', דלמע' מאצי' אינן בבחי' התחלקות, וכמו כחות הנעלמים שבהעלם אינם במציאות ובהתגלות מתגלים כולם כאחת כי אינן משתלשלים זמ\"ז, וכמו\"כ הוא באוא\"ס ולכן נק' למעלה מהשתל', ואצי' הוא גילוי האור ובסדר והדרגה וזהו שמשתלשלים זמ\"ז ועי\"ז מתמעט האור ממדרי' למדרי', והכוונה בשביל התהוות בי\"ע בכדי שיהי' אתכפי' סט\"א שעי\"ז אסתלק יקרא דקוב\"ה, ובכפי' בפועל האו\"מ נותן כח בהפנימי, ובכפי' ע\"י עבודה האו\"פ מאיר בבחי' פנימיות.</span>\n<b>תי)</b> אמנם נת\"ל פ' שפ\"ו דאדה\"ע דאצי' הוא בבחי' אדמה לעליון בחי' כי לא אדם כו', להיות דהתהוות האצי' הוא בבחי' קירוב שז\"ע אצי' ל' אצלו וסמוך כו', וכ' הפרד\"ס שזה מורה על עוצם דבקות הספי' במקורם, והיינו שהע\"ס דאצי' הן בבחי' יחוד באוא\"ס ב\"ה ובבחי' פשיטות שאינם בבחי' מציאות כו', ואין העולמות דבי\"ע יכולים לקבל אור האצי' כו', כ\"א מבחי' המל' דאצילותה היא בבחי' נבדל לא בבחי' קירוב ממש ה\"ז בבחי' גילוי שיכול להיות בבחי' מקור לבי\"ע כו' וכמו שנת\"ל פ' שפ\"ח ושצ\"ה, ומ\"מ מבחי' מל' דאצי' כמו שהיא באצי' ג\"כ אין העולמות בי\"ע יכולים לקבל כ\"א ע\"י הפרסא כו', דכשם שבכללות הגילוים שבעולמות הרי מבחי' מל' דא\"ס כמו שהוא לפני הצמצום (שזהו בחי' מל' דאצי' דכללות) עם היות שהיא בבחי' שייכות אל העולמות (דבחי' מל' גם בשרשה הראשון היא בבחי' נבדל וכמו בחי' התנשאות עצמי שהיא בבחי' כח נבדל כו' וכמ\"ש במ\"א), הרי אין העולמות יכולים לקבל, ובכדי שיהי' בחי' א\"ק אדם דברי' דכללות הוא דוקא ע\"י צמצום בבחי' סילוק האור כו',\nכמו\"כ מבחי' מל' דאצי' א\"א להיות עדיין הגילוי בבי\"ע כ\"א ע\"י הפרסא דוקא כו', דכל הצמצומים אינם מועילים עדיין להיות הגילוי בבי\"ע כו' להיות שהצמצום הוא בבחי' מיעוט האור לבד (והצמצום הראשון להיותו בבחי' סילוק ה\"ז מועיל להיות הגילוי בבחי' א\"ק כו', וכידוע ההפרש בין צמצום הראשון להצמצומים דסדר השתל' שהן בבחי' מיעוט לבד, אבל צמצום הראשון הוא בחי' סילוק האור כו', וצמצום דא\"ק הוא ג\"כ בבחי' סילוק שהעלה אורו למעלה מטיבורו כו' וכמשנת\"ל פ' שפ\"ה, ג\"ז אינו בבחי' סילוק כמו צמצום הראשון ויש בזה כמה חילוקים כו' עמשית\"ל, והצמצום הראשון להיותו בבחי' סילוק לגמרי"],[3601331058,"ה\"ז מועיל להיות התהוות א\"ק כו', וגם שהאור נכלל אח\"כ בנקודת הרשימו דלגבי אוא\"ס הוא נקודה העלמית, ועם היות דלגבי עולמות מפני שזהו ממדרי' האוא\"ס ה\"ז בחי' גילוי כו' וכמשנת\"ל פ' ת\"ה, מ\"מ לגבי אוא\"ס ה\"ז בחי' העלם כו', ומבו' במ\"א שזהו כעין פרסא כו', וא\"כ גם התהוות א\"ק הוא ע\"י צמצום ופרסא כו', ולעיל פ' כ\"ח נת' דלגבי האוא\"ס הבל\"ג הצמצום הוא בבחי' סילוק ולגבי שרשי האורות הוא בבחי' מיעוט כו'). והגם שנת\"ל פ' ת\"ה דהצמצומים הם דרך העולמות שזהו בחי' התעלמות האור כו', הנה התעלמות זאת היא בבחי' הכלים שאין זה העלם ממש, וכידוע בענין הכלים דעם היות שמעלימים על האור ה\"ה ג\"כ מגלים את האור כו', דז\"ע שהן בחי' כלים אל האור דהיינו לגלות אותו, רק שהגילוי הוא ע\"י שמעלימים על פנימי' ועצמי' האור ומגלים את חיצוני' האור כו' (וגם ענין ההעלם שלהם הוא ע\"י שהאור מאיר בגילוי בהכלי שהכלי מקבלת את האור ובזה הוא מתעלם, דהאור שאינו מאיר בהכלי ואינו מתקבל בה שהוא האור מקיף אינו מתעלם ע\"י הכלי כו', כ\"א האור פנימי שמאיר בגילוי\nבהכלי והכלי מקבלת את האור ה\"ה מתעלם ע\"י הכלי כו', וההתעלמות הוא שנעשה עי\"ז כמהות הכלי בבחי' מציאות דבר לא כמהות עצמו שהוא בבחי' אין כו' ועי\"ז אפשר לחיצוני' האור להיות בבחי' גילוי כו', שכ\"ז אינו העלם ממש שהרי הכל הוא בחי' גילוי אלא שבהגילוי גופא הוא מתעלם, והיינו רק שמתעלם מהות עצמו כמו שהוא בעצם לא בבחי' התעלמות ממש כו'. ומ\"מ ה\"ז בחי' העלם יותר מבחי' הצמצום לבד דאוא\"ס שלא ע\"י הכלים, דע\"י הצמצום לבד נמשך האור כמו שהוא בעצם משא\"כ ע\"י הכלים מתעלם מהות עצמו כו', ויובן זה עד\"מ בהשפעת השכל אינו דומה כמו שנמצא חיצוני' השכל אצל המשפיע ע\"י צמצום אור שכל העצמי לכמו שהוא כשמלבישו באותי' ועניני' והסברים שמשפיע אל המקבל, דכמו שהוא גבי המשפיע הרי מאיר בו בחי' הפנימי' (היינו הפנימי' שבחיצוני' השכל) וממילא גם החיצוני' היא בגילוי יותר, משא\"כ כשמלבשו באותי' ובפרט בעניני ההסברים הרי מתעלם הפנימי' וממילא גם החיצוניות אינו בבחי' גילוי כ\"כ כו'. ועד\"ז יובן ההפרש בין בחי' הצמצום דמ\"מ מאיר האור בגילוי כמו שהוא\nובההתעלמות דרך הכלים אין האור מאיר כמו שהוא בעצם כו', ומ\"מ ה\"ז גילוי אור כו'). וכמו\"כ יובן בבחי' המל' שנת\"ל פ' שפ\"ח דבחי' מל' שבכל ספי' הוא בחי' כח הגילוי ובחי' המציאות של הספי', וכמו שהיא בבחי' פרצוף בפ\"ע ה\"ה בבחי' גילוי להיות בבחי' מקור כו', הרי כ\"ז אינו בחי' התעלמות האור ממש כו', וכנודע דבמל' יש ב' מדרי' בחי' ים וארץ דים הוא בחי' פרצוף הפנימי דמל' שכונסת בתוכה האורות דאצי' וכמשנת\"ל בענין כנס\"י ובזה מתעלמים האורות דאצי' כו', ומה שהיא בבחי' מקור זהו בחי' חיצוני' המל' והוא בחי' מקבל ומשפיע שבמל' כו', ומבו' במ\"א שזהו כמשל המתורגמן שמקבל מן הדורש ומשפיע אל העם כו', הרי כ\"ז הוא בחי' גילוי האור ושבזה הוא מתעלם כו', וכמו המתורגמן שמקבל גילוי ההשפעה מהדורש ומתקבל בכלים וחושים שלו ובזה מתעלם ההשפעה שיהי' בערך המקבלים כו', וכמו\"כ הוא בבחי' מל' שמאיר בה גילוי האור, וז\"ע שכונסת בתוכה האורות דהיינו בחי' הגילוי ובזה הם מתעלמים בבחי' מל' כו', וא\"כ ה\"ז ג\"כ ע\"י הגילוי וממילא אין זה העלם לגמרי כו' (ומ\"מ התעלמות האור ע\"י"],[3601331059,"המל' הוא יותר מההתעלמות שע\"י הכלים כו', והוא מפני שהמל' היא בבחי' נבדל ע\"כ הגילוי שבה אין זה בבחי' גילוי ממש כו', וכמשנת\"ל פ' שצ\"ה דהספי' שלמעלה הן בבחי' קירוב שהאור מאיר בהם בגילוי ממש היינו שמתקבל בהכלי בבחי' פנימי' כו', משא\"כ בחי' המל' להיות בבחי' ריחוק בעצם ע\"כ גם גילוי האור שבה אינו בבחי' גילוי ממש שיתקבל בה כ\"א שיתעלם האור בה כו', וה\"ז ג\"כ בבחי' קבלה וקליטה אבל הוא בכדי שיתעלם בה כו', וזהו שהמל' כונסת בתוכה שאין זה שמקבלת בתוכה שזהו שהכלי מקבלת האור לעצמה בתוכה ופנימיותה להיות לה גילוי האור כו', משא\"כ ענין כונסת בתוכה הוא רק שהאור כנוס בה (בבחי' נבדל ממנה) לא שמקבלת בתוכה ופנימיותה ממש להיות לה גילוי האור כו', וע\"כ התעלמות המל' הוא ביותר והיינו שהיא משנה את האור כו', וכמו עד\"מ הלבנה שאור השמש משתנה בה כו', כמו\"כ בבחי' מל' משתנה האור כו', דגם כמו שהן בבחי' שני המאה\"ג מ\"מ הרי אור הלבנה אינו כמו אור השמש כו', משא\"כ בכלים הרי פנימי' הכלים הם רק גווני האור (משום דענינם הוא רק הגילוי\nלעצמן כו') וגם חיצוני' הכלים אינם משנים את האור כו', דעז\"נ כי שמש ומגן ה' אלקים הרי ע\"י המגן ונרתק אינו משתנה אור השמש כו', משא\"כ הלבנה משנה את אור השמש, וכמו\"כ הוא בבחי' מל' כו', וה\"ז כמו ההפרש בין השפעת השכל ע\"י עניני הסברים לכמו ההשפעה ע\"י משל, דהענינים שכלי' שבזה מסביר ומבאר הענין הגם שזהו העלם כנ\"ל מ\"מ אין האור משתנה בזה, משא\"כ בהתלבשות השכל במשל הגם שזהו ג\"כ בכדי שעי\"ז יבין את הענין, דאור שכל עמוק שא\"א להבין ע\"י ההסברים מלבישים אותו במשל שעי\"ז יבין אותו כו', הרי הבנת הענין ע\"י המשל בא מ\"מ באופן אחר כו', וכמו\"כ יובן בבחי' המל' שמשנית את האור כו', ומ\"מ אין זה התעלמות לגמרי כו'). אך ענין הפרסא הוא שהאור מתעלם לגמרי שהרי הפרסא היא כמו אותי' הבלתי מסודרים שאינם כלים אל האור, וא\"כ הרי התלבשות האור בהפרסא אינו בחי' גילוי אור רק התעלמות לבד כו', וע\"כ האור מתעלם לגמרי ע\"י הפרסא כו' (ועמשנת\"ל ד\"ה תקעו הב').\n<span data-k=\"ks\"><b>קיצור.</b> אמנם אדם דאצי' אדמה לעליון, דאצי' הוא האור הדבוק במקורו והתעלמות האור בהכלים הרי זהו ע\"י שמאיר בגילוי בהכלי, והכלי מקבלת האור, ולכן ההתעלמות היא רק שאינו כמהות עצמו כ\"א כמהות הכלי, והכלי מגלה את האור, ומ\"מ ה\"ז יותר מע\"י שנתגלה בחי' חיצוניות האור כמו שהוא, וכמו מציאות האור שכל ע\"י צמצום המשפיע לכמו שבא בלבושי' והסברים, וגם חיצוניות הכלים אינם משנים את האור וכמו נרתק השמש, משא\"כ הלבנה שמשנה, וכמו\"כ הוא בחי' מל' להיותה בבחי' נבדל, ומ\"מ מבחי' מל' עצמה אין העולמות יכולים לקבל (וכמו בבחי' מל' דא\"ס שלפני הצמצום דע\"ה בבחי' שייכות להעולמות א\"י לקבל משם), דבפנימיות המל' מאיר גילוי האור וז\"ע כנס\"י ובזה הוא מתעלם (ומ\"מ א\"ד להגילוי בכלים שהוא בבחי' גילוי ממש ובמל' הוא בכדי שיתעלם וזהו כונסת לבד), וכל הצמצומים אינם מועילים להיותם בבחי' מיעוט (ותועלת הצמצומים הוא שיוכל להיות התעלמות הפרסאות וזאת שיהי' מ\"מ גילוי אור, וממילא יוכל להתרחב) (והצמצום הראשון שבבחי' סילוק מועיל להתהוות א\"ק), ורק ע\"י בחי' פרסאות יוכל האור להתקבל בעולמות.</span>"],[3601331060,"<b>תיא)</b> וביאור הענין הוא דהנה אי' בע\"ח שער דרושי אבי\"ע שבכל עולם יש ד' מדרי' והן אורות וכלים ולבושים והיכלות, והן ד' אותי' הוי' והן בחי' אבי\"ע שבכל עולם כו', האורות הן בחי' אצי' שבכל עולם דגם בבי\"ע בחי' אור הנשמה הוא בחי' אצי' שבבי\"ע כו', והכלים הן בחי' ברי' שבכל עולם דגם באצי' בחי' הכלים הם ברי' שבאצי' כו', והאורות וכלים הם מיוחדים זע\"ז דעם היות שהכלים הן בבחי' ברי' לגבי האור שזהו בחי' האצי' כו' מ\"מ ה\"ה בבחי' יחוד כו', ולבושי' והיכלות הם נפרדים כו', וצ\"ל ההפרש שבין כלים ולבושים והיכלות כו'. והענין הוא דהנה אי' בהקדמת ת\"ז איהו וחיוהי חד איהו וגרמוהי חד הרי כשם שהאורות מיוחדים באוא\"ס המאציל כמו\"כ הכלים מיוחדים בהאורות כו' (ונא' ב\"פ חד מפני שאינו דומה אופן יחודם כידוע ומ\"מ ה\"ה חד כו'), דהנה ענין אורות וכלים הוא שהאור מאיר בגילוי בהכלי ומתלבש בתוכה והכלי סובל את האור ומתאחד בו כו', דעם היות שהאור והכלי מרוחקים זמ\"ז שהאור הוא בחי' אין והכלי הוא בחי' יש וכמשנת\"ל באורך, מ\"מ האור מתלבש בהכלי\nבבחי' או\"פ בגילוי ממש והכלי סובל ומקבל את האור (ופי' סובל לפי שהכלי היא שלא בערך האור הנה קבלת האור הוא בדרך סבלנות, דמה שהוא בערך זל\"ז הרי יכול לקבלו, אבל שני דברים שהם כמו הפכים הרי הקבלה שהכלי מקבל את האור ה\"ז שסובל אותו כו') ומתאחד בו עד שאופן התגלות האור הוא כפי אופן הכלי דוקא כו'. ויובן זה עד\"מ באדם למטה דבצלם אלקי' דאדה\"ע עשה את האדם כו', להיות ידוע דמה שנק' בל' המקובלים אור וכלי היינו הנק' חומר וצורה שהחומר סובל הצורה ומתאחד בה והיו לאחדים עד שאופן הצורה רק כפי מזג החומר, והחומר נדבק ונגרר אחר הצורה (והוא ביטול החומר אל הצורה שעי\"ז היא בבחי' כלי אל הצורה הרוחני' כו') והצורה בלתי נפרדת ממהות החומר שלה שמתגלה בה ופועלת כפי החומר דוקא כו', וכמו חומר כלי העין שסובל בעצמו כח הראות הרוחני והוא להיותו עצם ספירי ה\"ה חומר מוכן לקבל הצורה דראי' הרוחני', ולפי מזג טבעי' כלי העין בשחור ולבן שבה כך יהי' אופן הראי' אם בבהירות או בעכרורית כו', וכמו אור השמש המאיר ע\"י זכוכית לבנה או אדומה הרי\nכפי גוון הזכוכית כך הוא גוון האור (רק ששם הרי הגילוי הוא רק מצד האור ורק ע\"י עברת הזכוכית נעשה הגוון כפי גוון הזכוכית שהרי הזכוכית אינה מביאה ומגלה את האור (ער רופט ניט ארויס דעם אור) וממילא אינה פועלת בו מאומה רק מה שנראה בגוון זה כו', וכאן הרי המגלה את האור הוא החומר כי בלא חומר העין לא הי' גילוי כח הראי' בעצמו רק ע\"י החומר דוקא שהוא הממשיך את אור הראי' וכידוע שאברים ממשיכים חיות כו', והוא המגלה אותו כו', וע\"כ מגלה אותו כפי אופן החומר כו'), וזהו בגשמיות. וכמו\"כ בפקיחת העין לדין ולחסד שנק' טוב עין או רע עין, ג\"ז תלוי במזיגת כלי העין אם מבחי' החסדים או מבחי' הגבורות (דהיינו בהמזיגה והרכבה שלו אם בריבוי דמים או שהמים מתגבר על הדם כו'), וכמו שהאיש החסד והטוב יביט על כל דבר בעין טובה ולהיפך איש הדין יביט בעין רע כו' (דזה גופא הוא לפי החומר דהמרובה בדמים הוא איש הגבו' ע\"פ הרוב, וכאשר מזיגת החומר הוא בהתגברות המים על הדם הוא ע\"פ הרוב איש הטוב כו'), הרי שבחי' חו\"ג הרוחני' השכלי' שבראי' תלוי' במזיגת גשם חומר העין בטבעם כו'. וכך בכלי המוח שגם הוא חומר גשמי לגבי אור השכל"],[3601331061,"ומ\"מ לפי מזג טבע המוח כן יהי' הצורה הרוחני', דכל שכל שמשכיל הוא לפי אופן כלי המוח אם בקטנות השכל בקטנים מצד קטנות מוחם אם בגדלות השכל בשכלים גדולים לפי גדלות המוחין (ויש שבקטנים יהי' בהם שכל גדול בעניני' הקטנים שלהם יותר מערך גדלות השכל בגדולים בענינים שלהם, שזהו מצד טיב כלי מוחם כו', וכמו בוצין בוצין מקטפייהו ידיעא כו'), דבכלי המוח יש הכנה זו לקבל צורת אור השכל כו', ואין זה כמו חומר העין שגשם טבעו מוכן לקבל אור הראי' שזה שוה בכל אדם, ואם הי' כן גם בכלי המוח היו הכל חכמים אלא בבחי' הרוחני' ודקות כלי המוח יש שמוכן לקבל חכ' רבה ועמוקה ויש שבלתי יוכל לקבל רק מעט וגם זה שלא בעומק כ\"כ (כי כח עליון הוא בבחי' הדקות והרוחניות יותר ומתחלקים בזה יותר טבעי בנ\"א, דכח חחתון גשם החומר הוא הכלי לקבל את הכח ולכן הוא שוה בכל אדם, אבל כח העליון כלי ההכנה לקבל את הכח הוא הרוחני' יותר שבחומר, וע\"כ מחולקים בזה בנ\"א שאינו בכאו\"א בשוה). וע\"כ גם אופן התגלות אור השכל הוא לפי אופן מזיגת והרכבת כלי המוח, וכמו מוח\nהחכ' קר ולח ומוח הבינה חם ויבש ולכן חכ' היא בבחי' נקודה דטבע המים לדבק, ובינה בבחי' התחלקות פרטים דטבע האש לפרר כו' (והרי כח החכ' בעצם הוא בבחי' נקודה וכח הבינה בהתרחבות, אך התגלות הכח הוא ע\"י מזיגת והרכבת החומר כו'), וכן ההטי' לחו\"ג הוא כפי הרכבת חומר המוח דכאשר ההרכבה היא בבחי' גבורות כח שכלו נוטה תמיד למצוא כל אופני החוב בסברות עמוקות, וכמו חכמים המה להרע שההטי' הוא תמיד להרע כו', ויש חכמים להיטיב אשר בכל עת יטה שכלו להשכיל למצוא כל אופני זכות בסברות עמוקות, ויש שטבע מהות שכלם הוא בבחי' ממוצע כו', שכ\"ז הוא כפי הכנת חומר כלי המוח כו' (ובודאי דחו\"ג שבשכל הוא בנפש בשרשו ומקורו אם מבחי' החסד או מבחי' הגבו' וכמו ב\"ש וב\"ה כו', הנה זהו שבנין החומר הוא לפי בנין הצורה דכאשר נשמתו מבחי' החסד גם בנין החומר הוא באופן כזה, אך זהו בכללות הבנין דחומר וצורה כו', אבל פרטי אופני התגלות הצורה הוא כפי טבע ומזג החומר כו'). וכ\"ז הוא מצד התאחדות החומר בהצורה ע\"כ התגלות אור צורת הכחות לפי חומר הכלים כו'\n(וכן הוא בעבודה דנה\"א בבחי' חו\"ג שבו שזהו ג\"כ כפי חומר נה\"ט אם הוא מבחי' החסדים העבודה היא בבחי' התיישבות יותר ובבחי' אהבה הנמשכת כמים כו', וכן בבחי' תיקון כל דבר בבחי' קירוב דהיינו בדרך בירור כו', ומי שהוא מבחי' גבו' העבודה היא בבחי' התפעלות והתלהבות ובאה' כרשפי אש כו', וכן בתיקון הדבר בדרך דחי' בבחי' שמאל דוחה כו', וכן בצדקה וגמ\"ח או בדין ומשפט כו', וכן בהשגה לפי גסות ודקות ההשגה דנה\"ט כן היא ההשגה האלקי' כו', אמנם עי\"ז הוא שמתברר הנה\"ט שע\"י שעובד בעבודתו כפי החומר דנה\"ט ה\"ה מזדכך עי\"ז כו', דכמו\"כ בחומר וצורה שע\"י שהחומר הוא כלי לאור וצורת הנפש מזדכך החומר עי\"ז שז\"ע שאו\"פ מצחצח חצי הכלי כו').\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע דהנה יש אורות וכלים לבושים והיכלות, או\"כ מיוחדים, האור מתלבש בהכלי והכלי סובלת האור ומתאחד בו, ועד\"מ בחומר וצורה שהתגלות הצורה כפי מזג החומר, דכפי מזיגת חומר העין הוא בהירות ועכרורית</span>"],[3601331062,"<b>אור</b> הראי' וכן החו\"ג שבו, וכפי חומר המוח ולחלוחית הרוחני שבו כן הוא ההשכלות, ואופן ההשכלה לחו\"ג הוא ג\"כ כפי מזיגת החומר (ובודאי יש באור השכל בחי' חו\"ג זהו שבנין החומר בכללות הוא לפי בנין הצורה), וכ\"ז מפני שהחומר מתאחד בהצורה, וכן הוא בעבודה שהיא כטבעיות הנה\"ט אם בחסדים הוא בהתיישבות הוא בבחי' אהבה כמים, והתיקון בדרך בירור, ואם בגבו' הוא בהתלהבות ואהבה ברשפי אש, והתיקון בדרך דחי' ובזה הוא שמתברר הנה\"ט.\n<b>תיב)</b> והדוגמא מזה יובן למע' באדה\"ע בבחי' או\"כ שהכלי עם היות רחוק ערכה מן האור ה\"ה סובל ומקבל את האור (והאור בא באופן כזה שיוכל להאיר בכלי כו', ולעיל מפ' רס\"ג ואילך נת' שזהו ע\"י בחי' ש' מ\"ה שפועל ביטול בהאור שיבא באופן כזה שיאיר בהכלי והיינו שבא מאין ליש כו', וגם פועל הביטול בהכלי להיות מיש לאין שתקבל את האור כו'), ומתאחד בהאור עד שכל אופן ההתגלות של האור הוא כפי אופן הכלי, וכמו חכ' מוחא ובינה לבא כו', ובע\"ח אי' בכ\"מ מוחין דאבא ומוחין דאימא כו' שנק' הספי' ע\"ש הכלים, והרי העיקר הוא האור רק זהו מפני שהכלי מתאחד עם האור עד שהאור הוא כפי הכלי כו', דכללות אופן ההתגלות והמציאות דבחי' אור החכ' ואור הבינה כו', וכן בפרטי המדרי' דבחי' חו\"ג שבהם כו' וכן התגלות אור החסד והגבו' שבלב אדה\"ע כבי', הכל הוא כפי אופן הכלים כו' (דזהו באמת סבת ההפרש באופני הגילוים דאוא\"ס ב\"ה באצי' ולמע' מאצי' דשם הכלים אינם בבחי' מציאות מאיר האוא\"ס בגילוי יותר כו', ובאצי' שהכלים הם בבחי' מציאות אינו מאיר האוא\"ס\nבבחי' גילוי ממש רק הארה לבד וההארה גופא באה בבחי' מציאות כו', וזהו ג\"כ מה שלמעלה מאצי' הוא בד\"כ בחי' התגברות החסד כמו בחי' רב חסד שמתגבר על הגבו' כו', ובעתיק לית שמאלא בהאי עתיקא כו' ובאצי' הוא בחי' חו\"ג כו', שזהו ג\"כ מצד הכלים כו', וז\"ע ראו עתה כי אני אני הוא ואין אלקי' עמדי דלית שותפא עמי כו' ומשו\"ז לית שמאלא כו', ועמ\"ש בזח\"א דכ\"ב סע\"ב ודכ\"ג ע\"א, וכן באצי' החכ' היא בחי' חסד ובינה מינה דינין מתערין כו', מפני שבחכ' הכלי היא כמו האור ועיקר הכלים מתחיל מן הבינה כידוע, וכן במוחין ומדות הרי המוחין הן בחי' רחמים בכלל, והיינו שבמוחין הוא התרחבות הכלים שמאיר בהם האור בגילוי יותר ע\"כ הם בחי' רחמים כו', ובז\"א הוא בבחי' קטנות שנק' זעיר אנפין כו' ע\"כ שם עיקר ענין חו\"ג כו'). רק שלמעלה אינו כמו למטה דהאיש החסד הוא בבחי' חסד לבד ואין בחי' הגבו' (רק מה שיש בהתכללות כו') והאיש הגבו' הוא בגבו' לבד כו', ולמעלה באדה\"ע כל המדות הן בהתגלות כו', וגם אינו מוכרח במדה כזו וכזו וכמו שאו' יהי רצון מלפניך שיכבשו\nרחמיך כו' וכמו וינחם על הרעה שנהפך מדין לחסד כו', או שהגבו' היא בבחי' חסד ואדרבה בתגבורת החסדים כו' כידוע, והיינו משום דבאמת לאו מכא\"מ כו', וגם האור הוא בבחי' פשיטות וגם הכלים הן אלקות ממש כו', וע\"כ גם במדות גופא נהפך מדה\"ד למדה\"ר כו', והוא ע\"י גילוי אור עליון וכמא' יהי רצון כו' שע\"י גילוי הרצון נהפך מדה\"ד למדה\"ר כו', וזהו בבחי' הכלים להיותם אלקות ומתאחדים עם האורות ע\"כ ע\"י גילוי הרצון נהפך למדה\"ר כו'. אמנם בלבושים והיכלות שהן הפרסאות ומסכים המבדילים כמשי\"ת, הנה בכדי שיהי' הסרת המסך ושיהי' גילוי"],[3601331063,"אור זהו דוקא ע\"י המשכה מבחי' פנימי' הכתר דהיינו מבחי' עתיק, דלהיות דלית שמאלא בהאי עתיקא יכול להיות משם הסרת הפרסאות ג\"כ כו'.\n<b>ועפ\"ז</b> יובן מ\"ש אז ישיר משה כו', דהנה ידוע דבשעת קי\"ס הי' קטרוג גדול וכדאי' במד\"ר בשלח פכ\"א ע\"פ מה תצעק אלי שהס\"מ קטרג הללו עע\"ז כו', ולא שמע לו כלל מפני שבקי\"ס הי' גילוי בחי' עתיק, וכדאי' בזהר מה תצעק אלי בעתיקא תלי' מילתא ומשם נעשה הסרת כל הפרסאות וממילא אין מקום להקטרוג כלל, דהנה כל הקטרוגים הן ע\"י העלם והסתר האור, דכאשר מאיר גילוי האור אינו שייך קטרוג וכמ\"ש השקיפה ממעון קדשך מן השמים וברך את עמך ישראל דנש\"י נראים לדבר חשוב כו' וכמ\"ש במ\"א, ורק בהעלם והסתר האור אז שייך קטרוג, וכמ\"ש ויבאו בני האלקי' להתייצב כו' בני אלקי' דוקא ובאים בזמן סילוק והעלם האור כו', אבל בקי\"ס שהי' גילוי אוא\"ס ממש לא הי' מקום כלל לקטרוג שלו כו', וזהו אז ישיר אז הוא בחי' עתיק וכמש\"א המלך המרומם לבדו מאז דקאי על בחי' עתיק כו', וכדאי' בזהר בשלח דנ\"ד ע\"א כל ניסין וגבורן דאעבידו להו לישראל כד אתנהיר נהירו דעתיקא קדישא בעטרוי גליפין רשימין באז כו', וזהו אז ישיר דמבחי' אז עי\"ז נתבטלו כל המסכים והפרסאות כו'.\n<b>וז\"ש</b> דמשאמרנו שירה באז נתיישבה מלכותך כו', דהנה ישיבה מורה על הקביעות והעדר השינוי והיינו בבחי' עצמות אוא\"ס ב\"ה כו', דבברה\"ע הי' רק הארה לבד והו\"ע עומד שזהו רק לפי שעה היינו בחי' הארה לבד, דהארה זו מתעלם תחלה ע\"י הכלים ואח\"כ בבחי' מל' שמשתנה האור כו', ואח\"כ בהמסכים ופרסאות המסתירים עד שלמטה לא יש גילוי אור כו', אבל משאמרנו שירה באז נתיישבה מלכותך שנמשך בחי' עצמות א\"ס בבחי' מל' ובבחי' קביעות במל' (עמשנת\"ל פ' שע\"ה), והיינו שמל' היא בבחי' כלי לקבל לא רק מה שכונסת האור בתוכה שאין זה בבחי' התלבשות פנימי ממש והוא רק שמעלמת האור כו' כנ\"ל, אבל ענין ההתיישבות והקביעות הוא שתהי' המל' בבחי' כלי וכמו לעתיד דכתי' הרחיבי מקום אהלך שתהי' בבחי' רוחב הכלי כו', וכסאך נכון הוא שיהי' הגילוי גם בהמסכים והפרסאות שז\"ע כסא כס א' כו', והיינו ע\"י הגילוי מבחי' עצמות א\"ס כו' (וזהו מה יש כבוד בין מלך לאגוסטוס מלך עומד על הלוח, וידוע דציור על הלוח הוא בחי' דמות כו', ואגוסטוס יושב שגם בבחי' דמות נמשך בחי' העצמות\nכו'), וזהו שאע\"פ שמעולם אתה כו' לא נודעת בעולמך שלא הי' גילוי אלקות בעולם כו' עד שאמרו בניך שירה שנמשך גילוי אלקות בעולם כו'. וזהו ג\"כ מ\"ש ישיר משה ובנ\"י דהנה אי' במד\"ר שם פכ\"ג הה\"ד קדמו שרים אחר נוגנים כו', ומכיוון שיצאו ישראל מן קדמו מלאכים לאמר שירה א\"ל הקב\"ה יאמרו בני תחלה, הה\"ד אז ישיר משה שר לא נא' אלא ישיר אמר הקב\"ה ישירו משה ובנ\"י תחלה, וכן דוד אומר קדמו שרים אלו ישראל אחר נוגנים אלו מלאכים כו', דהנה מלאכים הם נושאים את הכסא כו', אך ההמשכה שלהם הוא מבחי' חיצוני' דאו\"א שזהו להחיות את העולמות כו', והנשמות ממשיכים בחי' יחוד פנימי דאו\"א כו', וע\"כ ישירו בני תחלה להמשיך מבחי' פנימי' או\"א, ואחר נוגנים שממשיכים הגילוי גם במלאכים ועד ונתתי לך מהלכים בין העומדים האלה כו', וידוע דעומדים זהו בבחי' הגילוי שבעולמות ומהלכים זהו בבחי' עצמות א\"ס"],[3601331064,"שזהו ממשיכים נש\"י כו', ועושים ההילוך במלאכים ג\"כ כו'. וזהו שנא' אז ישיר ישירו בני תחלה שזה נתחדש בקי\"ס דתחלה היו המלאכים אומרים שירה וממשיכים בחי' יחוד חיצוני כו', ובקי\"ס נתחדש שיאמרו ישראל תחלה להמשיך בחי' יחוד פנימי ואח\"כ אומרים המלאכים שירה שנמשך גם בהם הגילוי כו', וזהו אומרו את השירה הזאת היינו ההמשכה בבחי' מל' שנתיישבה מלכותך כנ\"ל, ויאמרו לאמר היינו שיהי' ההילוך גם במלאכים כו'. ובגמ' אמרו מכאן לתחה\"מ מן התורה, דתחה\"מ יהי' ע\"י בחי' טל תחי' טלא דנטיף מעתיקא גילוי בחי' עתיק כו', ושייכות זה לקי\"ס להיות דבקרי\"ס נקרע ונתבטל בחי' הפרסא כו', דהנה אי' במד\"ר ע\"פ מחצתי ואני ארפא מחיצתי אני ארפא מחיצה עשיתי בין העליונים ותחתונים העליונים חיים ותחתונים מתים אותה מחיצה מרפא כו', והיינו בחי' הפרסא שירפא הפרסא ועי\"ז יהי' תחה\"מ כו', וזהו דבקי\"ס מרומז ענין תחה\"מ לפי שאז נקרע הפרסא והי' גילוי בחי' עתיק כו', וזהו אז ישיר אז דוקא בחי' עתיק שעי\"ז נקרע הפרסא כו', ואו' ישיר ישירו משה ובנ\"י תחלה זהו המשכת\nבחי' יחוד פנימי דאו\"א דהיינו המשכת בחי' עצמות א\"ס ב\"ה כו', את השירה הזאת היא ההמשכה בבחי' מל' שנתיישבה מלכותך בבחי' קביעות אור כו', וגם כסאך נכון הגילוי גם בבחי' הפרסא ועי\"ז ויאמרו לאמר בחי' מהלכים בין העומדים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא מזה למעלה דהכלי מתאחד בהאור, וע\"כ גילוי האור כפי אופן הכלים, וזהו דלמעלה מאצי' האור בגילוי ביותר ובד\"כ בבחי' רב חסד ובאצי' מיעוט האור ובבחי' חו\"ג, ובאצי' גופא חכ' בחי' חסד וכן המוחין מפני שעיקר גרמוהי בחי' המדות, רק למעלה כל המדות בהתגלות וע\"י גילוי הרצון נהפך מדין לחסד משום דבאמת לאו מכל אמ\"כ (משא\"כ הסרת המסכים הוא מפנימיות הכתר). ובזה יובן מ\"ש אז ישיר דבקי\"ס הי' גילוי בחי' עתיק ועי\"ז הי' הסרת הפרסאות, וזהו אז בחי' עתיק, וזהו שנתחדש בקרי\"ס שישירו ישראל תחלה המשכת בחי' יחוד פנימי דאו\"א.</span>"],[3601331065,"<h3>בס\"ד. ש\"פ יתרו, העת\"ר</h3>\n<b>וישמע</b> יתרו כהן מדין חותן משה את כל אשר עשה אלקים למשה ולישראל עמו כי הוציא ה' את ישראל ממצרים, וצ\"ל למה נז' כאן כהן מדין דלכאו' אין זה למעלה וכבוד כ\"כ למשה שהי' כהן מדין ולמה הי' להזכיר זה. גם מה מודיע שהוא חותן משה הרי ידוע שהוא חותן משה ומה נצרך להודיע זאת, ואומר שניהם כהן מדין וחותן משה. גם צ\"ל מ\"ש את כל אשר עשה אלקי' למשה ולישראל כי הוציא ה' את ישראל ממצרים למה מחלק זה בב' ענינים שהרי מה שעשה למשה ולישראל זהו שהוציאם ממצרים, וממה שמחלקם משמע שהם ב'"],[3601331066,"ענינים. ורש\"י פי' על מ\"ש וישמע יתרו קי\"ס שמע, וא\"כ גם וישמע יתרו הו\"ע בפ\"ע, והרי יש כאן ג' ענינים, וישמע יתרו, ואת אשר עשה כו', וכי הוציא ה' כו', וצ\"ל מהו ג' ענינים אלו. ובזהר יתרו דס\"ז ע\"ב אי' דמ\"ת הי' ע\"י הודאת יתרו דוקא, דכאשר אמר יתרו עתה ידעתי כי גדול ה' מכל אלקים כדין אסתלק ואתייקר קוב\"ה ביקרי' עילא ותתא ולבתר יהיב אורייתא, וזה תמוה למה בהודאת יתרו דוקא הי' מ\"ת, וכי משה וס\"ר ישראל לא היו כדאי ליתן להם תורה עד שהודה יתרו דוקא. ולהבין כ\"ז ילה\"ק מ\"ש בע\"ח שיש ד' מדרי' אורות וכלים ולבושים והיכלות, ונת\"ל דאורות וכלים הם כענין חומר וצורה שהחומר מתאחד עם הצורה עד שהתגלות הצורה הוא כפי החומר דוקא, וכמו בחומר המוח דמוח החכ' קר ולח ומוח הבינה חם ויבש וכן הוא הגילוים דכח החכ' וכח הבינה, וכן ההטי' לזכות ולחוב הוא כפי מזיגת והרכבת חומר המוח בחסדים וגבורות שבו כו', וכמו\"כ הוא באו\"כ שהכלים מתאחדים עם האור דאופן הגילוי הן בבחי' ריבוי האור ומיעוט האור וכן בבחי' התגברות החסדים הוא כפי אופן הכלים\nדוקא כו', וזהו לפי שהכלים מקבלים את האור ומתאחדים עם האור וע\"כ גילוי האור הוא כפי אופן הכלי דוקא כו'.\n<b>תיג)</b> וזהו ענין ההפרש בין בחי' כלים ובחי' לבושים למעלה, דהנה ידוע במהות ענין הלבושים שהן בחי' נפרד מעצם ומהות הדבר ולא כחומר וצורה ככלי המוח וכלי העין כו', ואפי' בלבוש היותר פנימי שהוא דק בערך הרבה יותר מחומר כלי המוח כמו הלבוש דמח' בכלל שהיא דקה ורוחני הרבה מגשם חומר המוח, וגם מדקותו הרוחני שמוכן לקבל צורת השכל כו', וכידוע דגם הגשמי שברוחני הוא למעלה הרבה מהרוחני שבגשמי כו', וע\"כ אותי' המח' עם היותם בחי' הגשמי שברוחני' הנפש ה\"ז למעלה מהרוחני דגשם המוח כו', ואפילו פנימי' כח המח' שנק' אותי' השכל ה\"ז הכל בבחי' לבוש לבד כו', וכידוע דמח' גופא נחלקת לג' מדרי' מחדו\"מ, להיות דפנימי שבמח' הוא בחי' מח' שבמח' והוא הנק' אותי' השכל או מחשבת שכל והן האותי' שבאים עם גילוי השכל בלי הכנה להכין האותיות כ\"א באים בדרך ממילא עם התגלות השכל כו', וכמו כאשר ממציא אדם איזה השכלה הרי נמצאים אל השכל אותי' שבהם נתפס ונתלבש אותו המצאת השכל כו', ואותי' אלו הם דקים ורוחני' עד שכמעט אינם ניכרים כו', וכן\nכשחושב את השכל לעצמו דהיינו פנימי' השכל שחושב את הענין באותיות שבהם נתפס ונתלבש השכל ומאיר שם אור השכל והאותי' אינן מורגשין כ\"כ כו', ומ\"מ ה\"ז בחי' לבוש לבד שהאותי' מלבישים את השכל לא שהאותי' הן בחי' כלים אל השכל לקבל את השכל בבחי' פנימי' ממש כו'. ולכן האותי' עם היות שמלבישים את השכל אינם חיים מן השכל, כמו חומר המוח שחי מהאור השכל וכמ\"ש בסש\"ב פנ\"א שהן מקבלי' תחלה כח וחיות הראוי להם לפי מזגם ותכונתם שהן חב\"ד כו', הרי שהמוח חי מאור המתלבש בתוכו, משא\"כ האותי' אינם חיים מן השכל או המדות כו'. והגם שאינו דומה האותי' כשמתלבש איזה שכל לכשאין בהם התלבשות אור כו', ודברים היוצאים מן הלב הרי נראה בהם חיות כו', הנה באמת זהו חיות האור לא חיות האותי' כו', שהרי כשאין יוצאין מן הלב הגם שיש בהם אור אינו נראה בהם חיות רב רק כשיוצאים מן הלב שיש בהם ריבוי אור"],[3601331067,"נראה בהם חיות הרי החיות הוא חיות האור כו'. אך גם האותי' כשיש בהם אור ה\"ה בבחי' דקות יותר כו', ומ\"מ אינם חיים מן האור כמו הכלים כו', וזהו לפי שהכלים מקבלים את האור בתוכם ממש בבחי' פנימי' וע\"כ הם חיים מן האור, משא\"כ האותי' אינם מקבלי' את האור בתוכם ממש רק שמלבישים את האור כו', ולכן ביכולת להחליף את האותי' ולחשוב באותי' אחרים, וכמו הלבוש הגשמי שביכולתו להחליפו כמו\"כ האותי' ביכולת להחליף, ועם היות שא\"א לפשוט לגמרי לבוש המח' שנובע תמיד מן השכל מ\"מ הרי יש כמה מחשבות שונות, וגם את השכל יכולים להלביש באותי' אחרים משא\"כ חומר המוח א\"א לפשוט ולהחליף כו', ובודאי שאינן דומים האותי' הבאים מעצמן או כשמחליף את האותי' שזהו שבאו בהכנה כו', דכאשר מחליף את האותי' ה\"ה אותי' מורגשים יותר מהאותי' הבאים ממילא כו'. והענין הוא כידוע שיש אותי' בכח השכל קודם שמשכיל ומגלה איזה השכלה (וכידוע דשרש האותי' מקדמות השכל וכמ\"ש באגה\"ק סי' ה'), והוא פריטת האותי' קודם שבאו בבחי' מציאות אותי' בהתגלות (והוא ג\"כ כענין חומר\nוצורה בהאותי' גופא וכמ\"ש באגה\"ק שם), וכאשר מתגלה השכל ממקור השכל מתגלים עמו האותי' המלבישים את השכל ומגלים אותו כו', וזהו שאנו רואין שינוי אופן גילוי אור ההשכלה באדם זה שמוציאו באותי' ולשון זה ובין גילוי אור השכל בזולתו שבא באותי' וצירופים אחרים וכשינוי ל' המפרשים בשכל א' כתוס' רא\"ש ר\"ן שאומרי' שכל א' ובאותי' אחרים, והיינו שכפי האותי' שבמקור השכל כן באים בהתגלות כו', והן האותי' המתגלים עם השכל ובאים בדרך ממילא בלי הכנה כו', וכשמחליף האותיות עם היות שהן ג\"כ כפי מקורם כי א\"א לו להחליף באותי' אחרים לגמרי שלא כפי האותי' שבמקור השכל שלו כו', מ\"מ יהיו אותי' מורגשים יותר כו', ונמצא דאותי' שמחליף אינם כמו האותי' שבאים דרך ממילא כו', מ\"מ מזה שביכולתו להחליף הרי מובן שגם האותי' שבאים עם גילוי השכל בדרך ממילא הם ג\"כ נבדלים מן השכל, דאם היו מיוחדים עם השכל הרי לא הי' ביכולת להחליפם, ומה שביכולת להחליפם הוא מפני שהן נבדלים כו', ובאמת הרי אינו מוכרח שיהי' השכל באותי' אלו דוקא, שהרי בעל שכל אחר אומר\nאותו השכל עצמו באותי' אחרים הרי שמצד השכל אינו מוכרח שיהי' באותי' אלו דוקא, וההכרח הוא רק מצד הנפש דהיינו מצד האותי' שבמקור השכל מוכרח שיבא השכל באותי' אלו דוקא אבל מצד השכל גופא אין הדבר מוכרח, והיינו מפני שהם נבדלים מן השכל כו', וגם שבכל גילוי אור שכל הרי האותי' נרגשים לבד אור השכל גם בהברקת השכל, הגם שהאותי' אינם ניכרים כ\"כ מ\"מ אינם בלתי נרגשים לגמרי, שביכולתו להרגיש האותי' וגם הם מורגשים באמת, כי מה שהאותי' בלתי ניכרים אין זה מצד התאחדות האותי' עם האור כ\"כ עד שבלתי ניכרים כ\"א מצד האור והגילוי ביותר ע\"כ אין האותי' ניכרים ונרגשים כ\"כ כו', ואין זה כמו חומר וצורה (שהו\"ע אור וכלי) שאין החומר נרגש בפ\"ע מן הצורה, וכמו חומר העין או חומר המוח הרי אין החומר נרגש כ\"א אור הראי' או אור השכל הוא שנרגש (ורק כשאין החומר כלי אל הצורה וכמו בקלקול החומר ח\"ו ה\"ה מרגיש כאב האבר אבל כשהוא כלי אינו נרגש כלל), הגם דשם הצורה הוא לפי אופן החומר כנ\"ל פ' תי\"א (משא\"כ באותי'), מ\"מ החומר מתאחד עם האור כ\"כ עד שאינו נרגש כלל בפ\"ע ונרגש רק"],[3601331068,"האור כמו שהוא לפי אופן החומר כו' (שכן הוא בכל אור וכלי אפי' במדרי' שאין האור בגילוי כ\"כ הרי נרגש רק האור ולא הכלי כו'), משא\"כ באותי' שהן נרגשי' בפ\"ע מן האור כו', והיינו מפני שהן דבר בפ\"ע בבחי' לבוש הנבדל מן העצם כו'. ומכ\"ש בבחי' דבור שבמח' דהיינו כשחושב את השכל איך להשפיע לזולתו הרי יצטרך לסדר אופן צירופים שבדבור במחשבתו בשינוי מכמו שחשב הענין השכלי הזה לעצמו, הרי האותי' אלו באים בהכנה והן אותי' מורגשים בעצמו שהאותי' מורגשים יותר מן האור כו', ולבוש הדבור יותר נפרד מלבוש המח' שהן אותי' מורגשים אל הזולת ועת לדבר ועת לחשות כו', ועם היות שגם אותי' הדבור באים מן הנפש וכפי אופן האותי' שבנפש באים האותי' בדבור כו', מ\"מ ה\"ה בבחי' לבוש הנפרד המורגש ביותר וכלבוש תחליפם ואינם נמצאים תמיד כו'. ובכללות ענין האותי' הרי אין החו\"ג שבשכל תלוי בהאותי', כמו בחומר וצורה דהתגלות אור צורת השכל הוא כפי אופן החומר בבחי' חסדים וגבורות וכמשנת\"ל (ד\"ה אז ישיר), משא\"כ באותי' הרי אין הטיית השכל לחו\"ג תלוי כלל בהאותי'\nאדרבה מיד שיטה השכל כלפי זכות באיזה סברה מיד יחשוב הענין באופן כזה כו', וכידוע שבאותי' יש ג\"כ חסדים וגבורות וכמו אותי' שאינם מקבלים דגש, וכן דגש ורפוא הן חו\"ג כו', ועמ\"ש הפרד\"ס שער האותי' פ\"ג, ואור החסד בא באותי' דחסדים כו', והרי כפי הטיית השכל כך הן האותי' כו', וזהו שהאותי' מחו\"ד הן לבושי' להכחות דהיינו שהן דברים נפרדים מהכחות וממילא ה\"ה מעלימים על האור יותר מבחי' הכלים כו'. והדוגמא מזה יובן למעלה בבחי' לבושים שיש בכל עולם וכמא' לבושין תקינת לון כו' שזהו בחי' לבוש המעלים האור כו', ולא כמו הכלים שהן מתאחדים עם האור שהן כלי קבלה שהאור מאיר בהם בגילוי כו', וכמא' וההוא נביעו איהו כנשמתא לגופא דאיהו חיים לגופא כו', שהאור מאיר בהכלי והכלי מאירה ממש מן האור וחי' ממנו בבחי' חיות פנימי כו', משא\"כ בחי' הלבושים שהן רק מלבישים את האור (לא שהאותיות חיים מן האור שהן בבחי' דומם שאינן מקבלים חיות מאור השכל והמדות ומאור הנפש בכלל כו', ובודאי יש חילוקים בהלבושים שלפי אופן מעלת האור כן הוא דקות הלבושים,\nוכמו שמחולקי' לבוש הראש מלבושי הגוף והרגל כו', וכמו לבוש המח' ולבוש הדבור ומעשה כו', וכן באותי' למעלה יש אתוון רברבן ואתוון בינונים ואתוון זעירין, דאתון רברבין הוא שמאיר בהם ריבוי אור וממילא האותי' בבחי' רוחני' ובבחי' העדר המציאות יותר, ואתוון בינונים וזעירין הוא שבהם מיעוט האור וע\"כ הם בבחי' מציאות יותר כו', ומ\"מ אינם כלים אל האור רק לבושים המלבישים את האור) ומעלימים עליו כו', דעם היות שהן ג\"כ מגלים את האור כו', ה\"ז גילוי שע\"י דבר המעלים כו'. ויובן זה ע\"ד משנת\"ל (ד\"ה אז ישיר) ההפרש בין כלים דאצי' לבחי' מל', דהכלים דע\"ס מגלים חיצוני' האור, וההעלם הוא רק שלא יהי' בבחי' אין כמו שהוא בעצם כו', וההעלם דבחי' מל' הוא שמשתנה האור כו', ומ\"מ ה\"ז ג\"כ גילוי, וכמו אור הלבנה שזה ג\"כ אור רק שאינו כמו אור השמש שע\"י הנרתק שלא נשתנה אור השמש כו' (עם היות שאינו כמו כשהקב\"ה מוציא חמה מנרתקה כו'), וכמו\"כ הוא בבחי' מל' שהוא ג\"כ גילוי אור רק שהאור משתנה כו' וידוע דמל' נק' לבוש וכמ\"ש ה' מלך גאות לבש כו', ועד\"ז יובן בענין הלבושי' שהן בחי' העלם שמשתנה האור מכמו שהוא בעצם כו'."],[3601331069,"<span data-k=\"ks\"><b>קיצור.</b> אמנם לבושים הם נפרדים דגם לבוש המח' ובחי' מח' שבמח' שחושב השכל לעצמו וגם בהברקת השכל הרי האותיות הן לבושים ולא כלים, עם היותם רוחניים יותר מהכלים, ולכן הכלים חיים מן האור משא\"כ האותיות, רק שע\"י האור הן בדקות יותר, ודברים היוצאים מן הלב זהו חיות האור, וביכולת להחליפם, ואז הן מורגשים יותר, דהאותיות הבאים ממילא עם השכל הן מכח האותיות שבנפש, ואין השכל מוכרח לאותיות אלו דוקא, והאותיות ה\"ה מורגשים, והכלים כשהאור מאיר בהם אינם מורגשים בפ\"ע, ולבוש הדבור נפרד יותר שהוא אל הזולת ואינו תמיד, ובכללות אין האור כפי האותיות כ\"א להיפך דאור של חסד מתלבש באותיות דחסדים, וכ\"ז הוא מפני שאינם בבחי' אחדות וענינם הוא להעלים, וכמו כלים מיוחדים וחיים מהאור, ולבושים הוא רק שמלבישים ומעלימים על האור (ויש אתוון רברבן בינונים וזעירין שזהו בדקות הלבושים), והגילוי הוא ע\"י העלם, וכמו בחי' מל' שמשנה את האור (משא\"כ בכלים דע\"ס), ומל' היא בחי' לבוש.</span>\n<b>תיד)</b> והנה ידוע דלבושים בכלל הן עולמות בי\"ע שעז\"א לבושין תקינת לון כו', דע\"ס דאצי' הן בחי' גופים וכמא' וכמה גופים תקינת לון דקאי על הכלים דע\"ס דאצי' שהן עד\"מ כמו אברי הגוף המתאחדים עם כחות הנפש כחומר וצורה כו' וכמשנת\"ל, והו\"ע חכ' מוחא בינה ליבא כו' חסד דרועא ימינא גבו' דרועא שמאלא כו' שנק' הע\"ס ע\"ש הכלים מפני שמתאחדים עם האור כו', אבל בי\"ע הן בחי' לבושים נפרדים שעז\"נ ומשם יפרד כו' וכמ\"ש בת\"ז דלאו איהו וחיוהי וגרמוהי חד כו', וידוע דמח' ודבור הו\"ע ברי' ויצי' דלבוש המח' ג\"כ לבוש הנבדל (ובכללות ה\"ז בבחי' לבוש שאינו בבחי' כלי להיות בבחי' או\"פ כו' כנ\"ל), ומ\"מ ה\"ז מיוחד יותר שאינו ניכר ונרגש כ\"כ והוא בתמידות כו', ולבוש הדבור הוא לבוש הנפרד כו'. וכמו\"כ הוא בעולם הברי' שזהו יש הראשון הנברא מן האין האלקי שמאיר שם בחי' האין האלקי יותר, ובעולם הברי' אינו בבחי' מציאות יש עדיין רק בבחי' אפשרות המציאות לבד כו', וזהו שהברי' נק' חשך שאינו בבחי' מציאות מורגש עדיין כו', ויצי' נק' אור שהוא בחי'\nהגילוי אל הזולת והוא התחלת היש כו', וכן הוא בבחי' בי\"ע שבאצי' דבחי' מחשבת שכל הוא בחי' בינה דההשגה שם הוא בחי' אותי' המח' כו', ומ\"מ נק' מי שהיא בחי' העלם עדיין וכמ\"ש הנסתרות לה' אלקינו חו\"ב כו', וז\"א בחי' יצי' שבאצי' הוא בחי' הגילוי שעז\"א והנגלות לנו ולבנינו ונק' אלה כו'. אמנם בע\"ח שער דרושי אבי\"ע פ\"ד שהד' מדרי' או\"כ לבושין והיכלין הן אבי\"ע דברי' בחי' גופין ויצי' בחי' לבושין כו', וכ\"כ הפרד\"ס שער עצמות וכלים פ\"ו בפי' הב' במ\"ש לבושין תקינת לון דקאי על הספי' דיצי' ומ\"ש וכמה גופין תקינת לון הן ספי' דברי' כו'. וי\"ל דהנה יש בחי' התלבשות שהיא בבחי' גילוי דהיינו התלבשות פנימי ומ\"מ אינו כמו חומר וצורה כו' והוא בבחי' התלבשות הפרצופים זב\"ז כו', וידוע המשל בזה כמו בהתלבשות הכחות זב\"ז דכח עליון כאשר מתלבש בכח תחתון ה\"ז התלבשות פנימי בבחי' גילוי שע\"י ההתלבשות נעשה התחדשות בכח העליון כו', ומ\"מ הכח התחתון הוא בחי' לבוש לבד לגבי כח העליון, וכמו התלבשות הרצון בשכל להיות טעם לרצון הרי בהתלבשות זאת בא הרצון בבחי' התיישבות פנימי"],[3601331070,"ובבחי' התחלקות כו'. שהרי הרצון עצמו הוא פשוט שאין בו התחלקות פרטים וגם אינו בבחי' התיישבות פנימי בהכחות, וזהו שפעולת הרצון הוא שפועל בדרך כח עליון, וכמשנת\"ל בכ\"ד ההפרש בין פעולת הרצון לפעולת השכל, שהשכל פועל בהכחות בדרך אולפנא ולימוד שזהו בבחי' התלבשות פנימי, משא\"כ הרצון פועל בדרך כח עליון, והיינו לא בבחי' התלבשות פנימי רק בדרך גזירה וכמלך שגוזר אומר שזהו ענין ההשתררות ברצון כו', וכן בהמקבל הוא בדרך גזירה לא בדרך טעם ושכל שכן צריך להיות רק שצריך לקיים את הרצון כו', וכמו בקיום המצות בדרך קבעומ\"ש לא מצד הטעם והכוונה כ\"א לקיים רצה\"ע כו'. ובהתלבשות הרצון בשכל ה\"ה בא בבחי' התיישבות פנימי שיש טעם להרצון שעי\"ז הרצון מתיישב כו', וגם בא בבחי' התחלקות פרטים כו', וכמו רצון האדם לבנות בית שהוא רצון פשוט שאינו ניכר בהרצון איך ומה יהי' הבית כו', ובאמת בהרצון אין בו התחלקות פרטים איזה בית יהי' כי הרצון מצ\"ע הוא רק שרוצה בית ואינו נוגע כלל איך שיהי' הבית כו', ומה שמבו' במ\"א שבהעלם יש בהרצון אופן הבית\nשרוצה זהו בהעונג שבהרצון שיש לו עונג בענין הבית (דער געשמאק פון נפש) שבזה יש התחלקות בהעלם כו', אבל בהרצון עצמו אין בו התחלקות כו', ואיך שיהי' בגילוי ודאי לא יש התחלקות כו', וכשבא בטעם ושכל ה\"ה בא בדרך פרט באיזה אופן יהי' הבית באורך ורוחב ובציור חדריו ועליותיו וכה\"ג שיש רצון פרטי בכל דבר בפרט. והנה בהתלבשות זאת הגם שהשכל מחדש דבר בהרצון שבא בבחי' התיישבות היינו שיש טעם המחייב את הרצון והוא שצריכים לרצות כך וגם בא בבחי' התחלקות כו', הרי מ\"מ אין זה כמו חומר וצורה דהתגלות הצורה הוא כפי אופן החומר כו', וכמשנת\"ל פ' ת\"י דהכלים עם היות שאינם משנים את האור, הנה גילוי האור ע\"י אינו כמהות עצמו כ\"א כמהות הכלים כו', ובהתלבשות הרצון בשכל הרי הרצון מ\"מ נשאר בבחי' רצון דגם כשמתלבש בשכל ויש טעם לרצון אינו נעשה בבחי' שכלי כ\"א הוא בבחי' רצון כו'. וכידוע בענין תומ\"צ שהתורה היא טעמי המצות ומ\"מ המצוה היא בבחי' רצון, וכמא' אל תהי יושב ושוקל במצותי' ש\"ת דקלות וחמורות שוין, דענין קל וחמור הוא ע\"פ התורה כו'\nוכולם שוים בקיום המצוה להיותה בחי' רצון שאין בזה התחלקות כלל כו', הרי שאין הרצון משתנה בעצם ע\"י ההתלבשות בהשכל כו', וגם שאין הטיית הרצון לפי אופן השכל אדרבה הטיית השכל הוא כפי אופן הרצון דמה ששכלו מחייב כך זהו מפני שרצונו בזה דמשו\"ז ה\"ה מוצא טעם ושכל לזה כו', וכמו גם בפרטי הטיית השכל לזכות ולחוב שזה תלוי בהרצון כו', וכידוע בענין השוחד דמ\"ש כי השוחד יעור הוא שהשכל שלו מחייב לזכות וזה רק מצד הטיית הרצון כו' כידוע ומבו' במ\"א באורך. הרי בהתלבשות זאת הגם שהיא התלבשות בבחי' גילוי פנימי עד שנעשה עי\"ז התחדשות בהרצון ומ\"מ ה\"ז בבחי' לבוש לבד שאין המלובש נעשה כפי אופן המלביש כו', והיינו לפי שרצון וחכ' הן ב' כחות מחולקות זמ\"ז, וע\"כ החכ' עם היותה מלבשת את הרצון ה\"ז כדבר נבדל לא בבחי' התאחדות ממש, וכן הרצון הגם שהוא בבחי' גילוי פנימי בחכ' אין זה בבחי' פנימי ממש כ\"א שעומד מובדל מן החכ', וע\"כ בזה גופא שבא בחכ' בבחי' התלבשות ה\"ז פועל בחכ' בדרך כח עליון להיות הטיית החכ' כפי אופן הרצון כו', הרי שהחכ' היא בבחי' לבוש לבד לגבי הרצון רק שהיא לבוש"],[3601331071,"הראוי לגילוי הרצון (דגילוי הרצון בבחי' פנימי הוא בחכ' דוקא) ואינו מעלים על הרצון כו'. וכן הוא בכל התלבשות כח עליון בכח תחתון שהכח העליון הוא המנהיג את הכח התחתון כו', וכמו בהתלבשות השכל במדות הרי השכל מנהיג את המדה ולכל אשר יחפוץ יטה את המדה ע\"פ השכל וכמ\"ש לפי שכלו יהולל איש כו', דכן הוא באדם שכלי שהמדות הן רק לפי אופן שכלו דמה שהשכל מחייב שצריך לרצות ה\"ה רוצה באמת ומה שהשכל מחייב שלא לרצות אינו רוצה כו', דבמדות טבעי' יכול להיות שיהי' שלא לפי אופן השכל מפני שהן רצון בעצם מהותם כו', אבל מדות שכליי' הן לפי אופן השכל כו'. והנה באור וכלי ג\"כ האור מנהיג את כלי, וכמ\"ש במ\"א דלמעלה באו\"כ הוא שהמלובש מושל ושולט וכמשי\"ת בסמוך בהתלבשות הפרצופים כו', אך באו\"כ הרי האור נעשה כמהות הכלי, משא\"כ בשכל ומדות אין השכל נעשה מהות מדה כו' (ובהבי' דלכן אמר שמתהפך ממהות שכל למהות מדה, היינו שהאהבה הוא הטעם וג\"ז רק מהבנת טוב הדבר שזהו בחי' מדות שבשכל רק להיות שזהו הבנת טוב הדבר בעצמו ה\"ז מהות מוחין עדיין, אבל\nהשכל עצמו אינו נעשה מהות מדה, ועמשנת\"ל פ' קמ\"ט וקנ\"א). וכן הוא בהתלבשות אור וחיות הנפש בגוף בכללות התלבשותו הוא שהנפש מנהיג את הגוף והגוף בטל וטפל אל הנפש ונגרר אחריו כו', וכן הוא בהכחות כמו כח הראי' בעין הרי בהתלבשו' בו כח הראי' הרי ממילא יראה ואין בחירה ורצון בחומר העין שלא לראות (רק שיוכל להעצים עיניו דאז אין אור הראי' מתלבש בו וגם זה תלוי בנפש כו' וכמו עוצם עיניו מראות ברע שתלוי ברצון הנפש כו'), ועם היות שפרטי אופני הראי' הן כפי חומר העין כנ\"ל, מ\"מ כללות הראי' תלוי ברוחני' אור הראי' דנפש כו', וכן הוא בכל הכחות כמו כח השמיעה כו'. והנה יש אופן התלבשות שאין הלבוש בטל אל הכח המלובש בו, וכמו בהתלבשות נה\"א בנה\"ב הרי אין שליטה גמורה לנה\"א על הנה\"ב ויוכל להיות ח\"ו שליטה לנה\"ב כו', וכמ\"ש ולאום מלאום יאמץ שלפעמים זה גובר ולפעמים כו', וזהו ההפרש בד\"כ בין התלבשות הפרצופים באצי' ששם הוא בחי' ביטול שהמלביש בטל אל המלובש שההנהגה היא כמו המדרי' המתלבשת כו', וכמו או\"א שהלבישו לזרועות דא\"א שעי\"ז הי'\nיצי\"מ, דבכדי שיהי' יצי\"מ הי' צ\"ל התלבשות א\"א באו\"א, דמא\"א עצמו שלא ע\"י התלבשות באו\"א לא הי' אפשר להיות יצי\"מ שהרי שם כחשיכה כאורה כו', ופרעה אותי' הערף שמקבל מבחי' עורף דא\"א שזה הי' סבת הגלות כידוע, ורק ע\"י התלבשות א\"א באו\"א הי' הגאולה וכמ\"ש ויוציאנו ה' אלקינו משם ה' אלקינו דוקא בחי' או\"א כו', והרי הגאולה הוא מא\"א דמאו\"א עצמן א\"א להיות הגאולה, אדרבה כתי' וימררו את חייהם וכמא' אשר מררו חיי אבותינו במצרים, וידוע דאבותינו הן חג\"ת וחיי אבותינו בחי' המוחין כו', רק ע\"י התלבשות א\"א באו\"א עי\"ז הי' הגאולה כו', הרי שההנהגה היא מהמדרי' המתלבשת כו', ואו\"א הגם שמלבישים לא\"א ושיהי' עי\"ז הגאולה (היינו שיומשך למקום הראוי דוקא שזהו מה שאו\"א פועלים בא\"א שנעשה ע\"י בבחי' התיישבות פנימי כו') ה\"ה בבחי' ביטול שאינם מעלימים כמו לבוש המיוחד שההנהגה היא מהמדרי' המתלבשת כו', משא\"כ בבי\"ע דמשם יפרד אין הלבוש בטל כ\"כ כו', ולכן אמרו אפקוהו למט\"ט כו' הרי יש קצת פירוד כו'."],[3601331072,"<span data-k=\"ks\"><b>קיצור.</b> והנה בד\"כ לבושים הן בי\"ע, מח' ברי' דבור יצי' חשך ואור, וכן בי\"ע שבאצי' בינה העלם ז\"א גילוי, ונמצא בע\"ח ובפרד\"ס דגופין ברי' ולבושין יצי', וי\"ל כמו התלבשות הכחות זב\"ז שהוא בבחי' התלבשות פנימי שהעליון מוסיף אור וחיות בהתחתון ומ\"מ התחתון הוא בבחי' לבוש לבד, וכמו הרצון שאין בו התחלקות (וההתחלקות שבו בהעלם הוא מהעונג), ובא בשכל בבחי' התיישבות פנימי שיהי' טעם לרצון ובא בהתחלקות רצון פרטי לכ\"ד, והרי מ\"מ נשאר בבחי' רצון לא בבחי' שכלי, וכמו הרצון דמצות גם שבא בטעמי התורה, והרצון מטה את השכל גם בבחי' חו\"ג שבו כידוע בענין השוחד, הרי שהשכל רק כמו לבוש אלא שהוא לבוש הראוי שהרצון יהי' בו בבחי' פנימי, וכן השכל כשמתלבש במדות ה\"ה מנהיג את המדות וה\"ה בהם בבחי' התלבשות פנימי ואין השכל נעשה מדה, ולמעלה הו\"ע התלבשות הפרצופים זב\"ז וכמו או\"א שהלבישו לזרועות דאריך שע\"י ההתלבשות באו\"א נמשך למקום הראוי והגאולה בעצם היא מא\"א (ויש התלבשות שאין הלבוש בטל כ\"כ והוא בנה\"א ובנה\"ב והיינו בבי\"ע דומשם יפרד).</span>\n<b>תטו)</b> והנה באופן כזה יש ג\"כ הפרש בין לבוש המח' ללבוש הדבור, דהרי במח' א\"א לחשוב היפך השכל דכפי חיוב השכל כן הוא חושב במחשבתו כו', אבל בדבור הרי יכול האדם לדבר היפך השכל לגמרי שגם אם שכלו מחייב כך ומ\"מ ידבר בדבור באופן אחר לגמרי כו', והיינו מפני שהמח' הוא לבוש המיוחד וע\"כ אינו מעלים על השכל והוא שמה שמחייב שכלו ה\"ז בא בהתגלות במח' ואינו מתעלם כלל, משא\"כ הדבור הוא לבוש הנפרד וע\"כ יכול להעלים על השכל כו'. וכמו\"כ י\"ל בבחי' בריאה ויצי' דברי' היא כמו המח' שהלבוש בטל אל המלובש, וכמו\"כ בעולם הברי' ששם הוא בחי' הביטול דמצד קירוב הברי' אל האצי' ה\"ז בבחי' ביטול כו', שהרי גם הנבראים דברי' אינם בבחי' מציאות לעצמן עדיין והן בבחי' ביטול שמיוחדים במקורם כו', וכידוע בענין נבראים דעדאתכ\"ס שזהו עד\"מ כמו דגים שבים שמהותם מים ומובלעים בתוך מקורם ושם הוא דוקא חיותם וקיומם כו', דכמו\"כ הוא בנבראים דברי' שאינם עדיין בבחי' מהות ומציאות בפ\"ע וה\"ה מיוחדים במקורם האין האלקי כו', ומה שהן נבראים נבדלים הוא\nהרגש חיותם שמרגישים את החיות שלהם וזהו מציאותם כו', ומכ\"ש שהע\"ס דברי' הם בבחי' ביטול ויחוד במקורם כו'. וזהו שנק' גופים דעם היותם בחי' לבוש לבד ה\"ז כמו הלבוש המיוחד שבטל אל המלובש ועיקר ההנהגה הוא מהמתלבש כו', שהלבוש אינו דבר בפ\"ע והמתלבש מאיר ע\"י בגילוי כו', וכמו הגוף שבטל ונגרר אחר הנפש והעיקר הוא חיות הנפש כו', וכמ\"ש עור ובשר תלבישני הרי הבשר הוא רק לבוש ומ\"מ הוא לבוש המיוחד כו', וכמו\"כ עולם הברי' שהלבוש הוא כמו גוף המיוחד ובטל כו'. ועיקר ענין הלבושים הוא בעולם היצי' שזהו התגלות בחי' יש היינו מה שיש בחי' מציאות דבר לעצמו בבחי' מורגש כו', וזהו כמו לבוש הנפרד מן העצם כו'. ועם היות שהלבוש ג\"כ נמשך אחר האדם הלובשו כו', ובפרט בדמיון הנ\"ל בהתלבשות הנה\"א בנה\"ב שזהו ג\"כ כדוגמת התלבשות הנפש בגוף דהיינו בבחי' התלבשות פנימי כו', ומ\"מ להיותו לבוש הנפרד יכול להיות שאינו בטל ואז ה\"ה מעלים על המלובש כו', וכמו הגוף הגשמי הגם שנמשך אחר"],[3601331073,"האדם ה\"ה מכסה על הגוף כו', וכמו\"כ בעולם היצי' שאין הביטול בתכלית ויכול להיות צד פירוד כו', וכידוע דעה\"ד טו\"ר הוא בעולם היצי' הרי יכול להיות טו\"ר כו', וכנודע דמט\"ט כמו שהוא בעולם היצי' שנק' שרו ש\"ע כו' מחציו ולמעלה טוב ומחציו ולמטה רע, ולא שהוא עצמו רע ח\"ו כ\"א שנמשך ממנו חיות לבחי' הרע ג\"כ, שהרי כתי' ואתה מחי' את כולם שגם הסט\"א צריכה לקבל חיות, ולכן מחציו ולמטה רע היינו שנמשך ממנו השפעה גם להרע לצורך קיומו כו', ומחציו ולמעלה טוב שנמשך ההשפעה לטוב כו', וזהו שאמרו אפקוהו למט\"ט זהו בחי' מט\"ט דיצי' כו' וכמ\"ש במ\"א, וזהו דבפרטי מדרי' ברי' היא בחי' גוף ויצי' לבוש כו'. אמנם ההיכלות הן העלמין והוא בחי' הישות שבכל עולם כו', וכידוע בענין עולם שנה נפש דנפש הוא בחי' החיות של כל עולם, ושנה הוא שהמשכת החיות הוא בבחי' רצוא ושוב (שזהו מפני שאין ערוך העולם לגבי החיות ע\"כ צ\"ל ההמשכה בדרך רו\"ש כו' כמ\"ש במ\"א) שמזה נעשה הזמן כו', ועולם הוא המקום היינו העולם עצמו שכולל הרקיעים והארץ וכל גופות הנבראים דדצח\"מ\nשבכל עולם כו', דכמו שיש ז' רקיעים גשמי' כמו\"כ יש ז' רקיעים רוחניים והן ז' היכלות כו', וענינם הוא להסתיר ולהעלים על האור כו', וזהו שמעמד הנבראים הוא בההיכלות וכמו מעמד ומצב המלאכים וקבלת אורם וחיותם הוא ע\"י ההיכלות דוקא, להיות שההיכלות מעלימי' את האור באופן שיוכל להתקבל בבחי' מציאות יש ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו\"כ לבוש המח' שהוא רק כפי חיוב השכל משא\"כ בדבור, וכמו\"כ ברי' בטל ומיוחד בלי שום צד פירוד, וכמו דגים שבים ובפרט הע\"ס דברי' ולכן נק' גופים שהלבוש הוא כמו גוף, ועיקר ענין לבוש הנפרד הוא ביצי', ולכן שם התחלת עה\"ד טו\"ר, והיכלות הוא העולם בחי' מקום וענינם להעלים, ולכן מצב המלאכים בהיכלות.</span>\n<b>תטז)</b> והנה התהוות ההיכלות הוא מהפרסאות (ושרשן הוא מבחי' העיגולים שזהו ג\"כ העלם וכמ\"ש במ\"א, אך התהוותם הוא מהפרסאות) ומסכים המבדילים כו', וידוע שענין הפרסא הוא כמו המשל כו', דכללות ענין המשל הוא דבר זר מעצם השכל ומעלים ומסתיר על השכל כו', אך במשלים גופא יש ג\"כ חילוקים שיש משל שמ\"מ מבינים מאתו השכל, דהתלבשו' השכל בהמשל הוא בכדי להבין אותו, רק להיותו שכל עמוק שא\"א להבינו ע\"י עניני' שכלי' מלבישי' אותו במשל, אבל הכוונה היא להבין ע\"י את הענין שכלי ומבינים את השכל ע\"י המשל כו' (והוא ג\"כ הסתר להיותו דבר זר כו', והיינו שבא המשל בענין אחר וממנו מבינים את הנמשל שאין זה כלל כמו אם היו מבינים את השכל שלא ע\"י המשל כו'). ויש משלים שמסתירים לגמרי והוא הנק' חידה, וכמו חידותיו של שמשון וכמו העובדות דרבב\"ח שהן מעלימים ומסתירים לגמרי כו', דהתלבשות זאת אינו בכדי להבין את הענין כ\"א הוא התעלמות לבד כו', והוא בענין עמוק ביותר שהוא למעלה מגדר גילוי ה\"ה בא בחידה שהוא שמתעלם בזה לגמרי כו'. וז\"ע ההיכלות\nשהן להעלים ולהסתיר על האור להיות בחי' יש ממש כו', ואינו דומה לבחי' הלבושים שהן ג\"כ העלם (ולא כמו חומר וצורה כנ\"ל)"],[3601331074,"דמ\"מ ע\"י הוא גילוי אור, וכמו לבוש המח' וגם לבוש הדבור שע\"י מאיר עכ\"פ אור השכל כו', דכמו\"כ יש לבושים ברוחני' וכידוע דנשמות בג\"ע שנהנין מזיו השכינה הוא ג\"כ ע\"י לבושים (והן הלבושים דמצות כו'), להיות דהנשמה כמו שירדה בבי\"ע ה\"ה בבחי' נברא יש ודבר כו', ובכדי שתוכל לקבל בחי' זיו השכינה שבג\"ע הוא ע\"י הלבושים כו', וכמו במשה כדי לקבל את התורה כתי' ויבא משה בתוך הענן כו' שהענן נעשה לבוש למשה שע\"י יוכל לקבל את התורה ולזון ממזון הרוחני כו', וכמו אדם הרואה ומסתכל באור צח ע\"י אספקלרי' דבלא האספקלרי' א\"א לו להסתכל כ\"א ע\"י האספקלרי' שהוא כמו לבוש המעלים קצת וע\"י הוא רואה את הדבר (וכמו הקליפות כגלדי בצלים שע\"ג העין כו'), וכמו\"כ הו\"ע הענן שבו נתכסה משה וע\"י הי' ביכולתו לקבל את האור כו', וכן לגבי למע' כתי' לבושו צדקה שזהו ג\"כ בחי' לבוש המעלים בכדי שיוכלו לקבל את האור כו', וכן במ\"ת כתי' הנה אנכי בא אליך בעב הענן בעבור ישמע העם כו', דבכדי שיוכלו לקבל את האור הוא ע\"י עב הענן כו', וכ\"ז הוא לבושים שאינם מעלימים\nלגמרי וע\"י הוא גילוי האור כו'. וצ\"ל דלבושים הנ\"ל הן לבושים דברי' שאינן מעלימים את האור כו', ולכן הגילוי הוא לנשמות דעם היותם בחי' יש הרי אינם בבחי' יש ממש וביכולתם לקבל אור אלקי כו', ולבושי היצי' הן בבחי' מסך מעלים כמו המשל כו', ומ\"מ מאיר ע\"י ג\"כ גילוי אור כו' (וכמו הדבור שהוא לבוש הנפרד שביכולתו להעלים על השכל כנ\"ל ומ\"מ ה\"ה מגלה ג\"כ כו'), אבל היכלות הן פרסאות המעלימים לגמרי וכמו החידה כו', והן לבושי העשי' שהן בחי' העלם והסתר לגמרי כו'. והנה כללות ענין ההפרש בין הפרסא שהיא ע\"ד כמו המשל לנמשל, והפרסא שע\"ד חידה י\"ל דלצורך התהוות היש בחי' הפרסא היא עד\"מ כמו המשל שמדבר מענין אחר כו', דכמו\"כ הוא בהתהוות היש שהוא דבר אחר שאינו אלקות כו', ובאמת אין לך דבר חוץ ממנו רק שנראה כמו מהות אחר כו', והפרסא שע\"ד חידה הוא לצורך ההמשכה בנוגה כו', והוא ההפרש בין תחלת התהוות העולמות קודם החטא שהי' ג\"כ בבחי' יש ומ\"מ הי' נראה ונגלה אלקות בעולם כו' וכמשנת\"ל (ד\"ה בא אל פרעה), ובין לאחר החטא שהיש הוא בבחי' משכא\nדחויא דנוגה כו'. ובפרטי' הוא ההפרש בין לבושי היצירה ובין לבושי העשי' שמעלימים לגמרי כו' (וכמ\"ש בענין שם דעשי' אל אד' בגימט' צו ואין צו כו'), ובלבושי' גופא זהו כענין לבוש המנעל וכמ\"ש מה יפו פעמיך בנעלים כו', שהנעל עשוי מעור בהמה שהוא עור גס המסתיר לגמרי על הרגל כו', ואינו דומה כמו בגד הארוג מחוטי צמר או פשתים שיש בו נקבים שיוצא ע\"י משקה וכה\"ג, אבל בגד עור אין המשקה יוצא ע\"י כו', רק יש בו חללים ונקבים דקים מאד שיוצאים בו השערות דבהמה כו', אבל הוא לבוש המסתיר כו', וכמו\"כ לבושי העשי' הן שמעלימים ומסתירים לגמרי כו'. וזהו דבזה\"ג אותותינו לא ראינו דבדורות הראשונים הי' גילוי אלקות בעולם והי' מצוי ענין הנסים שהיו נסים נגלים היוצאים מדרכי הטבע לגמרי, וכמו ביצי\"מ וקי\"ס ומ\"ת שהי' גילוי עצמות אוא\"ס שנקרעו ונתבטלו כל הפרסאות והי' גילוי אלקות שלא ע\"י לבושי הטבע כלל כו', וגם בזמן נביאים האחרונים כמו בדניאל וחבריו היו ג\"כ נסים נגלים כו' (עד שגם נ\"נ הודה כו'), ואח\"כ נס דפורים הי' בלבושי הטבע ומ\"מ הי' נגלה בזה אלקות וכמ\"ש ראו כל אפסי ארץ את ישועות אלקינו כו' דבכללות ההנהגה ראו"],[3601331075,"בזה ענין אלקי כו', וגם בזמן תנאים ואמוראים היו כמה נסים וגילוי אלקו' כו', אבל בזמן האחרון אותותינו לא ראינו שאינו מאיר גילוי אלקו' כו', הגם שבכל זמן הקב\"ה עושה נסים עם ישראל וכמא' כבשה א' בין ע' זאבים והיא מתקיימת וכמו בכל דור ודור עומדים עלינו והקב\"ה מצילנו כו', רק שמלובש בדרכי הטבע והולך ובא הכל בהנהגת הטבע ואין האלקו' נראה ונגלה כו', ובפרט בהנסים תכופים שבכל עת ושעה שאינם נגלים כלל, וכמארז\"ל ע\"פ לעושה נפלאות גדולות לבדו שאין בעל הנס מכיר בניסו מפני שמלובש מאד בלבושי הטבע כו', וכ\"ז הוא מפני שבדורות הראשונים הי' ההשפעה ע\"י לבושי הברי' והיצי' וע\"כ הי' מאיר גילוי אלקו' כו', ובזה\"ג ההשפעה היא ע\"י לבושי העשי' שמעלימים ומסתירים כו', וזהו בחי' לבוש הנעל שמעלים ומסתיר לגמרי כו' (ומ\"מ כתי' מה יפו פעמיך בנעלים דשרש הפרסאות הוא למע' יותר, וכנ\"ל דענין עמוק ביותר שאינו בגדר גילוי ה\"ה בא בדרך חידה כו', וכמו\"כ הוא שבהפרסאות המעלימים לגמרי יש בהם דוקא מבחי' עצמו' א\"ס ב\"ה, וע\"י העבודה שמסירים המסכים והפרסאות מאיר עי\"ז גילוי אור עליון יותר כו').\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש וישמע יתרו כהן מדין כו', דהנה כתי' וראיתי אני שיש יתרון לחכ' מן הסכלות כיתרון האור מן החשך, דיתרון האור הוא דוקא ע\"י בירור החשך כו', דז\"ע ירידת הנשמה למטה שהרי הנשמה כמו שהיא למע' כתי' חי ה' אשר עמדתי לפניו שהיתה עומדת באהוי\"ר בבחי' ביטול לאלקו' וירדה ונתלבשה בגוף ונה\"ב בכמה העלמות והסתרים והוא בשביל הבירור דנה\"ב כו', והוא ע\"י העבודה בהשגה והתבוננות אלקי דוקא בהתלבשות השכל הטבעי דנה\"ב שגם הוא יבין את הענין האלקי ויתפעל גם הוא לרצות באלקו' כו', עי\"ז נעשה יתרון אור בנה\"א וכמ\"ש ורב תבואות בכח שור דוקא כו', וע\"ז אמרו יש מפזר ונוסף עוד שע\"י הפיזור בירידת הנשמה למטה עי\"ז נוסף עוד כו', דטוב לי תורת פיך דנשמה למטה בגוף ונה\"ב מאלפי זהב וכסף שהן האהוי\"ר שהנשמה למודה ורגילה בהם למעלה כו', מפני שעי\"ז נעשה יתרון אור מכמו שהאור הוא מצ\"ע כו', וכמו\"כ יש יתרון לחכ' מן הסכלות סכלות הן חכמות חיצוני', ונק' סכלות להיות ידוע ההפרש בין חכ' דקדושה לחכ' דקלי' דחכ' דקדושה הוא ביטול\nוכידוע דעיקר ענין הביטול הוא בחכ' כו', וחכ' דקלי' היא תכלית הישות וכמ\"ש ראית איש חכם בעיניו כו' וכל גיא שוטה וע\"כ נק' סכלות, אך ע\"י בירור הסכלות עי\"ז נעשה יתרון בחכ' דקדושה כו', וכמ\"ש ותרב חכמת שלמה מכל חכמות בני קדם שע\"י חכמות בני קדם שנתרבה חכמת שלמה כו', וכתי' חכמות בחוץ תרונה, תרונה בחי' פנימי' הכתר בחי' שיר וטעמים כו', וע\"י שחכמות בחוץ עי\"ז דוקא תרונה שנמשך תוס' אור בחכ' מבחי' פנימי' הכתר כו'. וזהו מה שמ\"ת הי' ע\"י הודאת יתרו דוקא, דהנה יתרו הי' לעו\"ז דמשה, דמשה הי' בחי' חכ' דקדושה וכתי' בי' ונחנו מה בבחי' ביטול בתכלית ויתרו הי' חכ' דקלי' ולכן הי' כהן מדין ל' מדון וריב שזהו תכלית הישות כו' וכמ\"ש בלק\"ת ד\"ה החלצו, וכאשר הודה יתרו שזהו דחכ' דקלי' נתהפך לקדושה נמשך עי\"ז תוס' אור בחכ' כו', ועי\"ז הי' מ\"ת דאורייתא מחכ' נפקת ובכדי שיהי' ירידת והמשכת החכ' למטה הי' צ\"ל תוס' אור בחכ', וכידוע דכל ירידה והמשכה הוא ע\"י תוס' אור כו',"],[3601331076,"וזהו שע\"י שהודה יתרו שנתוסף אור בחכ' עי\"ז הי' ירידת והמשכת החכ' דתורה למטה כו', ומ\"ת הי' באמת לנש\"י שהן דוקא ראוים לקבל את התורה (וגם יתרו ע\"י הודאתו הי' ראוי כו'), רק בכדי שיהי' המשכת התורה זהו דוקא ע\"י הודאתו של יתרו כו', וזהו שנא' כאן כהן מדין דהיינו שע\"י שכהן מדין נהפך לקדושה עי\"ז הי' מ\"ת כו'. וזהו ג\"כ חותן משה דהנה ביום חתונתו זה מ\"ת, שהו\"ע חות דרגא כו', והתורה נק' ע\"ש משה כמ\"ש זכרו תורת משה כו' והיא בבחי' ירידה והמשכה שז\"ע חות דרגא כו', וחותן הוא שמפעיל את הירידה וזהו חותן משה שע\"י הי' ירידת והמשכת בחי' משה, ולכן נא' שניהם כהן מדין וחותן משה כו'. וזהו שפרש\"י קי\"ס שמע דסבת הודאת יתרו הי' ע\"י קי\"ס שהי' גילוי בחי' עתיק כמא' בעתיקא תלי' שעי\"ז נקרעו כל הפרסאות כו' וכמשנת\"ל (סד\"ה אז ישיר), הנה עי\"ז הי' ג\"כ הודאת יתרו דבחי' חכ' דקלי' תכלית הישות המעלים ומסתיר נהפך ג\"כ לקדושה כו'. ופרטי הענינים דוישמע יתרו ואשר עשה כו' וכי הוציא כו', י\"ל שהן ד' מדרי' דאו\"כ ולבושים והיכלות דקי\"ס דבעתיקא\nתלי' זהו בחי' האור בעצם שלמעלה מבחי' הכלים (דעתיק הוא שרש האו\"פ והוא למעלה מגדר כלים כו'), וזהו וישמע יתרו קי\"ס שמע גילוי בחי' האור העצמי כו' (שעי\"ז הי' ההודאה שלו כו' כנ\"ל), ואשר עשה אלקי' למשה ולישראל עמו זהו\"ע התלבשות אורות בכלים כו', וכידוע דאלקים הוא בחי' הכלים כו' שע\"י הכלים הוא בחי' גילוי האור כו', וזהו למשה ולישראל דמשה הוא בחי' חכ' דאצי' וגם ישראל מושרשים באצי' כו', וגם שזהו הגילוי שע\"י לבושי הבריאה דהגילוי הוא לנשמות כו' כנ\"ל, ומ\"ש כי הוציא ה' את ישראל ממצרים זהו בחי' הלבושים וההיכלות, דהנה מצרים הוא בחי' מיצר מי והו\"ע מיצר הגרון שזהו בחי' הפסק שבין המוחין למדות כו' וכמשי\"ת, וזהו במדרי' הקדושה והו\"ע לבושי היצי' כו', ומצרים דלעו\"ז הוא המיצר וההעלם לגמרי שזהו ע\"י העלם ההיכלות ופרסאות המעלימים לגמרי כו', וזהו כי הוציא ה' שהיא היציאה מההעלמות וההסתרים כו', דמ\"ש אשר עשה אלקים כו' כ\"ז הוא בחי' גילוי אור כו', ומ\"ש כי הוציא הוא היציאה מההסתר כו'. וזהו וישמע יתרו קי\"ס שמע התגלות בחי'\nעצם האור ועי\"ז גם כהן מדין נהפך לקדושה ונתוסף עי\"ז תוס' אור בחכ' שעי\"ז הי' מ\"ת ירידת חכ' דתורה למטה שז\"ע חותן משה כו', את כל אשר עשה אלקים למשה ולישראל עמו זהו הגילוי בנשמות ע\"י הכלים ולבושי הברי' כו', כי הוציא ה' את ישראל ממצרים הוא היציאה מההעלמות וההסתרים שעי\"ז הוא יתרון האור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והתהוות ההיכלות הוא ע\"י הפרסאות שהן כמו משל מדבר זר ומ\"מ ענינו שיהי' עי\"ז גילוי, ויש משל כמו חידה על ענין עמוק ביותר וענינו להעלים לגמרי, וז\"ע ההיכלות ולא כמו לבושים דמ\"מ ע\"י גילוי, וכמו לבושי הנשמות בג\"ע, וכמו ויבוא משה בתוך הענן ולמעלה לבושו צדקה ובמ\"ת אנכי בא בעב הענן, וצ\"ל שזהו לבושים דברי' ולבושי יצי' כמו המשל ולבושי עשי' כמו החידה, וזהו עיקר ענין ההיכלות, והנה הפרסא שע\"ד משל הוא לצורך התהוות העולם כמו שהי' קודם החטא שהי' נראה בו אלקות, והפרסא שע\"ד חידה הוא לצורך ההמשכה בנוגה, והו\"ע לבוש המנעל של עור, וזהו דבזה\"ב ותו\"א היו ניסים נגלים ובזה\"ג אותותינו לא ראינו מפני שהוא ע\"י לבושי העשי'. וזהו וישמע</span>"],[3601331077,"<b>יתרו</b> דיתרון האור הוא מבירור החשך, וכמו\"כ יתרון החכ' דמ\"ת מאתהפכא דחכ' דקלי' שזהו הודאת יתרו, וענין וישמע יתרו אשר עשה אלקי' וכי הוציא, י\"ל שהו\"ע או\"כ לבושים והיכלות."],[3601331078,"<h3>בס\"ד. ש\"פ משפטים, פ\"ש, העת\"ר</h3>\n<b>זה</b> יתנו כל העובר על הפקודים מחצית השקל כו' עשרים גרה השקל מחצית השקל תרומה לה', וצ\"ל מהו אומרו זה יתנו והול\"ל ונתנו כל העובר כו'. גם מהו שאומר זה יתנו כו' מחצית השקל קודם שהודיע כמה הוא השקל, דאח\"כ אומר עשרים גרה וקודם אין יודעים כמה הוא השקל, וא\"כ מהו אומר סתם מחצית השקל והול\"ל שיתנו עשר גרה כו'. גם אחר שמודיע כמה הוא השקל אומר עוד מחצית השקל תרומה לה' הלא כבר אמר שיתנו מחצית השקל כו'. ולהבין זה ילה\"ק משנת\"ל ההפרש בין כלים ולבושים דכלים הוא שמקבלים את האור ומתאחדים עם האור וע\"כ עושים ציור ותמונה בהאור דהתגלות האור הוא לפי אופן הכלי כו', וכמו בחומר וצורה דמוח החכ' קר ולח ומוח הבינה חם ויבש דלפי אופן זה הוא כח החכ' והבינה זה בבחי' נקודה כללית וזה בבחי' התפשטות כו', וכן בבחי' חו\"ג שבהם הכל הוא לפי אופן הכלי מפני שהכלי מקבלת ומתאחדת בו כו', אבל לבושים הם נפרדים מן העצם וכמו אותיות המח' ואותי' הדבור שהן נפרדים מן האור וביכולת להחליפם דכלבוש תחליפם כו' וע\"כ הם מעלימים על האור כו'.\n<b>ונת'</b> דבכללות זהו באצי' ובבי\"ע דבאצי' הוא בחי' הכלים בבחי' אחדות ובי\"ע הם לבושים נפרדים דומשם יפרד כו', אך בבי\"ע יש ג\"כ הפרש בין לבושי הברי' ולבושי היצי' שזהו עד\"מ לבוש המח' ולבוש הדבור דלבוש המח' הוא לבוש המיוחד ואינו מעלים על האור, דהתגלות השכל מאיר בגילוי במח' כו', ולבוש ביכולתו להעלים על השכל וא\"כ גם מה שמגלה זהו ע\"י ההעלם כו', ולבושי העשי' הם עד\"מ לבוש המנעל העשוי מעור גס של בהמה שמסתיר לגמרי, כמו לבושי העשי' הם פרסאות ומסכים המעלימים ומסתירים לגמרי כו'.\n<b>תיז)</b> וביאור הענין הנה לפעמים נק' אותיות בשם כלים ולפעמים בשם לבושים, דהנה בזהר פ' תרומה דקס\"ז ע\"ב בענין התהוות כלים דאו\"א אומר אינון אתוון אגלימו גו משחתא, ופי' המק\"מ שהן האותיות שמהם נתהוו פרצוף או\"א, אוכ\"ל מספר\"ת פנים דאו\"א בד\"ק חי\"ה אחור דאו\"א, וכן הוא בע\"ח שער הנקודים פ\"ו דאותיות אלו הן כלים דאו\"א, ואותי' שעטנז גץ הן כלים"],[3601331079,"דתהו כו', ואומר שם דהאותי' לעולם הם בחי' כלים כו', אמנם לפעמים הרי האותי' הם בבחי' לבושים וכמו אותי' המח' ואותי' הדבור שהן לבושים כו'. אך הנה כללו' ההפרש בזה הוא בין אותי' עצמי' ואותי' הנבדלים מן העצם כו', דאותי' עצמי' הם שמיוחדים עם העצם וכמו אותי' החקוקים על האבן טוב הרי הם בגוף ועצם האב\"ט ומיוחדים בו, אבל כשחותמין על השעוה ה\"ה נבדלים מן האב\"ט כו', וכמו\"כ יש בנפש אותיות המיוחדים בהאור עד שא\"א להחליפם, וכמו האותי' דבריקת וסקירת השכל הרי אותי' אלו א\"א להחליף דכמו שמתגלה ההשכלה ממקור השכל ה\"ה באותו האותי' שמתגלה בהם ואינו שייך להחליפם, דבהשגת הענין אפשר לפשוט אותי' אלו ולהלביש אותי' אחרים אבל בהתגלות ההשכלה ממקורה א\"א להחליף האותי' כו', ובהשגה ג\"כ הרי גם במחשבת שכל שזהו מח' שבמח' שיכולים להחליף את האותי' כמשנת\"ל (ד\"ה וישמע יתרו), הנה עי\"ז מתמעט האור, וכמו שאנו רואים בחוש במחשבת שכל כשחושב הענין שכלי ואינו מכוון בהאותי' דהיינו שהאותי' באים ממילא, מאיר אור השכל בגילוי, וכשמכוון בהאותי'\nהיינו להחליף האותי' הרי מתמעט האור שאינו מאיר כ\"כ, ועיקר ענין החליפים של האותי' שייך בדבור שבמח' וכ\"ש בדבור והיינו דשם גם כשמחליף את האותי' אין זה עושה מיעוט בהאור כו' (וכמו שני חכמים זה מגלה את השכל באותי' אלו וזה באותי' אלו הרי אין בזה שום מיעוט בהאור השכל כו'), ונמצא דבמחשבת שכל וכ\"ש בנקודת ההשכלה האותי' מיוחדים שאינם יכולים להחליפם כו', והיינו דבאור פנימי ואותי' בבחי' בלתי מציאות ה\"ה בבחי' התאחדות, וחיצוני' האור ואותי' שהן בבחי' מציאות ה\"ה בבחי' נבדל כו'. וי\"ל שזהו ההפרש בד\"כ בין האותי' דש' הוי' והאותי' דשארי השמות כמו אד' ואלקים כו', והן אותי' דמ\"ה ואותי' דב\"ן כו', דאותי' דמ\"ה שהן אותי' דהוי' הם בבחי' כלים ואותי' דב\"ן שזהו האותי' דשארי השמות הן בבחי' לבושים כו'. ויובן זה מענין תושב\"כ ותושבע\"פ, דתושב\"כ הרי יסודתה הם אותיות התורה, ולכן מדקדקים באותיותי' בחסר ויתיר, ושיהיו בתמונתן ובצלמן דוקא, ושיהיו גולם אחד שלא יהי' בהם הפסק, ואם יש הפסק באות א' הס\"ת פסולה, ואסור להוסיף בה אותי' שגם\nאם מבין בתבונתו יותר ממה שבהאותיות בהדיא אינו רשאי להוסיף אפי' אות א', כי האותי' הם מורים על אופן המשכת האור, וכמו אות א' הוא יו\"ד בראשו ויו\"ד בסופו וקו באמצע והן בחי' ח\"ע וח\"ת, ולפעמים עושים היו\"ד שבסופו כעין דלי\"ת והוא רומז על בחי' מל' שנק' דלה, והקו שבאמצע הוא ת\"ת המחבר חכ' ומל', והו\"ע בריח התיכון המבריח חכ' ומל' כמ\"ש בזהר. והבי\"ת הוא קו למעלה וקו למטה וקו באמצע לצד ימין דקו העליון הוא בינה וקו התחתון מל' וקו שבאמצע ת\"ת המחבר בינה ומל' כמ\"ש בזהר ר\"פ שמיני דל\"ו רע\"א ובמק\"מ שם, ובס' התמונה אי' דציור הב' הוא ו' ד' והן דו פרצופין דז\"א ומל' כמו שכלולים בחכ' כו'. ואות ג' הוא וא\"ו ויו\"ד בסופו והוא בחי' יסוד שמשפיע במל', וזהו גימ\"ל גומל דלים כו', ואות וא\"ו הוא ג\"כ יו\"ד וא\"ו אלא שהיו\"ד בראשו והוא בחי' נקודת החכ' כמו שנמשך בוא\"ו, ובגימ\"ל היו\"ד בסופו דהיינו בחי' גמר השפע דיסוד במל' כו', וכן כל האותי' מורים על אופן המשכת האור כו', ולכן צריך להיות דוקא אותי' אלו שהאותי' הן לפי אופן האור והמשכת האור הוא דוקא באותי' וצירופים אלו כו'. וזהו שמצינו כמה ענינים שנאמרו ונשנו"],[3601331080,"בתורה דלכאו' הוא מיותר, כמו קרבנות הנשיאים שנא' בכל נשיא ונשיא קרבנו בפרט ולכאו' הול\"ל וכן הקריב נשיא פלוני כו', וכמו\"כ במספר השבטים שנא' בכל א' במספר שמות כל זכר לגולגלותם כו', וזהו מפני שצריך להיות ההמשכה בכאו\"א בפרט ע\"י האותי' והצירופים וע\"כ אינו מספיק מה שיאמר וכן הקריב כו', כי לא תהי' בזה ההמשכה כ\"א ע\"י האותי' והצירופים שבהם וע\"י הוא המשכת האור כו', והגם שאותן האותי' והצירופים ממש נאמרו בכאו\"א, הנה בהאותי' שהן לפי אופן האור עם היות שהאותיות אחת הן ההמשכות הן מיוחדות בהם, וכמ\"ש הפרד\"ס שער האותיות פ\"ב, כי בציור האותי' בכל אות יש כמה חילוקי' באופן הציור, וכמשנת\"ל באות ב' שהוא ג' קוין או דו פרצופין הרי בציור האות ב' גופא יש ב' אופנים, וכן בכל אות ואות יש כמה חילוקים באופן הציור שלו, והחילוק הוא באיזה מדרי' הוא האות והצירוף דבמדרי' זו ביאור האות והצירוף הוא באופן כך ובמדרי' אחרת באופן אחר (וכמו באות אל\"ף בציורו יש שמתבאר יו\"י ויש יו\"ד ויש י\"ו ו\"י וכן עוד כמה אופנים וכ\"ז הוא החילוק באיזה\nמדרי' הוא) וכמבו' בס' הקבלה, וזהו שנא' ונשנו הדברים בכל נשיא ושבט כי כאו\"א הוא במדרי' מיוחדת וצ\"ל ההמשכה לכאו\"א בפרט לפי האותי' והצירופים שבמדרי' ההיא כו'. וכ\"ז הוא בתושב\"כ (ועמשנת\"ל ד\"ה ואתחנן הא'), אבל בתושבע\"פ אינו נוגע האותי' דהעיקר הוא השכל והאותי' אינו נוגע כלל דזה אומר באותי' אלו וזה באותי' אחרים, וזה מפני שבתושבע\"פ אין האותי' מורים על המשכת האור, והיינו שאין המשכת האור ע\"י האותי', רק שהן לבושים לבד, ויכול להיות לבוש זה או לבוש אחר דכלבוש תחליפם כו', והגם דגילוי אור השכל הוא בתושבע\"פ יותר מבתושב\"כ שהרי בתושב\"כ אין אנו יודעים ההשכלה שבהאותי', דיש בתורה כמה סיפורי מעשיות שגנוז בהם סודות ורזין דאורייתא ואין אנו יודעים מה הוא, וגם הדינים שבתורה הנה לבד זאת שהתורה היא לא כמו ספר הדינים והמשפטים כ\"א כמו סיפור דבר מה שא' הקב\"ה למשה לאמר לישראל, הרי כל המצות נאמרו בה רק ברמז, ומתושב\"כ עצמה לא היינו יודעים שום מצוה איך ומה היא, ובתושבע\"פ הרי יש בה גילוי השכלה, ובה אנו יודעים כל מצוה איך\nלעשותה כו', והרי הכלים מגלים אור ולבוש מעלים על האור, וכאן הוא להיפך לכאו'. הענין הוא דהאור דתושב\"כ הוא אור עצמי וע\"כ הוא אור כללי, דעם היות שהוא ריבוי אור הרבה יותר מבתושבע\"פ אינו בבחי' התפשטות כמו תושבע\"פ שהוא בחי' התפשטות אור, משא\"כ תושב\"כ להיותו אור עצמי ההתגלות שלו אינו בבחי' התפשטות כו'. וכמו שידוע דבכל מדרי' הגבוה יותר שם מספר המרובה יותר, וכמו יחידות עשירות מאות אלפים ורבבות הרי א' בזהר בענין מאה שנה ועשרים שנה ושבע שנים דשבע בז\"א ועשרים בחו\"ב ומאה בכתר קוב\"ה דאתכליל מאתר עילאה סתימין דכ\"ס כו', ואלפים ורבבות ג\"כ בכתר, ומאה הוא בבחי' חיצוני' הכתר בחי' אריך, ואלפים בבחי' המשכה מפנימי' הכתר וכמ\"ש ונוצר חסד לאלפים דיגת\"ד הן המשכות ממו\"ס ופנימי' הכתר כנודע, ובפנימי' הכתר בחי' רבבה כו', והרי נמצא להיפך דבמדרי' הגבוה שם בחי' האחדות יותר וכמו אנת הוא חד ולא בחושבן דבחי' עתיק הוא בחי' חד כו', וכל שלמטה יותר המספר מרובה יותר כו'. וידוע שזהו ההפרש בין בחי' האורות לבחי' הכלים, דהאורות כל שלמעלה המספר"],[3601331081,"מרובה, וכל מה שיורד למטה המספר מתמעט, ובבחי' הכלים כל מה שלמעלה יותר המספר מועט יותר וכל שלמטה יותר מתרבה המספר כו', וידוע החילוק בזה דבכלים המספר המרובה הוא בבחי' התחלקות המספר ממש, ובאורות מה שלמעלה הוא מספר המרובה אין זה בבחי' מספר רק בחי' ריבוי האור כו', כי באורות אינו שייך ענין המספר כו' (ועמשנת\"ל ד\"ה ביום השמע\"צ הא'). ומה שאומרים אלפים ורבבות הוא לפי שאנחנו יודעים ענין הריבוי רק במספר אבל באמת אין זה במספר כלל, או ענין המספר בזה הוא שאם יתגלה יהי' במספר כזה, וכמ\"ש במ\"א על מ\"ש הזהר בגולגלתא יתבין תליסר אלפין עלמין דהכוונה בזה שאם יתגלה למטה יהי' מספר כזה כו', וזהו בחי' ריבוי האור שההתגלות אינו בבחי' מספר והתפשטות כו', וכמו עד\"מ שכל עמוק שבא במיעוט דברים דכל שהשכל עמוק ביותר ה\"ה בא במיעוט דברים יותר, והרי ריבוי האור בו הוא הרבה יותר מחיצוני' השכל הבא בריבוי דברים כו'. וכמו\"כ יובן דבתושב\"כ הוא אור נעלה וריבוי האור יותר הרבה מבתושבע\"פ רק שבא בבחי' כללות כו', ועוד זאת מה שהוא רק ברמז\nזהו לגבינו שאין אנו יכולים לקבל אור שלא ע\"י לבושים, וכמ\"ש הפרד\"ס שער אבי\"ע ספ\"א דלבושי הבריאה המה מוכרחים דא\"א להיות שום השפעת אור בלא לבושי הבריאה, דנשמה בגוף אינה יכולה לקבל האור מכלים דאצי' כ\"א ע\"י לבושי הברי' כו', וע\"כ אין אנו רואין האור והגילוי בתושב\"כ רק בתושבע\"פ, אבל אם יהי' הגילוי ע\"י האותי' דתושב\"כ הן בבחי' ריבוי האור יותר מבתושבע\"פ כו', והיינו לפי שהאותי' דתושב\"כ הן לפי אופן האור ועל ידן הוא המשכת האור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע דהנה בע\"ח אי' שאותיות הן כלים, והרי ידוע שאותיות הן לבושים, אך יש אותיות עצמיים כמו בחקיקה, ויש אותיות הנבדלים, וכמו אותיות שבנקודה השכלה, גם אותיות שבמחשבת שכל א\"א להחליף, ואם יחליף יהי' מיעוט האור, להיות פנימיים ומתאחדים, רק בדבור שהן חיצוניים יכולים להחליף, וי\"ל שזהו אותיות דהוי' בחי' מ\"ה, ואותיות דשארי שמות בחי' ב\"ן, וכמו בתושב\"כ הדקדוק באותיות מפני שהן לפי אופן האור ומגלים את האור, וזהו שנא' בכל נשיא קרבנו בפ\"ע מפני שההמשכה היא ע\"י האותיות, ובאותיות אלו באות א' יש כמה כוונות לפי אופן אור ההמשכה, וזהו בחי' כלים, ובתושבע\"פ אינו נוגע האותיות להיותם בחי' לבושים לבד, והרי כלים מגלים ולבוש מעלים ומפני מה תושב\"כ ברמז ותושבע\"פ גילוי, זהו מפני שתושב\"כ הוא אור עצמי וע\"כ ע\"ה ריבוי אור ה\"ה בבחי' כללי, וכמו מספר המרובה שבמדרי' העליונה שזהו ריבוי האור ולא במספר, וגם מפני שהגילוי אלינו הוא ע\"י לבושים דוקא, וכמ\"ש הפרדס דלבושי הברי' הן מוכרחים.</span>\n<b>תיח)</b> ועד\"ז הוא באותי' הוי' כאשר ידוע דהד' אותי' הוי' שהן צמצום והתפשטות והמשכה והתפשטות שזה מורה על הבאת והמשכת האור, הן בכללות האור והגילוי בעולמות והן בע\"ס דאצי' הכל הוא ע\"י ד' אותי' הנ\"ל, דיו\"ד הוא בבחי' נקודה והיא הנקודה הכוללת כל האור שיתגלה ובאה ע\"י צמצום אור העצמות, וכידוע המשל בזה מהשפעת השכל מהמשפיע אל המקבל"],[3601331082,"דבכדי שימצא האור שכל השייך אל המקבל זהו ע\"י שהמשפיע מעלים את אור שכל עצמו, דכאשר מאיר אור שכל העצמי אינו בערך שייכות אל המקבל וגם חיצוני' האור אינו ניכר כלל, רק כאשר מעלים האור השכל בעצמו אז נמצא חיצוני' האור השייך אל המקבל, והוא נמצא בבחי' נקודה הכוללת כל מה שיתגלה אל המקבל וגם נמצא בה בהעלם מעצמות שכל המשפיע שלמעלה מהמקבל, וזהו דלא קאים אינש אדעתי' דרבי' עד ארבעין שנין ואחר ארבעין שנין ה\"ה קאים כו', ודעתי' דרבי' זהו עומק חכמתו כו', והיינו לפי שנמצא גם מעומק חכמתו כו', רק זהו בהעלם ביותר בהנקודה ומה שהוא בגילוי יותר בהנקודה גופא הוא מה שכוללת כל הגילוי כו'. ואח\"כ צ\"ל ההתפשטות היינו מה שהמשפיע מפרט הפרטי' של הנקודה מה שיגלה לו מהנקודה ובאיזה אופן יגלה לו, שבזה צ\"ל ההשערה בחושי המקבל כמה שכל יכול לקבל ובאיזה אופן ביכולתו לקבל דלפי אופן זה הוא מפרט הפרטי' והענינים המביאים ומגלים את השכל כו', וכ\"ז הוא הצמצום וההתפשטות בהמשפיע עצמו כו'. ואח\"כ באה ההשפעה והגילוי אל המקבל כו', וקודם לזה צ\"ל\nג\"כ צמצום דגם כאשר מפרט פרטי הנקודה יש בזה ריבוי אור משכל הרב (עם היות שזהו חיצוני' האור) שלמעלה מהמקבל וע\"כ צ\"ל עוד צמצום להעלים האור כו', רק שאינו כמו צמצום הקודם שהוא בבחי' התעלמות האור לגמרי ונמצא עי\"ז אור שבאין ערוך לגבי אור הקודם, וכאן הרי כ\"ז הוא בחיצוני' האור אין הצמצום באופן כזה רק העלם ריבוי האור כו', אמנם ההמשכה אל המקבל תחלה היא בבחי' כללי' ואח\"כ בא בפרטי' וכמו משנה וגמ' כו', וזהו בחי' המשכה והתפשטות שהוא בחי' השטח הנתפס בהמקבל כו'. וכמו\"כ הוא בהמשכת האור בעולמות דתחלה הוא בבחי' נקודה הבאה ע\"י הצמצום דאוא\"ס ב\"ה, שהרי האוא\"ס שלפני הצמצום אינו בערך העולמות כלל, ובכדי שיהי' אור השייך אל העולמות ה\"ז ע\"י הצמצום שסילק אור הראשון עי\"ז נמצא בחי' חיצוני' האור השייך אל העולמות ונכלל בבחי' נקודת הרשימו הכוללת כל האור שיתגלה בעולמות מרוכ\"ד עד סוכ\"ד כו', וגם כוללת בחי' עצמות האור שלמעלה מבחי' שייכות אל העולמות כו', והוא שממשיכים ע\"י תומ\"צ שהכוונה בזה הוא להמשיך תוס' אורות דכמו שהי' אוא\"ס\nממלא כל מקום החלל קודם הצמצום כך יהי' גם לאחר הצמצום ועוד מדרי' עליונו' יותר כו' וכמ\"ש במ\"א, וג\"ז נמצא כלול בהנקודה כו', ואח\"כ ההתפשטות זהו בחי' הקו כמו שבא בבחי' מחה\"ק דא\"ק שאמרו ע\"ז צופה ומביט עד סוף כל הדורות כו', וידוע דדורות הוא מל' דרי דרי והן שורות הע\"ס דעקודים נקודים ברודים ובי\"ע כו', דהכל כאשר לכל הוא שעלה במחה\"ק דא\"ק כו', וידוע דא\"ק הוא בבחי' שטח דעם היות שאין שם בחי' מציאות כלל ומ\"מ הוא בבחי' שטח וכמא' צופה ומביט עד סוכה\"ד וכולם נסקרים בסקירה א' כו', הרי אף שהוא בסקירה א' ה\"ה צופה ומביט עד סוכה\"ד כ\"א בפרט כו', וזהו בחי' הה' שהוא בחי' התפשטות ושטח כו'. ובפרטי' בהקו גופא היו\"ד הוא ראשית הקו טרם שמתלבש בא\"ק כו', ומבו' במ\"א שזהו מ\"ש בע\"ח שיש כדוגמת עתיק לעילא מגולגלתא דא\"ק כו', והה\"א הוא בחי' מחה\"ק דא\"ק כו', וכ\"ז הוא עדיין בעצמו כו', ואח\"כ הוא הגילוי דבחי' עקודים נקודים ועתיק ואריך כו', שזהו אות וא\"ו שהוא ההמשכה וגילוי מבחי' א\"ק כו', והוא\"ו בראשו יו\"ד הוא בחי' הצמצום דא\"ק כו', ואין זה כמו הצמצום דא\"ס"],[3601331083,"שהי' בבחי' סילוק לגמרי משא\"כ הצמצום דא\"ק אינו בבחי' סילוק לגמרי כו', והמשכת הוא\"ו הוא בבחי' כללות עדיין כו', והה\"א הוא בחי' השטח הנתפס בהמקבל והן הע\"ס דאצי' כו', או שהשטח זהו בחי' הצנורות הנמשכים מהקו כו', וכידוע דהקו הוא הצינור הגדול הנמשך מאוא\"ס ב\"ה ויש צנורות פרטי' לכל ספי' בפרט וזהו בחי' השטח דה' אחרונה כו' וכמ\"ש כ\"ז במ\"א באורך. וכ\"ז הוא בכללות הגילוים, וכמו\"כ בע\"ס דאצי' בפרט דהיו\"ד הוא בחי' נקודת החכ', דחכ' הוא ראשית ההשתל' כו', והוא ג\"כ נקודה הבאה אחר הצמצום דאור הכתר (עמ\"ש בתו\"א ד\"ה פתח אלי'), דכתר הוא שלמע' מהשתל' וכמא' אנת הוא עילאה על כל עילאין סתימא על כל סתימין כו', וצ\"ל צמצום בבחי' הכתר ונשארה הנקודה דחכ' שהיא כוללת כל מה שיתגלה בסדר השתל' דע\"ס דאצי' כו', וגם כלול בהנקודה מה שלמעלה מהשתל' והוא בחי' הקוצו של יו\"ד והיו\"ד הוא מה שכולל כל מה שיתגלה כו', ולכן היו\"ד עם היותו נקודה ה\"ה בציור אות אבל הקוצו ש\"י אינו בציור אות כו', ואח\"כ הה\"א הוא בחי' בינה שהוא בחי' התפשטות והתגלות\nהפרטי' שבהנקודה דחכ' כו' דבינה ציירא ציורים כו', וכמ\"ש אפריון עשה כו' מעצי הלבנון דלבנון הוא בחי' הלובן דחכ' והוא בחי' הנייר שנושא עליו הציור כו', והציור הוא מבחי' בינה כו', וכ\"ז הוא בהעלם עדיין וכמ\"ש הנסתרות להוי' לאלקינו כו', ואותי' ו\"ה הן הנגלות לנו כו', דוא\"ו הוא בחי' המשכה כללי' עדיין וה\"א הוא בחי' מל' שזהו בחי' שטח שנתפס בהמקבל כו', הרי דהד' אותי' הוי' הוא שע\"י הוא המשכת האור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ועד\"ז אותיות הוי' הן באופן הבאת האור, ועד\"מ בצמצום אור המשפיע שלעצמו נמצא האור השייך להמקבל בבחי' נקודה הכוללת הכל ויש בה גם מעצמות שכלו, ואח\"ז מפרט הפרטים בעצמו, וצ\"ל עוד צמצום בבחי' מיעוט ונמשך השכל אל המקבל בבחי' כללות ואח\"כ בפרטיות וכמו\"כ לאחר צמצום הראשון נשאר נקודת הרשימו הכוללת כל האור שיתגלה וגם בחי' עצמות האור שנמשך ע\"י תומ\"צ, גם ראשית הקו היא בחי' נקודה יו\"ד ומחה\"ק דא\"ק ה' בחי' שטח, עקודים נקודים וכן עתיק ואריך המשכה בבחי' כללית ו', וע\"ס דאצי' שטח ה'. ובע\"ס יו\"ד חכ' הכולל הכל וגם עצמות האור הקוש\"י, בינה הוא ציירא ציורים ה' וכ\"ז נסתר, ו' בחי' ז\"א ה' אחרונה בחי' מל'.</span>\n<b>תיט)</b> ועוד יש המילוים דש' הוי' והן הד' שמות ע\"ב ס\"ג מ\"ה ב\"ן שזהו בחי' ההתגלות פרטי' בכל ספי', והיינו כל ספי' דחו\"ב ז\"א ומל' מה שכוללת בעצמה ה\"ז בא בבחי' התגלות יותר בהספי' עצמה כו', ואותי' המילוי הוא שכח ההתגלות שיש בכל אות דש' הוי' בא בהמילוי בבחי' התגלות הפרטי' יותר כו', והכל הוא בהספי' עצמן לא בבחי' השפעה והתגלות חוץ להספי' כו'. דהנה הד' שמות עסמ\"ב ש' ע\"ב בחכ' וש' ס\"ג בבינה וש' מ\"ה בז\"א וש' ב\"ן במל', והוא דאות י' דש' הוי' נעשה ש' הוי' שלם בד' אותי' י\"ה ו\"ה וגם במילואו האותיות שביו\"ד יש ו\"ד ובה' יו\"ד ובו' י\"ו ובה' אחרונה יו\"ד, וכן ש' ס\"ג הוא במילוי יודי\"ן רק הוא\"ו הוא במילוי אלף, דש' ע\"ב שבחכ' היו\"ד הוא חכ' שבחכ' והה\"י הוא בינה והוי\"ו מדות שבחכ' והה\"י מל' שבחכ', ושם ס\"ג בבינה"],[3601331084,"היו\"ד הוא חכ' שבבינה והה\"י בינה שבבינה והוא\"ו מדות שבבינה והה\"י מל' שבבינה, וכן בכל השמות כו', שזהו התגלות הפרטי' שבכל הספי' והכל הוא במהות הספי' עצמה כו', ולכן ש' ע\"ב הוא במילוי יודי\"ן דהיינו שכל המדרי' הן בבחי' מהות החכ' כו', וזהו שהה\"י הוא במילוי יו\"ד דהה\"י הוא בחי' הבן בחכ' שזהו כמו שהחכ' כוללת כח הבינה שגם זה הוא בבחי' חכ' בבחי' נקודה כו', וכן הוי\"ו שהן מדות שבחכ' הן במדרי' החכ', וכידוע שיש הפרש גדול בין המדות כמו שכלולים בבינה לכמו שכלולים בחכ' דבבינה הן בבחי' מציאות דבר ובחכ' אינן בבחי' מציאות ניכרת כלל כו', וכמ\"ש בבה\"ז פ' בלק עמאה\"ז דר\"ג ב' ע\"פ כי מראש צורים אראנו (ועמשנת\"ל ד\"ה ואשים דברי בפיך), ולכן בינה מקור קרוב למדות וחכ' בחי' מקור רחוק כמ\"ש בלק\"ת ד\"ה ביום השמע\"צ כנישין תהי, עם היות דחכ' היא עיקר המקור אך בחכ' א\"ז בבחי' המציאות כו', וידוע דנקודת יו\"ד מורה על הביטול וזהו שהחכ' היא יו\"ד שהיא בבחי' ביטול בתכלית כו', ולכן השראת אוא\"ס הוא בחכ' דוקא דאין אוא\"ס שורה אלא במה שבטל\nכו', וזהו ג\"כ שבכל האותי' המילוי הוא יו\"ד שהביטול דחכ' הוא בכל המדרי' הכלולים בחכ' כו', ומזה יובן דבכללות אצי' הוא הביטול דחכ', שהרי אצי' בכלל הוא בחי' חכ' וכמ\"ש בע\"ח בפי' כולם בחכ' עשית והו\"ע אבא עילאה מקננא באצי' כו', וא\"כ כמו שהבחי' דאצי' כשהן כלולין בחכ' הן בבחי' הביטול כמו\"כ באצי' בכלל הוא בחי' הביטול דחכ' כו'. גם ידוע דחכ' הוא מקור החסדים כו', וזהו ג\"כ שהמילוי יו\"ד דבחי' החסדים הוא בכל המדרי' שבחכ' כו', גם אצי' בכלל הוא בחי' רחמים וחסדים כו'. וש' ס\"ג הוא ג\"כ במילוי יודי\"ן דהרי היו\"ד דש' ס\"ג הוא בחי' חכ' שבבינה (בחי' וחכם בבינה) ה\"ה בחי' יו\"ד, וגם אות ה\"י הוא במילוי יו\"ד להיות דחו\"ב הן תרין ריעין דלא מתפרשין כו', והענין הוא דה\"י הוא בחי' בינה שבבינה דבזה הוא יחוד חו\"ב, דאוא\"ס שורה ביחודם וע\"כ הוא מילוי יו\"ד דאין אוא\"ס שורה אלא ביו\"ד שהוא בחי' הביטול שבבינה כו' ואות וא\"ו הוא מילוי אלף, הענין הוא דהנה ציור אות א' הוא יו\"ד בראש ויו\"ד בסוף וקו באמצע, והקו הולך באלכסון מהגבוה אל הנמוך\nוהוא מהגבו' אל הנצח, הרי קצהו העליון בחי' גבו' וקצה התחתון בחי' חסד, ונמצא כלול מחו\"ג כו', והיודי\"ן שבו הנה היו\"ד שבראשו מחובר בקצהו התחתון שהוא בקו הימין והיינו להיותו בחי' חכ' מקור החסדים, והיו\"ד שבסופו נמשך מקצהו העליון שהוא בחי' גבו' והיינו מפני שהמל' בנינה מן הגבורות כו', הרי שהאלף כלול מחו\"ג כו', וז\"ע מילוי א' דש' ס\"ג דבינה לפי שבינה מינה דינין מתערין כו', דחכ' הוא בחי' חסדים כולה ובינה דינין מתערין כו' רק זהו בסופה כי הבינה עצמה היא בחי' דרור עלמא דחירא בחי' יובלא עילאה כו', ולכן הבינה היא בחי' שמחה וכמ\"ש אם הבנים שמחה כו', רק בסופה מתערין דינין כו', ועד\"מ היין משמח לב האדם דבשעת השמחה יכול לקבל כל הנגדיים וימחול גם לשונאו כו', ומ\"מ יכול להיות הסתעפות דינין ורוגז והוא יין המשכר שגורם חמימות וכעס כו', וכמו\"כ בחי' הבינה שהיא בחי' שמחה מ\"מ בסופה יכול להיות דינין וגבו' כו', וזהו שהמילוי א' הוא באות ו' דוקא, שהוא\"ו מורה על המשכה והיינו שהגבורות הן בסופה היינו כשנמשך בבחי' המדות כו',\nומ\"מ הגבו' שבה כלולים ג\"כ בחסדים שז\"ע אלף שכלול מחו\"ג כו'. וש' מ\"ה הוא במילוי אלפין דעיקר ענין חו\"ג הוא בז\"א"],[3601331085,"כו', וש' ב\"ן במילוי ההי\"ן והיינו שהמילוי הוא כמו עצם האות וזה מורה על בחי' צמצום ומיעוט האור בבחי' מל' כו', וכמו עד\"מ מי שמקבל איזה שכל וסברה מן הרב אם משיג עומק השכל ביכולתו להרחיב הענין ולהשפיע יותר ממה שקבל אבל אם אינו משיג עומק הענין אינו יכול להשפיע רק כמו שקבל מן הרב כו', כמו\"כ בחי' המל' מפני צמצום האור הרי המילוי הוא כמו עצם האות כו', וכ\"ז הוא בש' הוי' שהאותי' ה\"ה מורים על אופן המשכת האור שהוא באותי' אלו דוקא כו', אבל אותי' דב\"ן שהן שארי שמות ה\"ה בבחי' לבושים וכמו האותי' דתושבע\"פ אין נוגע האותי' לפי שהן לבושי' לבד כנ\"ל, כמו\"כ האותי' דב\"ן הן בבחי' לבושי' לבד כו', שהרי הכלים דברי' וגם האורות נ\"ר הן בחי' נברא וע\"כ הן בחי' לבושים לבד כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והמילוים דש' הוי' עסמ\"ב הוא ההתגלות פרטיות דכל ספי' בעצמה וכפי מהותה, בש' ע\"ב אות יו\"ד בכל האותיות דגם בינה ומדות ומל' הכל בבחי' נקודה ובבחי' ביטול ובבחי' חסדים וכן אצי' ביטול וחסד דאבא עילאה באצי', וש' ס\"ג ג\"כ במילוי יודי\"ן דחו\"ב תרדל\"מ רק הוא\"ו במילוי אלף, שכולל חו\"ג להיות דבינה בסופה היינו בהמדות דינין מתערין והו\"ע יין המשכר ועצם הבינה יין המשמח, וש' מ\"ה במילוי אלפין מפני שבז\"א עיקר בחי' חו\"ג, וש' ב\"ן במילוי ההי\"ן שמפני צמצום ומיעוט האור במל' הגילוי הוא כמו העצם, וכ\"ז בש' הוי' ואותיות דשארי שמות הן בחי' לבושים.</span>\n<b>תכ)</b> אמנם צ\"ל והלא ש' אלקים הוא בחי' הכלים וכידוע דהוי' אלקי' הן בחי' אורות וכלים כו', וידוע שהז' שמות שאינם נמחקים (ובפרטי' הן י' שמות) ה\"ה בכלים דע\"ס ש' אל בחסד וש' אלקי' בגבו' כו', אך הענין דזהו כמו שהן באצי' דבאצי' הכל הוא בבחי' הכלים שגם השארי שמות הן בבחי' כלים כו', ומ\"מ י\"ל דגם באצי' הנה שארי שמות הן בחי' חיצוני' הכלים, דש' ע\"ב שהוא כלי החכ' וש' ס\"ג כלי הבינה כו' הן בחי' פנימי' הכלים, אבל שארי שמות הן בחי' חיצוני' הכלים להיותן בחי' ש' ב\"ן, שהרי בכללות ש' הוי' הוא בחי' ש' מ\"ה ושארי השמות הן ש' ב\"ן, וע\"כ הד' שמות עסמ\"ב שהן שמות הוי' ה\"ה בחי' פנימי' הכלים ושארי השמות שהן ש' ב\"ן ה\"ה בחי' חיצוני' הכלים כו', ועם היות דבפרטי' יש בחי' צלם אלקי' ודמות אלקי' כו' כמ\"ש במ\"א, מ\"מ בכללות ה\"ה בחי' חיצוני' הכלים כו'. וההפרש ביניהם ידוע ונת\"ל באורך דפנימי' הכלים הוא עצמות הכלי מה שהיא כלי לקבל והוא לקבל לעצמה לא בבחי' השפעה וגילוי כו', וחיצוני' הכלי הוא בחי' ההשפעה וגילוי חוץ לעצם\nהספי' וע\"כ היא בבחי' נבדל מן העצם כו', וכמשנת\"ל בענין בצלמנו כדמותנו דבצלמנו הוא בחי' צורה עצמי' דבכלים הוא בחי' הצורה החקוקה בהעצם שמיוחדת בהעצם כו', וכדמותנו הוא בבחי' נבדל מן העצם כו', ולכן מה שהכלי עושה ציור ותמונה בהאור היינו שהאור יהי' בבחי' אור החכ' כו', ה\"ז דוקא בחי' פנימי' הכלי כו', שהרי האור לכל השיטות ה\"ה בבחי' פשיטות לגבי הכלי והכלים ה\"ה העושים ציור בהאור להיות בבחי' אור החכ' והחסד כו', והיינו פנימי' הכלי דוקא שמקבלת האור בתוכה ומתאחדת בהאור עד שעושה בו ציור ותמונה כו', אבל"],[3601331086,"בחי' חיצוני' הכלי אינה עושה ציור בהאור כי ענינה אינה לקבל את האור כ\"א לפעול בכח האור וכמו איהו וגרמוהי חד לברוא בהם וע\"י מאין ליש כו', או לפעול פעולת הגילוי כו', שזהו רק שהאור מתלבש בהכלי ופועל על ידה מפני שהאור מתעלם בה לפעול פעולה שחוץ לעצמו כו', ומה שמתלבש בחיצוני' הכלי הוא בחי' חיצוני' האור ופנימי' הכלי מתאחדת בפנימי' האור כו', דבכלל מה שבא בבחי' התלבשות והתעלמות הוא בחי' חיצוני' האור דפנימי' האור אינו בא בהתלבשות (ומ\"מ גם פנימי' הכלי הוא שפנימי' האור הוא בבחי' התלבשות רק שההתלבשות היא באופן אחר כו' וכמ\"ש במ\"א). וכמו עד\"מ מה שהמשפיע מלביש את השכל בעניני' והסברים ה\"ז חיצוני' השכל, דפנימי' השכל כמו שהוא לעצמו אינו מלבישו בענינים כי אינו צריך להם שמבין עצם הענין כמו שהוא, רק חיצוני' השכל להיות שהמקבל לא יבין אותו כך ה\"ה מלבישו בעניני' והסברי' הרי שההתלבשות היא בחיצוני' האור, ובהתלבשות זאת מתעלם האור שהרי כמו שהוא לא יבין אותו המקבל מפני שהוא בבחי' ריבוי אור לגבי' וע\"י ההתלבשות מתעלם\nהאור כו'. וכמו\"כ הוא בחי' חיצוני' הכלים שבהם מתלבש ומתעלם האור כו', ובודאי הוא שגם חיצוני' הכלים מקבלים את האור אמנם עיקרם הוא בחי' התלבשות שמלבישים ומעלימים על האור כו', דבחי' פנימי' הכלים הוא שעושה תואר ותמונה בהאור וגם מתאר ומגלה את האור כו', שז\"ע ש' התואר שמתארת ג\"כ את האור כו' וכמשנת\"ל, וזהו ע\"י שמקבלת את האור ומתאחדת בהאור כו', אבל חיצוני' הכלי אינה עושה תואר בהאור ואינו מתאר ומגלה את האור, כי ענינה הוא רק שהאור מתלבש בתוכה ומתעלם על ידה לפעול פעולה שחוץ לעצמותו כו'. וי\"ל דבחי' השתל' הספי' זמ\"ז וכן בהתלבשות הפרצופים זב\"ז ה\"ז ע\"י בחי' חיצוני' הכלים שהוא בחי' השפעה וגילוי חוץ לעצמות של הספי' כו', שהרי ההמשכה מן הספי' העליונה אל התחתונה הוא שרק בחי' החיצוני' שבעליון נמשך ומתלבש בהתחתון וההתלבשות הוא שהעליון מתעלם בהתחתון כו', וכמו כאשר נמשך מחכ' לבינה ה\"ז רק בחי' חיצוני' החכ' וכמו נקודת ההשכלה (שזהו השכלי דחכ' שאין זה עצמי' החכ' כו' וכמשנת\"ל), ונקודת ההשכלה הרי מתעלם בבינה וכידוע\nשההשגה מעלמת על הנקודה כו', ומה שבא ההתגלות הוא ההשגה לא הנקודה, הגם שא\"א להיות השגה בלי נקודת השכלה, הרי לא הנקודה היא המתגלית כ\"א ההשגה רק שזה שמבינים את הנקודה אבל ההתגלות היא ההשגה כו', וזהו שהעליון מתעלם בהתחתון שההתגלות היא מדרי' התחתון כו', והיינו מפני שהמדרי' מתעלמת בעצמה בהתלבשותה בהמדריגה התחתונה, וזהו שההתלבשות היא ע\"י בחי' חיצוניות הכלים דחיצוניות האור מתעלם בה כו' כנ\"ל, וכמו\"כ הוא בשכל ומדות הרי מה שנמשך מן השכל אל המדות הוא רק חיצוני' השכל וזה מתעלם בהמדה, דמה שבא בהתגלות בלבו ולזולתו הוא התפעלות המדות, רק שהמדות הן שכליי' לא טבעיי' אבל ההתגלות הוא מדות כו' (ועם היות שההנהגה היא מהעליון כמשנת\"ל ד\"ה וישמע יתרו, מ\"מ ה\"ה מתעלם שההתגלות הוא המלביש כו'). והמשכה זאת הוא מבחי' חיצוני' שמלבישים ומעלימים על האור כו', באופן שי\"ל דבחי' חיצוני' הכלים זהו בחי' לבושין כו', ועם היות שהן מקבלי' והיינו שהן בחי' כלים כו', מ\"מ י\"ל דבד\"פ באצי' גופא זהו בחי' לבושין כו', וזהו דהז' שמות הן בבחי' ז\"א דבבינה הרי השם"],[3601331087,"הוא הוי' רק בניקוד אלקי' כו', ושארי השמות אל אלקים כו' הן במדות דז\"א שזהו בחי' לבושין כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וצ\"ל והלא ש' אלקים וכל השמות שאינן נמחקים הן בכלים, י\"ל דשמות עסמ\"ב הן בפנימיות הכלים שמיוחדים בהאור וענינם לצייר ולתאר האור ולקבל לעצמן וגם לתאר ולגלות את פנימיות האור, ושארי השמות הן בחיצוניות הכלים דחיצוניות האור מתלבש ומתעלם בהם, ועד\"מ התלבשות השכל בלבושי' והסברים בכדי שיתקבל להמקבל, וענינם הוא לפעול חוץ לעצם, וי\"ל שהו\"ע השתל' הספי' זמ\"ז והתלבשות הפרצופים זב\"ז שרק חיצוניות העליון הוא שמתלבש ומתעלם בההתלבשות, וכמו בחו\"ב שההתגלות הוא רק ההשגה ובמוחין ומדות ההתגלות הוא המדה, וע\"ס הן בחי' לבושין במדרי' דאצי' ולכן הן בז\"א.</span>\n<b>תכא)</b> וכ\"ז הוא באצי' דבד\"כ הכל הוא בבחי' כלים כו' דאצי' בכלל הוא בחי' אחדות כו', אך בי\"ע בד\"כ הן בחי' לבושים דומשם יפרד כו', אמנם יש בזה הפרש בין לבושי הברי' ולבושי היצי' שהן עד\"מ מח' ודבור כו', וי\"ל דכמו שבאצי' יש הפרש בין פנימי' הכלים וחיצוני' הכלים דפנימי' הכלים מקבלים את האור ואינם מעלימים על האור אדרבה מתארים ומגלים את האור כו', וחיצוני' הכלים מלבישים ומעלימים את האור כו', כמו\"כ לבושי הבריאה מגלים את האור שהרי אור השכל כמו שהוא מתגלה במח' שאין המח' מעלמת על השכל כו' כמשנת\"ל ד\"ה וישמע יתרו (ובכללות גם לבושי הבריאה הן בחי' לבושי' ומ\"מ ה\"ה כמו בחי' הכלים, וכמשנת\"ל דאותי' עצמי' כאותי' דברק המבריק ואותיות דמחשבת השכל ה\"ה מיוחדים עם האור שא\"א להחליפם כו', וזהו דבאצי' בכללות הן בחי' כלים ובד\"פ בחי' חיצוני' הכלים זהו כמו לבושים, ובבי\"ע בכללות הן בחי' לבושים ובד\"פ הברי' היא כמו בחי' כלים כו'). ובזה יובן שהרי לפי משנ\"ת הרי יש יתרון בלבושי הברי' שהן כמו לבוש המח' עד\"מ על ענין\nדהתלבשות הפרצופים כו', דהרי בהתלבשות הפרצופים המלובש מתעלם בההתלבשות ומה שמתגלה הוא המלביש ובהתלבשות במח' הרי המלובש הוא המתגלה כו', ובאמת התלבשות הפרצופים הוא למעלה במדרי' שזהו באצי' שהכל הוא בבחי' כלים כו', ומ\"מ יש יתרון בלבושי הברי' מפני שהן בדוגמת בחי' פנימי' הכלים שמגלים את האור כו', אבל לבושי היצי' הן בדוגמת בחי' חיצוני' הכלים שמעלימים את האור לפי שזהו לבוש הנבדל מן העצם (כמו האותיות שהן בבחי' מציאות כו' כנ\"ל) ומעלים על האור כו', ועם היות שהן ג\"כ מגלים ה\"ז גילוי שע\"י ההעלם כו'. וי\"ל שזהו ע\"ד שמבואר במ\"א שיש המשכה שבבחי' אותי' והמשכה שבבחי' שערות כו', עד\"ז הוא ההפרש בין לבוש המח' ולבוש הדבור (עמ\"ש בלק\"ת ד\"ה והניף ידו ובתו\"א ד\"ה ועשית בגדי קדש דאותי' הדבור הן כדוגמת השערות כו'), דשערות הן ע\"י הפסק האור כו', והפרש ביניהם ידוע דבבחי' דצח\"מ שבאדם האותי' הן בחי' חי ושערות בחי' צומח (ועמשנת\"ל מזה בד\"ה זאת חקת התורה הב' ושם נת' דחכמת הדבור הוא בחי' חי כו'), דצומח הוא דומם בעצם מהותו רק\nשיש בו התפשטות חיות כו', וחי הוא שיש בו נפש החיונית כו', וכמו\"כ הוא בחי' ברי' ויצי' דברי' הוא בחי' חי כו' (ואי' במק\"מ"],[3601331088,"דלבושי שבת ויו\"ט יהיו של משי שהן מדרי' חי שזהו לבושי הברי' כו'), דעולם הברי' הוא היש הראשון שנברא מהאין האלקי ומאיר שם האין האלקי בגילוי כו', ויצי' הוא בבחי' צומח דשערות דיצי' בחי' יש ומאיר שם רק בחי' התפשטות ההארה האלקי' כו', ומ\"מ בעולם היצי' מאיר ג\"כ גילוי אלקו' וכמו ע\"י אותי' הדבור מאיר עכ\"פ גילוי אור השכל כו', והגם דהגילוי ביצי' הוא כמו ע\"י הפסק העור כו', ה\"ז כמו עור האדם שהוא עור דק שאינו מפסיק ומעלים כ\"כ כו'. אבל ענין ההיכלות שהן לבושי העשי' ה\"ה עד\"מ עור הבהמה שהוא עור גס המעלים ומסתיר לגמרי, דעם היות שגם בעור הבהמה יש נקבים שצומחים מהם שערות הבהמה ה\"ז בבחי' צמצום היותר אפשרי עד שיונקים מהם הע\"ש דנוגה כו', וכמ\"ש כרחל לפני גוזזי' נאלמה שיונקים מבחי' השערות כו', וה\"ז עד\"מ כמו חכם המעתיק איזה שכל וסברה מלה\"ק לל' אחר שהוא ל' הסכמי דהרי לה\"ק אינו הסכמי כ\"א יסודתו במדרי' גבוהות דקדושה כו', וע\"כ באיזה אותי' שמלבישים אין זה העלם לגמרי כו', אבל כשמלבישים הענין בל' אחר ה\"ז העלם גמור כו', או\nכמו קטן המדבר באיזה שכל עמוק ששמע או ראה באיזה ספר, הגם שמבינים קצת מן השכל ה\"ז באין ערוך לגמרי כמו שהשכל הוא באמת כו', ויותר מזה הוא הסתר החידה כו', ובדוגמא כזאת הו\"ע צירופי החלומות דעם היותם מהרהורי דיומא וכמו רעיונך על משכבך סליקו כו' ה\"ז בא בענינים ובצירופים אחרים לגמרי כו', ועד\"ז הוא לבושי העשי' שמעלימים לגמרי כו'. והענין הוא דהנה אי' בפע\"ח שער עולם העשי' פ\"ג בכוונת צו את בנ\"י דשם דעשי' הוא אל אד' בגימט' צו ואין צו אלא ע\"ז כו', ולכאו' תמוה שהרי השם הנ\"ל הוא במדרי' הקדושה ואיך הוא בגימט' צו דאין צו כו', אך זהו מפני ההתלבשות בלבושי העשי' שהאור מתעלם ביותר עד שנמשך יניקה גם לסט\"א כו', וזהו שארז\"ל ישראל שבחו\"ל עובדי ע\"ז בטהרה, והלא רוב ישראל הם בחו\"ל, אך הענין הוא לפי שמקבלים השפעתם ע\"י לבושי העשי' והוא ההתעסקות בענינים גשמי' כמו במו\"מ שיכול להיות שיחשוב אותם לדבר מה כו', וכן במה שמקבל חיותו מאכו\"ש גשמי שמתאווה אל הגשמי ומתענג בו בתענוגי בנ\"א כו', שזהו מחמת ההעלם דהאור האלקי, שבאם הי'\nמאיר אלקו' בעולם לא הי' לזה מקום כלל, וכמו קודם החטא שהי' נראה ונגלה אלקו' בעולם כמשנת\"ל (ד\"ה בא אל פרעה) לא הי' תאוה גשמי' כלל כו', וכמו\"כ בעסק מו\"מ כשמחשב את הגשמי למקור פרנסתו ומעמיק שכלו בזה, דבאמת הרי ברכת ה' היא תעשיר כו', ורק בחסד ה' עלינו בכדי שיהי' חיות גשמי ה\"ז בא בלבושי עשי' כו' כנודע, ובאופן כזה לא הי' מחשב את הגשמי והי' בטל לאלקו' אשר הוא הנותן לו כח כו', ומכ\"ש שלא הי' שום נדנוד איסור בהעסק כו', אבל כשמחשב את הגשמי ומעמיק ומטריד שכלו בזה ה\"ז השתחוואה לע\"ז ברוחני' כו', וכ\"ז שייך בעשי' מחמת העלם והסתר האור ביותר כו'. ומ\"מ כתי' מה יפו פעמיך בנעלים דהעיקר הוא בירור ותיקון העשי' ועי\"ז נעשה יתרון האור כו', וע\"ז הוא ירידת הנשמה למטה שנתלבש בגוף ונה\"ב בכדי לתקן את הנה\"ב וכל הדברים התחתונים כו', דהנה הנשמה שרשה מבחי' פנימי' הכלים וכמא' נשמה שנתת בי טהורה היא דכל הנשמות שרשן באצי' בבחי' פנימי' הכלים דאצי' כו', וגם כמו שהן בבי\"ע שרשן בעולם הברי' שז\"ע לבושין תקינת לון דמנייהו פרחין נשמתין כו', וכמא' ישראל עלו במח' כו',"],[3601331089,"וההפרש הוא דהנשמה כמו שהיא באצי' ה\"ה למע' מהתלבשות בנה\"ב וכמו שהיא מעולם הברי' ה\"ה בחי' התלבשות בנה\"ב כו' וכמשי\"ת, והנה\"ב הוא מנוגה שזהו ע\"י המסכים ופרסאות המבדילים כו', וירדה הנשמה להתלבש בגוף ונה\"ב לתקנו ולבררו שיהי' ג\"כ בטל לאלקות כו', ועי\"ז הוא דוקא יתרון האור כו'.\n<b>ועפ\"ז</b> יובן מ\"ש זה יתנו כו' מחצית השקל עשרים גרה השקל כו', הנה עשרים גרה הן העשר כחות דנה\"א ועשר כחות דנה\"ב, ובפרטי' בנה\"א הן עשר כחות דשרש הנשמה כמו שהיא באצי' ועשר כחות דנשמה דברי' כו', וכמשנת\"ל בענין רוח רעש ואש דבי\"ע ודאצי' שזהו בעשר כחות הנפש דמוחין ומדות כו', ועז\"א זה יתנו מחצית השקל מה שהשקל שלם הוא עשרים גרה יתנו מחצית השקל, והן העשר כחות דנה\"ב שזהו תכלית הכוונה בירור ותיקון הנה\"ב דוקא וכן בנה\"א הכוונה הוא דוקא העבודה דנה\"א המלובש בנה\"ב כו', דירידת הנשמה למטה אינו בשביל עצמה, וע\"כ אין הכוונה בעבודתה מצ\"ע כ\"א שתעבוד לברר ולתקן את הנה\"ב, והוא שתהי' ההתבוננות בענינים השייכים לנה\"ב ודוקא בהתלבשות בשכל הטבעי שגם השכל הטבעי יבין את הענין האלקי ואת הטוב דאלקות כו' והתעוררות יהי' דוקא בהתגלות הלב כו', והא בהא תלי' דכאשר ההתבוננות היא באופן הנ\"ל ממילא האהוי\"ר היא בהתגלות הלב כו', ואז בהתפעלות זאת גם הנה\"ב מתפעל באה' לאלקו' כו', וזהו תכלית הכוונה בעבודתו, ועי\"ז נותנים לו מלמע'\nגילוי שרש הנשמה כמו שהיא באצי' כו', שעז\"א מחצית השקל קודם שאומר עשרים גרה כו', דהנה הרמ\"ז ר\"פ כי תשא מבאר שם מא' הרע\"מ שיש ב' מדרי' מחצית השקל הא' סתמית מבלי נודע כמה הוא שקל שלם והב' שהוא עשר גרה כו', והמדרי' הא' היא הנשמה כמו שהיא במדרי' האצי' שלמע' מבחי' המספר כו', וזהו שנותנים לו מלמעלה כו' (וענין שהוא מחצית השקל היינו בחי' המוחין ומדות, וכמשנת\"ל בענין התחברות שרש הנשמה עם כחות הנפש שאז נעשים הכחות באופן נעלה ביותר כו' וזהו מדרי' האצי' שהן ע\"ס כו'). וזהו זה יתנו היינו חלק הגלוי והן הכחות דנה\"ב וגם הכחות דנה\"א המתלבשים בנה\"ב לבררו ולתקנו כו', דכשהוא מבקש אינו מבקש אלא לפי כחן כו' ועי\"ז נותנים מלמעלה מחצית השקל שלא נודע מספרו כו'. גם י\"ל זה יתנו ע\"ד זה אלי דקרי\"ס שהי' גילוי עצמות אוא\"ס למטה, ומחצית השקל שייך לקי\"ס כדאי' בירושלמי דכל העובר על הפקודים מאן דעבר על ימא כו', והוא יתרון האור הנעשה ע\"י בירור החשך כו', וזהו זה יתנו שיתנו חלק הגלוי והוא המחצית השקל שאומר אחר אומרו עשרים גרה כו', ועי\"ז נותנים מלמע' בחי' זה גילוי עצמות אוא\"ס דבנשמה הוא גילוי שרש ומקור הנשמה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכ\"ז באצי' דבד\"כ הוא בחי' כלים ובי\"ע בד\"כ בחי' לבושים, אך ברי' הוא לבוש המח' שמגלה את אור השכל ה\"ז בדוגמת בחי' פנימיות הכלים, וזהו שיש יתרון מעלה במח' על ענין התלבשות הפרצופים שהמתגלה הוא המלביש, מפני שמח' היא בדוגמת בחי' פנימיות הכלים, ולבושים דיצי' הוא כדוגמת בחי' חיצוניות הכלים, וי\"ל לבושי ברי' ויצי' הו\"ע אותיות ושערות, חי וצומח, ולבושי העשי' הן כמו שערות שמעור הבהמה, וכמו אותיות דלשונות</span>"],[3601331090,"<b>שלבד</b> לה\"ק, וכמו חידה ואותיות דחלומות, וזהו ש' דעשי' אל אד' בגימ' צו, עוע\"ז בטהרה, ומ\"מ מה יפו פעמיך בנעלים, דירידת הנשמה הוא לברר הנה\"ב ומזה דוקא יתרון אור. ובזה יובן מ\"ש זה יתנו מחצית השקל עשרים גרה השקל והן עשר כחות דנה\"א ודנה\"ב, ובנשמה עשר דאצי' ועשר דברי', וזה יתנו מחצית השקל בירור דנה\"ב שזהו ע\"י הנשמה בבחי' עשר כוחות דברי'."],[3601331091,"<h3>בס\"ד. ש\"פ תרומה, העת\"ר</h3>\n<b>וידבר</b> ה' אל משה לאמר דבר אל בנ\"י ויקחו לי תרומה מאת כל אשר ידבנו לבו תקחו את תרומתי, וצ\"ל מהו הב' תרומות ויקחו לי תרומה ומאת כו' תקחו את תרומתי, ואח\"כ או' וזאת התרומה הרי או' ג' תרומות וצ\"ל מהו ענינם. גם צ\"ל מהו\"ע מאת כל איש אשר ידבנו לבו תקחו את תרומתי, הלא תרומה זו היא תרומת מחצית השקל שזה הי' חיוב על כאו\"א וא\"כ מהו אשר ידבנו לבו מה שייכות בזה נדבת לב, דמ\"ש אח\"כ וזאת התרומה זה הי' נדבת המשכן אבל ב' תרומות הקודמים היו בחיוב כו'. ולמה או' קודם ויקחו ל' נסתר ואח\"כ או' תקחו ל' נוכח. ובמד\"ר אי' הה\"ד כי לקח טוב נתתי לכם כו', ויש לך מקח שמי שמכרה נמכר עמה א\"ל הקב\"ה לישראל מכרתי לכם את תורתי כבי' נמכרתי עמה שנא' ויקחו לי תרומה, ופי' המת\"כ לי הוא כמו אותי, וצ\"ל מה שייך תורה לתרומה ושע\"י התורה אותי אתם לוקחים דלכן או' ויקחו לי כו'. ולהבין כ\"ז ילה\"ק משנת\"ל שיש ד' מדרי' אורות וכלים לבושים והיכלות אורות וכלים הוא שהכלי מקבלת את האור ומתאחד עם האור, וע\"כ היא עושה ציור ותמונה בהאור ומגלה את\nהאור כו', לבושים המה נפרדים כמו אותי' המח' והדבור שהן נפרדים מן האור וממילא מעלימי' על האור כו', ובד\"כ כלים הוא באצי' להיות דאצי' הוא בחי' אחדות וע\"כ שם הוא בחי' כלים כו', ובי\"ע דומשם יפרד הן בחי' לבושים כו'. אמנם נת' שיש בחי' לבושים גם באצי' והן חיצוני' הכלים, דמה שהכלי מתאחדת עם האור היינו פנימי' הכלי שזהו עצמות הכלי מה שהיא כלי לקבלה ופנימי' הכלי היא אשר עושה תואר בהאור ומתאר ומגלה אותו, אבל חיצוניות הכלי ענינה אינה לא לקבל את האור ולא לתאר את האור רק לפעול בכח האור שזהו חוץ לעצם כו', ה\"ז בחי' לבוש דהיינו שהאור מתלבש ומתעלם בזה לפעול דבר שאינו מערכו ומהותו כו', ולכן השתל' הספי' זמ\"ז וכן התלבשות הפרצופים זב\"ז הוא על ידי חיצוניות הכלי כו', ובד\"כ הוא בחי' כלי רק שבפרטיות ה\"ז כמו בחי' לבוש כו', ובי\"ע בכללות הן בחי' לבושים רק בפרטיות כמו פנימיות הכלי וחיצוניות הכלי באצי', כמו\"כ הוא לבושי הברי' ויצי' דלבושי הברי' הן בדוגמת פנימי' הכלי שמתאחד עם האור וכמו אותיות דמחשבת שכל שא\"א להחליפם כו', רק אותי' דדבור שבמח' יכולים להחליף אבל מח' שבמח' הגם שהוא לבוש"],[3601331092,"מ\"מ אינו יכולים להחליפם כו', וכמו\"כ בחי' לבושי הברי' מתייחדים עם האור ומאיר שם גילוי האור דבחי' האין האלקי מאיר בגילוי בברי' כו', ויצי' הם כמו לבוש הדבור שמעלים על האור כו', ומ\"מ ג\"ז הוא גילוי, אבל היכלות הן לבושי עשי' שהן מסכים ופרסאות המעלימים על האור לגמרי כו'.\n<b>והנה</b> ענין המסכים והפרסאות יש בכל העולמות גם בעולם אצי' ובעולמות שלמעלה מאצי' כו', דכשם שאורות וכלים ישנם בכל העולמות ופי' אורות היינו או\"פ, הרי בכל העולמות יש בחי' או\"פ, דהגם שבד\"כ מה שלמעלה מאצי' הוא בחי' מקיף מ\"מ הרי יש בזה או\"פ כו', וכמ\"ש בע\"ח דגם בבחי' א\"ק יש עיגולים ויושר ובכל א' יש בחי' או\"מ ואו\"פ כו', רק שבכללות המדרי' העליונה היא בבחי' מקיף כו', וכמו\"כ בחי' הכלים ישנם בכל העולמות וכמ\"ש במבו\"ש שהתחלת התהוות הכלים הוא בא\"ק דאל\"כ במה הוא חלוק מאוא\"ס כו', כמו\"כ בחי' מסכים ופרסאות ישנם בכל העולמות כו', כי זהו אחת מעניני התיקון שיהי' המשכת האור דרך מסך ופרסא דוקא. וכמ\"ש בעה\"מ שע\"ח פ\"ב דמ\"ה ע\"ג וז\"ל החוט הזה של א\"ס כו' נתפשט החוט בתוך א\"ק ונעשה פרסא פי' פרוכת שהוא מסך בין א\"ק סתימאה לבין א\"ק סתם כו' (והיינו בין עולם המלביש ובין א\"ק), כדי שלא יצא יותר מדאי ויהי' ח\"ו העולם חרב כמו שהי' בעולם התהו, והמסך הזה מעכב השפע שלא יצא חוצה יותר ממה שיכולים לסבול העולמות, וכן יש בין כל\nעולם ועולם מסך מבדיל בסוד והבדילה הפרוכת לכם בין קדש ובין קדה\"ק כו' עכ\"ל, הרי גם במדרי' העליונות ביותר דהיינו בין המלביש ובין א\"ק יש פרסא כו'. ומדבריו מבואר שבעולם התהו לא הי' פרסאות והי' האור מאיר בגילוי ביותר וזה הי' סבת השבירה כו', ובאד\"ר בתחלתו דקכ\"ח ע\"א אי' ופריס קמי' חד פריסו ובה גליף ושיעור מלכין כו', וזהו פרסא דא\"ק, דאחר הצמצום דא\"ק שהעלה אור חצי הפרצוף התחתון למעלה פריס פרסא ובה גליף כו', משמע דגם בתהו הי' פרסא כו', ועמ\"ש מזה בע\"ח שער הנקודים פ\"ב ובביאור האד\"ר בס' קול ברמה, אמנם בס' רוח דוד בפי' הא' כ' דע\"י הפרסא הנה מדחיקות האור שלמעלה מהפרסא יצא האור דרך העינים (שלא ע\"י הפרסא) והם האורות דתהו כו', והוא מהר' צמח שם וכ\"ה בע\"ח שם, נמצא דהאור דתהו הי' שלא ע\"י הפרסא רק שזהו ע\"י סבת הפרסא כו', ונת\"ל (ד\"ה וירא בלק) דחומר העין הוא ג\"כ כמו הפסק לגבי אור הראי' ומ\"מ נמשך בזה העצמי כו', אך מ\"ש באד\"ר ובה גליף ושיער מלכין משמע דהמשכת האור הוא ע\"י הפרסא, צ\"ל כמ\"ש בע\"ח שם פבו\"ג ובמבו\"ש ש\"ב\nח\"א פבו\"ג דו\"ה שיש ב' מדרי' בתהו ועיקר אורות דתהו הוא מהעינים דא\"ק שלא ע\"י הפרסא והאור הנמשך ע\"י הפרסא הוא ש' מ\"ה החדש כו', ומ\"מ נמשך אור זה בנקודים ג\"כ כו' יעו\"ש. ועיקר ענין הפרסאות הן בבחי' התיקון כו', דבתהו עיקר האור הוא שלא ע\"י הפרסא ובתיקון עיקר האור הוא ע\"י הפרסא דוקא כו', וכמ\"ש בזהר נח דס\"ה רע\"א ובמק\"מ שם שביאר שם פרסא דא\"ק ופרסא תוך רדל\"א ופרסא בח\"ס כו', וכללות ענין הפרסאות הוא שיהי' האור באופן אחר מכמו שהי' קודם כו', וזהו דבתהו שנמשך האור שלא ע\"י פרסא הרי הי' האור כמו שהוא במקורו, וכנודע דספי' דתהו הוא שהאורות דעקודים כמו שהן במקורם יצאו ונתגלו כו', וזהו שהספי' דתהו היו בבחי' כתרים"],[3601331093,"שהכתר הוא העצמי של הספי' כו', והיינו דבחי' עצמיות האורות כמו שהן בעקודים יצאו ונתגלו כו', והגם דבהתגלותם נעשו בבחי' תוקף המציאות דבהיותם בעקודים היו בתכלית הביטול ובבחי' אין ממש ובהתגלות שלהם נעשו בבחי' יש ומציאות כו' דכל התגלות דבר גורם מציאות הדבר כו', ובפרט שנתגלה העצמי נעשה בתוקף המציאות כו', מ\"מ ה\"ה ממש אותן האורות דעקודים (בבחי' חיצוניותם כו') וכמשנת\"ל (ד\"ה אנכי ה' אלקיך), ובבחי' התיקון הוא שנמשכו האורות דרך פרסאות שזהו בחי' התעלמות האור שמתגלה דרך הפרסא לא כמו שהוא במקורו כו'. וגם ש' מ\"ה החדש בא דרך בקיעת הפרסא דא\"ק כנ\"ל וכמו שנת\"ל (ד\"ה וידבר כו' את קרבני לחמי), דהמשכת ש' מ\"ה בעולמות הוא דרך בקיעה דוקא שבזה מתעלם האור כו', ועם היות שהעצם הוא הבוקע (והוא בחי' ש' ע\"ב דא\"ק) דגם כמו שבא דרך בקיעה ה\"ה עצמי כו', מ\"מ ה\"ה מתעלם בבקיעה זאת שאינו בא בגילוי כמו שהוא במקורו שעי\"ז יכולים לקבל את האור שנמשך בכל עולם לפ\"ע העולם כו' וכמשנת\"ל באורך. וכן הוא בהאורות דתיקון שנמשכים דרך פרסאות דוקא\nכו', דכשם שהפרסא שבין אצי' לבי\"ע ה\"ה מעלמת על אור האצי' שהאור שנמשך בבי\"ע הוא באין ערוך לגבי אור האצי' (וגם בחי' נר\"ן דבי\"ע שזהו מבחי' הכלים דמל' והארת הקו שבהם והוא בחי' האצי' שבבי\"ע כו' הרי רחוק ערכו מבחי' אצי' ממש כו', וכמ\"ש במ\"א שיש הפרש גדול ביניהם, דמדרי' שבאצי' הרי מסתלקים בשעת החטא כמ\"ש בסש\"ב, ואצי' שבבי\"ע אינם מסתלקים כו', הגם שאינו שייך בהם ח\"ו חטא ועון והיינו שאינו נסרך בהחטא כמו מדרי' דבי\"ע ששייך בהם ענין סרכות הריאה כו', משא\"כ במדרי' האצי' כו', מ\"מ אינם מסתלקים כו', ולעיל (ד\"ה וידבר כו' וארא) נת' ההפרש בעבודה בין פנימי' המוחין וכוונה פנימי' שבמוח שזהו הפרש גדול כו'), כמו\"כ באצי' ולמעלה מאצי' דהמשכת האור שע\"י הפרסא הוא שבא האור באופן אחר כו'.\n<b>ולהבין</b> זה בפרטי מדרי' פרסאות דאצי', הנה נודע שיש פרסא בין הבינה לז\"א שעז\"נ ועל ראשי החיות רקיע כעין הקרח הנורא, דחיוון עילאין הן בחי' המדות דז\"א ויש פרסא על ראשי החיות דקבלת האור הוא ע\"י הפרסא כו', ויש לבאר הענין ע\"פ הידוע דלידת המדות הוא מהמוחין והיינו לא שעצם התהוותן הוא מהמוחין שהרי המדות ישנם בלב תמיד רק ההתעוררות שלהם הוא ע\"י שמקבלים מן המוחין כו', דכאשר מבין בשכלו איך שאותו הדבר הוא טוב נתהווה מזה אצלו אהבה ותשוקה לאותה הדבר כו', והרי הטעם המחייב את האהבה ה\"ז שכלי והוא טעם וסברה מפני מה ירצה בזה ויכול להיות סברה אחרת שאינו צריך לרצות בזה, שכן הוא ענין השכל שבכל דבר יש סברות שונות (והו\"ע השכל בלי תערובות מדה ואהבה עצמית שיש שכל וסברה לכל צד כו'), ומתגברים הטעמים והסברות שצריך לרצות שעי\"ז מתעורר באהבה, והרי האהבה אינה שכלי והיא מהות מדה שהיא אה' והרגשת עצמו שהוא היפך ענין השכל (ולכן כאשר יש תערובות אה' עצמי בשכל לא יהי' השכל אמיתי וכמו השוחד שיעוור כו'), ובא מ\"מ מן השכל\nהרי שבא ממהות שכל למהות מדה שהוא מהות אחר כו'. והנה בפרטי' הרי המדה יש בה ג\"כ מוחין והוא הנק' בכן כידוע, והיינו שהשכל הוא בטעמים וסברות בטוב הדבר איך שהוא דבר טוב או אם צריך לרצות א\"ל, ותחלה צ\"ל השגת עצם הדבר שהרי א\"א להיות השגת טוב הדבר אם אינו משיג את עצם"],[3601331094,"הדבר וע\"כ צ\"ל תחלה השגת עצם הדבר ומבין איך שהדבר טוב כו', והבכן הוא איך שהדבר טוב לו וצריך לרצות בזה שמזה נעשה התעוררות האהבה כו', הרי הבכן שהוא הטעם של המדה ה\"ז מהות מדה שהוא הרגש עצמי איך שלו טוב הדבר כו', וידוע שהבכן בא מההתפעלות שכלי, כי כאשר משיג ומבין טוב הדבר ה\"ה מתפעל בשכלו על טוב הדבר, ומזה בא התפעלות הלב איך שהדבר טוב לו שזהו הבכן שעי\"ז הוא התעוררות האהבה כו'. וידוע ההפרש ביניהם דמה שמתפעל בשכלו (שזהו בחי' מדות שבשכל) הוא שמתפעל על טוב הדבר מצ\"ע, לא מה שלו טוב הדבר כ\"א מה שהדבר בעצמו טוב הוא, כי טבע האדם הוא להתפעל על דבר טוב כו', והבכן הוא מה שלו טוב הדבר כו', ונמצא דהתפעלות השכל על טוב הדבר ה\"ז במהות ומציאות השכל, והיינו שאין בזה הרגשת עצמו כ\"א התפעלות על טוב הדבר מצ\"ע, ומזה לא יהי' עדיין התעוררות האהבה רק שמזה בא התפעלות הבכן איך שהדבר טוב לו, אך התפעלות הבכן הוא במהות ומציאות המדות היינו בהרגש עצמו איך שלו הדבר טוב כו', הרי שנהפך ממש ממהות מוחין למהות מדות כו'. וכן הוא ג\"כ\nבעבודה שבלב שהשכל הוא ההתבוננות באיזה ענין אלקי בהשגת הענין שבזה בא הטוב והעילוי דאלקות בעצמו (דיא התבוננות טראגט ארויס א רייכקייט אין אלקות) ומתפעל בשכלו על הטוב והעילוי דאלקו' כו', ומזה בא הבכן איך שקרבת אלקי' לו טוב ומתעורר באהבה ותשוקה גדולה לאלקות כו', והרי ההתפעלות שכלי הוא בעצם הטוב דאלקו' והבכן הוא מה שלו טוב שאין זה מהות השכל כ\"א הוא מהות מדה בבחי' הרגש עצמי רק שזהו הטעם של המדה כו', הרי נעשה מהות שכל ונהפך למהות מדה כו' (ובד\"כ בחי' חב\"ד שבמדה הוא האהבה ועצם המדה הוא החסד כו', וברוחני' הוא כמ\"ש באגה\"ק סי' ט\"ו דמחמת אהבת ה' ומרוב חפצו לדבקה בו הוא חפץ חסד כו' היינו לעשות גמ\"ח בגופו ובנפשו כו', ואפשר בכלל זה הוא ג\"כ המשכת נפשו לעניני אלקות כמו בעסק התורה ומעהמ\"צ במ\"ע בפרט כו'), וזהו ההמשכה מן המוחין אל המדות שבאים במדות באופן אחר מכמו שהן במוחין כו' (וזהו בבחי' חיצוני' המוחין וכידוע דזה שהמדות באים ע\"י הבכן הוא בחיצוני' המוחין כו', ופנימי' המוחין הרי באים בלב כמו שהן במוחין כו',\nומ\"מ נת\"ל דכמו שנרגש בלב אין זה כמו שהוא בבחי' מוחין ממש וכמו ענין גחין ונשיק לעפרא שאין זה כמו שזלגו עיניו דמעות שזהו התפעלות המוח לבד משא\"כ גחין ונשיק לעפרא שזהו התפעלות הלב ה\"ז ניתק קצת מעצם המוח, דהתגלות התפעלות זאת מה שגחין ונשיק כו' אין זה שייך בהתפעלות המוח, וא\"כ ה\"ז ניתק מעצם המוחין ממש כו'). דכמו\"כ הוא למעלה בחי' יסוד אימא שמסתיים בחזה דז\"א דעד החזה הוא בחי' המוחין של המדה ומן החזה ולמטה הוא בחי' המדות כו', דהמוחין של המדה הוא שממהות מוחין נעשה מהות מדה כו' וכמ\"ש בתו\"א בהבי' דולכן אמור, וזהו ע\"י הפרסא שבין המוחין למדות שעי\"ז בא אור המוחין באופן אחר מכמו שהן במוחין ולהיות כמהות המדות כו', וי\"ל דהפרסא הו\"ע מיצר הגרון שזהו ההפסק בין המוחין למדות כו' כמש\"ש, והיינו שבזה מתעלם אור המוחין לבוא לפי אופן המדות כו', וכמ\"ש בתו\"א שם דמיצר הגרון הוא מקום צר דהמוחין מתעלמים שם שאינו מהות מוחין ולא מהות מדות ובזה מתהפך ממהות מוחין למהות מדות כו', ובעבודה הוא דלאחר"],[3601331095,"ההתבוננות והתפעלות שכלי אינו בא תיכף הרגש הבכן דקרבת אלקי' לי טוב, דמפני שהן מהותים נבדלים אינם באים זא\"ז תיכף דהיינו שמההתפעלות על עצם הטוב דאלקות תבוא ההתפעלות דהרגש עצמי איך שלו טוב כו', כ\"א שאחר ההתבוננות האמיתי כאשר מתפעל בשכלו כנ\"ל מתעלם האור לגמרי שאינו בבחי' השגה ולא בבחי' התפעלות, ובזה הוא משתנה והולך (ער גייט אריבער) ממהות למהות להיות הרגש הבכן כו'.\n<b>והנה</b> בתו\"א שם מבו' דמיצר הגרון הוא הממוצע המחבר כו', וי\"ל דכמו\"כ הוא ג\"כ בענין הפרסא שזהו כמו ממוצע, וכמ\"ש בזהר בראשית דל\"ב ע\"ב ע\"פ יהי רקיע אית קרומא במציעות מיעוי דב\"נ דאיהו פסיק מתתא לעילא ושאיב מעילא ויהיב לתתא כו', הרי דהפרסא היא כמו ממוצע דשאיב מעילא כו'. ולהבין ענין דשאיב מעילא ויהיב לתתא, הנה ענין הפרסא עם היותה לבוש המעלים לגמרי מ\"מ יש בה נקבים שע\"י יוצא דבר מה, וכמו עור האדם שמלא נקבים שדרך בם יוצא הזיעה וגם מעור הבהמה יוצאים שערות כמשנת\"ל, דכמו\"כ הוא הדוגמא בפרסא העליונה שיש בה נקבים והו\"ע הרשת שע\"ג מזבח עילאה הנז' בזהר, דבד\"כ זהו הפרסא שבין אצי' לבי\"ע ה\"ז נק' רשת שהוא מנוקב כנקבי הנפה כו' (והוא בבחי' המל' וכמו\"כ הוא בפרסאות שלמעלה מבחי' המל'), וכמו עד\"מ הנפה שמרקדין בה הקמח הרי עיקר ענינה הוא להפריד הפסולת מן הקמח, שקודם שמרקדין את הקמח הרי מעורב הכל בתכלית העירוב ואז הפסולת אינו גס כ\"כ וגם הטוב אינו טוב כ\"כ, וע\"י שמרקדין את הקמח בהנפה קולטת הנפה את הפסולת הגס\nודרך הנקבים יוצא הקמח הדק, וכאשר משימים הקמח עוד הפעם בהנפה ישאר עוד מהגס ע\"ג הנקבים שאינו גס כ\"כ כהקודם והיותר דק יוצא כו', וכן יהי' בירור הנפה כמה פעמים כו', וזה בנפה שלנו שקולטת הפסולת ומוציאה את הטוב, אבל בנפה הנזכרת במשנה פ\"ה דאבות הוא שקולטת הסולת ומוציאה את הקמח היינו שקולטת את הטוב ומוציאה את הפסולת כו', ובבירור הראשון מתברר הסולת היותר טוב והשאר יוצא הכל בפסולת שיש בזה הרבה קמח, ואח\"כ מתברר עוד ויוצא פסולת גס יותר עד שבבירור האחרון יוצא הפסולת היותר גס כו', וה\"ז ממש כמו נקבי עור האדם שמוציאים את הזיעה שהיא הפסולת המתברר מן החום הטבעי כו', דחום הטבעי יש בו פסולת כי טבע החום להוליד פסולת וכמו שהוא בהחום הטבעי ה\"ז בדקות ומ\"מ צריך להתברר מן החום והוא שיוצא מעט מעט עד אשר יוצא בהזיעה וזהו שהזיעה מבריא את הגוף מפני הסרת הפסולת, וכאשר מתגבר החום הטבעי נסתם נקבי הזיעה וכאשר מזיע ה\"ה מבריא כו', ומ\"מ הרי החום הטבעי אינו יוצא שבאם יוצא ח\"ו החום הטבעי א\"א לחיות כו', רק יוצא הפסולת לבד כו'.\n<b>וכמו\"כ</b> יובן בענין הרשת שע\"ג מזבח עילאה בחי' מל' דאצי' הנותנת טרף לבי\"ע כו', שזהו ע\"י הרשת המלא נקבים שבהם מתברר הפסולת מן הטוב כו', וכמ\"ש במאו\"א אות ר' סל\"ה רשת מחצי המל' ולמטה כי שם ק\"נ, והיינו שהרשת מוציאה הפסולת ממש כו'. והענין הוא דהנה השפעה האלקי' מהרפ\"ח ניצוצות ה\"ז מעורב טו\"ר משבה\"כ דתהו כו', דהרי האורות דתהו היו בבחי' ביטול ביותר (וכמשנת\"ל בענין בהמה בה מה) והכלים היו בבחי' יש ביותר, ונת\"ל שגם הביטול דאורות היו בבחי' ישות (לא בבחי' הנחת עצמותו כו'), וע\"כ הרפ\"ח ניצוצות מעורבים טו\"ר כו', וזה מתברר ע\"י הרשת שהיא הפרסא כו', שהטוב"],[3601331096,"נשאר למעלה מהפרסא והפסולת יוצאה למטה מהפרסא כו', וזהו סיבת מציאת הרע שבעולם שנא' ע\"ז ובורא רע, שהוא בריאה יש מאין כו', זהו שנתהווה מהפסולת הנבדלת כו', והגם שאין רע יורד מלמעלה זהו מלמעלה דוקא היינו מעל לרקיע ופרסא המבדלת דשם הכל טוב שנברר כו', אבל ממה שנבדל תחת הפרסא מזה מתהווה הרע כו', וה\"ז כמו נקבי הזיעה שמוציאים הפסולת שבחום הטבעי כו', כמו\"כ נקבי עור החשמל מוציאים הפסולת מגבורות העליונות שהן גבורות קדושות שנעשה חיות זה בבחי' גבורות קשות ממש כו'. ויובן זה ע\"ד משארז\"ל מזיעתן של חיות נה\"ד יוצא כו', דמהתלהבות חיות שבעולם היצי' נה\"ד יוצא דבהשתל' על ראש רשעים יחול בגיהנם כו', ועד\"מ המתפלל בהתלהבות גדולה ברשפי אש התשוקה לאלקות ה\"ה מתענג בעונג נפלא בתשוקה זו כו', ובאה מהתענוג שבההתבוננות דכאשר מתבונן בענין אלקי ומשיג אותו היטב ונקלט אצלו היטב הענין במוחו שמאיר אצלו הענין האלקי בגילוי ממש כו', ה\"ה מתענג מאד בהענין האלקי ומזה הוא שבא רשפי אש התשוקה לאלקות שיש בזה ג\"כ תענוג גדול כו', והגם שעונג\nהוא השבת הנפש והתשוקה היא בבחי' הסתלקות וכליון הנפש כו', מ\"מ התשוקה באה מהעונג שבההתבוננות ויש בה עונג כו', כי גם העונג כלול מחו\"ג ומבחי' גבורות שבעונג בא רשפי אש התשוקה כו', והיינו שגם בההתבוננות העונג הוא בהתלהבות או שזהו עונג דאו\"ח וע\"כ בא בבחי' רשפי אש כו', ונמצא עם היות שזהו עלי' והסתלקות החיות ה\"ז בא מעצם נקודת חיות הנפש שהוא העונג כו'. והנה כאשר נפסק ההתלהבות בזמן מה אחר התפלה יכול לבא לידי כעס ורוגז על עוברי רצונו כו', דכשרואה איזה דבר ה\"ה מתכעס כו', וזה בא מצד ההתלהבות כו', דבעת ההתלהבות הרי לא הי' שייך כלל לאיזה כעס מפני שהי' בבחי' ביטול עצמותו בהתכללות במקור חיים שהוא העונג האלקי כו', אך כשנפסקה ההתלהבות יבא לידי כעס שזהו מהחמימות וגבו' הקודמת כו', ואם הי' העבודה בבחי' חסדים שבגבורות לא הי' הכעס כלל (כ\"א הי' בבחי' צער בנפשו על הלא טוב כו' וכמ\"ש במ\"א), ומפני שהעבודה היא בבחי' גבורות מזה בא הכעס כו', ועם היות שזהו ג\"כ לשם שמים, ה\"ז מ\"מ בחי' גבו' קשות ויכול להיות מזה עונש בפו\"מ\nכו', ועד\"ז הוא מזיעתן של החיות דמהתלהבות הרשפי אש שלהם שזהו בתכלית הקדושה נברר מ\"מ מזה הפסולת שהן גבורות קשות והן מלאכי חבלה ומזיקים שמזיקים לנפש כו', ועד\"ז הוא הפסולת הנברר ע\"י הרשת שזהו פסולת ממש שנעשה רע כו'.\n<b>אמנם</b> יש בחי' רשת בקדושה וכמ\"ש בזהר\"ק בפי' מאה\"ז בראשית דנ\"א כ' ואמנם יש רשת בקדושה שע\"י אותם הנקבים נכנס האור ויוצא למי שראוי לקבל כו' (ושם שזהו בבעל תשובה שחותרים להם חתירה כו' יעו\"ש ד\"ל ע\"א). והענין דפסולת זאת אין זה פסולת ממש כ\"א מה שכל מדרי' תחתונה נק' פסולת לגבי המדרי' העליונה וכמו דא מוחא לדא ודא קלי' לדא כו', והמדרי' העליונה כוללת המדרי' התחתונה ואז הכל הוא כמו המדרי' העליונה, וכאשר המדרי' התחתונה מתגלית בפ\"ע אז ה\"ה כמו פסולת לגבי המדרי' העליונה כו', וז\"ע יהי רקיע ויהי מבדיל בין מים למים שזהו בין מ\"ע ומ\"ת כו', דקודם ההבדלה היו מעורבים יחד ולא הי' המ\"ע בבחי' העילוי כ\"כ והמ\"ת לא היו בבחי' ירידה כו', וע\"י ההבדלה הוא שהובדלו והופרשו זמ\"ז ונעשו המ\"ע בתכלית העילוי ומ\"ת נעשו בתכלית הירידה שנעשו"],[3601331097,"מקור לתענוגים גשמי' דמים מצמיחים כל מיני תענוג כו', והיינו ע\"י הרקיע המבדיל ביניהם שנתברר בחי' המ\"ת שהיו כלולים במ\"ע ונבדלו ונפרשו בפ\"ע כו'. וכמו\"כ הוא למעלה וכידוע דמ\"ע הוא בחי' ח\"ע ומ\"ת בחי' ח\"ת כו' (ובד\"כ זהו בחי' חכ' דתורה וחכ' דמע\"ב כו'), דעד שלא נבה\"ע הי' מים במים שהיו כלולים ומעורבים זב\"ז כו' ואז הי' ח\"ת במדרי' ח\"ע כו', וכמשנת\"ל (ד\"ה ויגש אליו) בענין בחי' מל' שבכל ספי' שזהו בחי' כח הגילוי כו', דכללות ענין המל' הוא בחי' הגילוי ובחי' המציאות כו', אך כמו שכלולה בספי' העליונות ובפרט בבחי' החכ' אינה בבחי' גילוי ולא בבחי' המציאות כו', דבהיותה בבחי' החכ' ה\"ה במדרי' החכ' כו', וכמשנת\"ל (ד\"ה זה יתנו) דש' ע\"ב הכל במילוי יו\"ד גם ה\"י אחרונה דהיינו שהכל הוא במדרי' החכ' כו', וכאשר נבדלה במדרי' בפ\"ע אז ה\"ה בבחי' הגילוי ובבחי' המציאות כמהות מדרי' המל' כו', וההבדלה היא ע\"י הרקיע שנבדלה בחי' ח\"ת מבחי' ח\"ע, ויצא ונתגלה במדרי' בפ\"ע כו'. וזהו כדין קרומא דפסיק במעוי דב\"נ שהוא חצר הכבד שמפסיק בין אברי\nהנשימה לאברי המזון, דאברי הנשימה הם בתכלית העילוי ואברי המזון בתכלית ההגשמה שזהו ע\"י חצר הכבד דוקא שיש בו טבע הזאת לברר את הכח הגשמי הכלול בהרוחני שבהיותו כלול שם ה\"ה ג\"כ כח רוחני עדיין וחצר הכבד הוא מבררו ומבדילו ומגשמו להיות כח גשמי כו', וכמ\"ש באמ\"ב (ושם שזהו לפי שכלול מרוחני וגשמי כו'), וכמו\"כ הרקיע מבדיל בחי' ח\"ת מבחי' ח\"ע כו', וזהו דשאיב מלעילא ויהיב לתתא דהיינו שהפרסא שואבת בחי' השפע התחתון הכלול בהעליון שבא בהתגלות במדרי' התחתונה כו', דבהיותה כלול במדרי' העליונה ה\"ה כמהות המדרי' העליונה וכאשר יוצאת בפ\"ע ה\"ה נעשית במהות המדרי' התחתונה כו'. והנה החצר הכבד זהו הבדלה גשמיות כו', ויש ג\"כ הבדלה רוחני' בהקרומות שבמוח שמבדילין בין שכל לשכל וכמו שכל הנוטה כלפי חסד ושכל הנוטה כלפי גבו', דמתחלה הוא שכל וסברה אחת שלא הי' בה התחלקות סברות שונות ואח\"כ נחלק כו', והיינו כמשנת\"ל (בתחלת הדרוש) דשכל וסברת הרב אחת היא ובהמקבלים באה הסברה בבחי' התחלקות וכמו שמאי והלל שקבלו מרב א' כו', וכמו\"כ הוא בכל\nא' שתחלת הסברה בנקודתה אחת היא ויכולים להטותה לזכות ולחוב (וכמו שמצינו שטעם א' יחייב לחוב וגם לזכות וכמו כי יצר מחשבות לבו כו'), ואח\"כ בא בהתחלקות להיות סברה זו לזכות דוקא או לחוב דוקא או שיהי' בה ב' סברות לזכות ולחוב כו', דהסברה בתחלה כוללת חו\"ג רק שזהו בתכלית ההתכללות ואח\"כ מתחלק ונבדל לב' הטיות כו', והבדלה זו זהו ע\"י הקרומות שבמוח שהקרום הוא המפסיק ומחלק את השכל הכללי ועושהו לחצאין שמבדילו לב' חלקי חו\"ג, דעיקר כח ההבדלה הוא בהקרום דבשרשם ומקורם היו לאחדים ממש באמת, והקרום הזה הוא שמבדילם לעשותם ב' הפכים כו'. וכשם שהוא בהבדלת שכל א' לב' שכלי' בהטיות שונות כו', כמו\"כ הוא בהבדלת השכלי' והחכמו' בכלל וכמו שיש חכ' עליונה שהיא דקה ועמוקה ביותר ויש חכ' שאינה דקה כ\"כ כו', וכמו שכל המעשי עם היות שיש בזה כמה שכלי' וחכמות ה\"ז מ\"מ שכל פשוט לגבי שכל השייך אל המדות וכ\"ש לגבי שכלי ממש כו', וכן בהשבע חכמות שהן בדרגות זו למעלה מזו כו', וכל החכמות לגבי חכמת אלקי' וחכמת התורה כו', והלא המוח הוא כלי לאור השכל שכולל כל החכמות ושכלי'"],[3601331098,"כו', אך השכלי' הפשוטים והתחתונים הם כמו פסולת לגבי השכליי' הדקים כו', ובהיותם כלולים יחד בכח השכל שבמוח ה\"ה מעורבים יחד ואז אינם בבחי' הגשמה כ\"כ כו', וההבדלה היא שנעשה ע\"י הקרומות שבמוח שמבדילים את השכלי' התחתונים מן העליונים ובאים בהגשמה עי\"ז כו'. ומשל גשמי הוא כמו הזלת הליחה מהחוטם שזהו הרקת הפסולת מהלחלוחית שבמוח, ושם במוח הוא בתכלית הדקות (דהלחלוחית היא רוחני) ואינו שייך שם כלל ליחה סרוחה ועכורה כ\"א פסולת דקה ביותר, ומ\"מ צריכים להפרידה והוא ע\"י הקרומות שמפרידין מעט מעט עד שנעשה בחוטם ליחה סרוחה ועכורה שהוא פסולת ממש כו', וכמו\"כ הוא בהקרומות שבמוח המפרידין את השכלי' דבכח השכל שבמוח כלולים כל השכלי' והן בבחי' הרוחני' כו', ונבדלים ע\"י הקרומים ונעשים שכלים פשוטים כו'.\n<b>והדוגמא</b> מזה יובן למעלה דהנה לכאו' אינו מובן מפני מה מייחסים את התורה לבחי' ח\"ע יותר מכל הנמצאים שבעולם שהכל הוא מבחי' ח\"ע וכמ\"ש כולם בחכ' עשית כו', ויש בהם חכ' עמוקה וכמש\"א אשר יצר את האדם בחכמה והיא חכמת הניתוח כו', וכן כל השבע חכמות שיש בהם חכמות עמוקות כו', מהו מעלת התורה כ\"כ שעלי' אמר שלמה אמרתי אחכימה והיא רחוקה ממני, שכל החכמות השיג בחכמתו ועל חכמת התורה ובפרט פרה אדומה וכה\"ג אומר אמרתי כו' והיא רחוקה כו', וכתי' לא ידע אנוש ערכה אלקים הבין דרכה כו', ובמד\"ת אי' שאלמלי ניתנו פרשיותי' של תורה על הסדר הי' האדם יכול להחיות את המתים ולעשות מופתים כו', וזהו מפני שהתורה היא רצונו וחכמתו ית', והלא כל הדברים המה מרצונו וחכמתו ית' כו'. גם צ\"ל בעיקר ענין התורה שהיא להבדיל בין טמא לטהור ומותר ואסור כו', דקודם מ\"ת הי' הכל מותר וכמ\"ש כירק עשב נתתי לכם את כל, וע\"פ התורה יש בהמות טהורות ובהמות טמאות כו', והלא בגשמי' אין הפרש בין הטהורה להטמאה, ולכאו' גם בכח האלקי המהווה ומחי' אין גרעון\nבכח המהווה את הבהמה טמאה לגבי הכח המהווה בהמה טהורה כו', ושרש כולם הוא מבחי' החכ' דכולם בחכ' עשית כו' ומפני מה התורה מבדלת ביניהם כו'. אך כללות הענין הוא שזהו ההבדלה דיהי רקיע ויהי מבדיל בין מים למים דהיינו בין ח\"ע וח\"ת שזהו בשרשו ההבדלה בין חכ' דתורה וחכ' דמע\"ב, דחכ' דמע\"ב היא בבחי' פסולת לגבי חכ' דתורה ונק' מלין דהדיוטא וכמא' לאו אורחא דמלכא לאשתעי במלין דהדיוטא כו', דעם היות שזה מדרי' גבוה מאד ה\"ז בבחי' מלין דהדיוטא ובחי' פסולת לגבי חכ' דתורה כו', ומחכ' דמע\"ב הוא שנשתלשלו כל החכמות וממילא ה\"ה פסולת לגבי חכ' דתורה כו', ולכן על התורה דוקא אומר אמרתי אחכימה והיא רחוקה כו' ולא ידע אנוש ערכה כו' מפני שהיא עצמי' החכ', משא\"כ כל החכמות ששרשן מחכ' דמע\"ב ה\"ה פסולת לגבי תורה כו', ועם היות דחכ' דתורה וחכ' דמע\"ב שניהם בבחי' החכ', הנה חכ' דתורה היא עצמיות דחכ' וחכ' דמע\"ב בחי' הפסולת דחכ' כו'. ובזה יובן משארז\"ל בסנהדרין ע\"פ אדם לעמל יולד איני יודע אם לעמל תורה או לעמל שיחה כו', עמל שיחה הן העש\"מ\nכו', ואומרו איני יודע כו' זהו קודם ההבדלה דשניהם בבחי' החכ' כו', אבל כאשר נבדלו הרי חכמת התורה נשארה בבחי' העצמיות דח\"ע וחכ' דמע\"ב בחי' הפסולת דחכ' כו', והאדם דוקא לעמל תורה יולד כו', ומה שתורה מבדלת בין מותר ואסור זהו ההבדלה בחכ' דמע\"ב גופא, דהנה"],[3601331099,"יש ב' הבדלות יהי רקיע ויהי מבדיל כו' ואח\"כ ויעש ה' את הרקיע ויבדל כו', והבדלה הראשונה היא ההבדלה שבין ח\"ע וח\"ת חכ' דתורה וחכ' דמע\"ב כו', והבדלה שני' היא הבדלת הפרסא האחרונה המוציאה ומבדלת את הפסולת ממש, והיא הרשת שע\"ג מזבח עילאה כו' כנ\"ל, וכל הדברים המותרים שרש ההתהוות והחיות שלהם הוא מלמעלה מהפרסא, וכל הדברים האסורים שרש התהוותם הוא מהפסולת שלמטה מן הפרסא שנעשה רע ממש כו', וזהו הפסולת הגס דבחי' חכ' דמע\"ב כו', ומ\"מ הפסולת הוא בבחי' חיות להם כו', והתורה מבדלת ביניהם שזה מותר וזה אסור, והיינו שזה יכול להתברר ולהיות כלי לגילוי אלקות וזה אינו יכול להיות כלי לאלקות מפני שהיא פסולת הגסה שצריכים לדחותה לגמרי כו'. ובזה יובן מה שא' במד\"ר האור זה מעשה הצדיקים וחשך מעשה הרשעים ואיני יודע באיזה מהן חפץ כשהוא אומר וירא כו' הוי שחפץ במעשה הצדיקים דוקא, וזה תמוה איך או' וא\"י כו', אך הענין הוא דזהו קודם ההבדלה, אבל כאשר נבדל ונפרש בבחי' פסולת הגס ה\"ה חפץ במעהמ\"צ דבחי' חפץ ורצון בבחי' גילוי אלקות הוא\nבמעשה הצדיקים דוקא, אבל מעשה הרשעים אינו חפץ בהם ואדרבה הן נגד רצונו ית' כו'. והנה ידוע דנובלות חכ' שלמע' תורה, שגם התורה היא בחי' נובלות לגבי חכ' עליונה יותר, דהנה אורייתא מחכ' נפקת והיא בחי' חכ' דאצי' וה\"ה בחי' נובלות לגבי בחי' ח\"ס כו', ויש הבדלה ביניהם והוא בחי' קרומא דחפי' על מו\"ס ומבדיל בין ח\"ס וח\"ע כו'. והענין הוא דהנה מצינו הפרש בין תורה ומצות דתורה היא להבדיל בין הטמא ובין הטהור, ומצות מבדילים בדברים המותרים גופא מה שראוי למצוה ומה שאינו ראוי כו', וכמו ד' מינים שבלולב שנבחרו מינים אלו דוקא למצוה ולא שארי צמחים והוא מפני האחדות שבהם כו', שהרי המחלוקת שנאוי מאד למעלה והד' מינים יש בהם אחדות כנודע, ע\"כ נבחרו אלו דוקא למצוה כו', וכן ציצית בצמר דוקא, וכמו תרומה ומעשר שמה שמפרישין ומבדילין נעשה קדש והשאר חולין כו', דקודם הבדלה הי' הכל בשוה ואח\"כ נבדלו כו', והיינו שהמצות מבדילים שבזה יכול להיות גילוי רצה\"ע דמצות, ובזה עם היותו דבר המותר אינו יכול להיות בזה גילוי רצה\"ע כו'. והבדלה זו\nהיא מבחי' ח\"ס כו' שהרי בחכ' אתברירו דכל סדר באיזה דבר שזה יהי' כך וזה כך הוא מבחי' חכ' כו', והסדר בהרצון במה ישרה הרצון ובמה לא ישרה זהו מבחי' ח\"ס כו', וכמ\"ש מזה במ\"א בד\"ה ויחי יעקב וביאורו, והיינו להיות דח\"ס היא מדרי' עליונה יותר ה\"ה מבדלת שהשראת אלקות יכול להיות דוקא בזה גם בדברים המותרים כו'. ובתורה זהו ההפרש בין גליא וסתום דתורה, דתורה בכלל היא בחי' חכ' וסתום דתורה היא בחי' ח\"ס כנודע, וזהו הטעם שבזהר ובס' קבלה מחמירים בהרבה ענינים על הגלי' דתורה מפני שהגילוי דסתום דתורה יכול להיות דוקא באופן כזה, דעם היות שהדבר מותר ע\"פ גלי' דתורה מ\"מ אין זה כלי לבחי' הסתום דתורה וצ\"ל חומרא יתירה בכדי להיות כלי לבחי' סתום ופנימי' התורה כו'. ומכ\"ז יובן ענין דשאיב מעילא ויהיב לתתא דבתחלה הי' בבחי' התכללות וכמו ח\"ע וח\"ת שהי' כלולים זב\"ז והי' הכל במדרי' החכ' כו', ואח\"כ נבדלו ע\"י הרקיע המבדיל ואז החכ' דתורה נעשית בעצמית מדריגתה בחי' העצמיות דח\"ע, וח\"ת נבדלה במדרי' בפ\"ע ואז היא במדרי' ומהות בחי' ח\"ת כו'."],[3601331100,"<b>וע\"פ</b> הנ\"ל יובן מ\"ש ויקחו לי תרומה כו', דהנה תרומה הוא ל' הפרשה והבדלה וגם ל' רוממו' כו', והוא להיות שבהבדלה דתרומה הוא שהדבר הנבדל נעשה קדש, ה\"ז הבדלה בבחי' רוממות כו', וזהו ג\"כ מפני שנבדל מזה המדרי' התחתונה שהיא בחי' פסולת לגבה כו' והכל ענין א'. וזהו שאמרו במד\"ר ע\"ז כי לקח טוב כו' שהיא התורה דתרומה היא תורה מ' כידוע, והיינו שנבדלה ונפרשה התורה להיות בבחי' העצמיות דח\"ע כו', ומש\"א כבי' נמכרתי עמה הוא האוא\"ס שבתורה כו', וכידוע דבחכ' שורה אוא\"ס כו', וזהו שהתורה לפי שהיא עצמות החכ' ע\"כ יש בה השראת אוא\"ס כו', וזהו יש לך מקח בעולם שמי שמכרה כו' והיינו שבבחי' חכ' דמע\"ב לא יש בזה השראת אוא\"ס רק בחכ' דתורה להיותה עצמו' החכ' יש בה השראת אוא\"ס כו'. והנה התורה היא שנבררה למעלה והיא בבחי' המשכה מלמעלמ\"ט כו', והגילוי הוא לנה\"א כו', אך צ\"ל העבודה לברר ולזכך הנה\"ב כו', וע\"ד כמו יום א' של פסח שהי' בו יצי\"מ הגילוי הוא לנה\"א, ואח\"כ צ\"ל ספה\"ע וספרתם לכם ממחרת השבת שזהו בירור הנה\"ב כו', וכמו\"כ\nכאן הרי צ\"ל בירור וזיכוך הנה\"ב שהוא מק\"נ שזהו ע\"י ההבדלה דפרסא האחרונה דויעש אלקי' הרקיע כו', וצ\"ל הבירור שיהי' גם הוא כלי לאלקות כו'. ועז\"א מאת כל איש כו' תקחו תרומתי והיא התרומה השני' בהבדלה האחרונה שג\"ז יתהפך לאלקות כו', וזהו מאת כל איש דאיש מורה על הגבורה כאיש גבורתו כו', וכמארז\"ל ע\"פ אשרי האיש ירא כו' אשרי מי שהוא מתגבר על יצרו כגבורת האיש, והיינו לעמוד נגד כל מונע ומעכב שבזה נשבר חומרי' וגסות הנה\"ב כו', דכל מניעה ועיכוב הוא מהנה\"ב וע\"י שעומד נגד כל מונע נשבר חומריותו כו', וגם להתגבר עליו להכניעו ולפעול בו הביטול כו'. ובאו\"ת פי' מאת כל איש שכולו איש והיינו שלמטה מהפרסא יהי' כמו למעלה מהפרסא, והענין הוא דהנה כמו שאברי הנשימה הם בבחי' הדקות והרוחניות ואברי המזון הן בהגשמה כמו\"כ הוא בהאדם ברוחני' דבשעת התפלה הוא מקורב לאלקות ואינו שייך לחומריות כלל, ואחר התפלה כשהולך בעניני העולם ה\"ה נמשך אחר חומריות העולם להתאוות תאוה כו', ואז אינו איש ונק' אשה כי נשים דעתן קלות כו', וגם שהוא בבחי'\nמקבל מהתענוגים הגשמי' כו' והוא מרוחק מאלקו' כו', וענין שכולו איש הוא שיהי' אחר התפלה כמו בעת התפלה והיינו שכל היום לא יהי' נמשך אחרי חומרי' העולם כו', ובהיותו בעולם יהי' מקורב לאלקות והו\"ע בכל דרכיך דעהו כו', ובד\"כ הו\"ע הכפי' שכופה את הנה\"ב ופועל בו הביטול שלא ירצה בעניני העולם וירצה באלקות כו', ואומרו אשר ידבנו לבו הענין הוא דכשם שיש הפרש בין למעלה מהפרסא ולמטה מהפרסא כמו\"כ הוא בלב ההפרש בין חלל הימני וחלל השמאלי, דחה\"ש מלא דם ששם משכן הנה\"ב כו', וזהו אשר ידבנו לבו שהנה\"ב שבחה\"ש יתאחד עם הנה\"א שבחה\"י ויהי' בביטול באלקות כו'. וזהו שתחלה או' ויקחו ל' נסתר לפי שזהו בבחי' המשכה מלמעלה ויש בזה השראת אוא\"ס כו', והוא הגילוי מלמעלה להנה\"א כו', ואח\"כ תקחו ל' נוכח שזהו עבודת האדם בכח עצמו בבירור ותיקון הנה\"ב כו'. והנה ע\"י הבירור דנה\"ב נעשה יתרון אור כו', וזהו וזאת התרומה כו', דהנה ג' תרומות הן בחי' ח\"ת וח\"ע וח\"ס כו', וזהו וזאת התרומה היינו גילוי בחי' ח\"ס בחי' סתום דתורה כו', שזהו היתרון אור שנעשה ע\"י בירור הנה\"ב כו', וזהו וידבר ה' כו' ויקחו לי תרומה זהו ההבדלה"],[3601331101,"בבחי' ח\"ע שנבדלה התורה שהיא בחי' עצמות ועי\"ז אותי אתם לוקחים בחי' אוא\"ס שבתורה כו', ואח\"כ מאת כל איש אשר ידבנו לבו תקחו תרומתי בהבדלת הפסולת דבחי' ח\"ת לברר ולזכך את הנה\"ב כו', ועי\"ז נעשה יתרון אור וזהו וזאת התרומה אשר תקחו גילוי בחי' ח\"ס שזהו התגלות פנימי' התורה כו'."],[3601331102,"<h3>בס\"ד. ש\"פ תצוה, העת\"ר</h3>\n<b>ואתה</b> תצוה את בני ישראל ויקחו אליך שמן זית זך כו' להעלות נר תמיד, מחוץ לפרוכת כו' יערוך אותו אהרן ובניו מערב עד בקר כו', וצ\"ל מהו ואתה תצוה הול\"ל צו את בנ\"י כו' מהו אתה תצוה, ועוד וא\"ו נוסף ואתה תצוה כו'. גם מהו ויקחו אליך הלא מצות העלאת הנרות הוא באהרן כמ\"ש יערוך אותו אהרן וא\"כ מהו ויקחו אליך. גם צ\"ל מ\"ש מחוץ לפרוכת יערוך אותו כו' למה זה להודיע כאן, והלא מקום המנורה כבר נא' בפ' תרומה, וכאן הציווי על השמן ולמה להודיע כאן מחוץ לפרוכת יערוך אותו כו'. גם למה בפסוק ראשון גבי ויקחו אליך נא' להעלות נר תמיד, ובפסוק הב' כתי' מערב עד בקר. ולהבין כ\"ז ילה\"ק משנת\"ל בענין יהי רקיע ויהי מבדיל דאי' בזהר ע\"ז קרומא אית במעוי דב\"נ דפסיק מתתא לעילא ושאיב מעילא ויהיב לתתא, ונת' שזהו\"ע הפרסא ששואבת חלקי השפע התחתון הכלול בהעליון להיות במדרי' בפ\"ע, דכאשר כלול בהעליון הוא במהות מדרי' העליונה וכשנעשה במדרי' בפ\"ע ה\"ז במהות המדרי' התחתונה כו', וזהו יהי רקיע ויהי מבדיל בין מים למים היינו בין מ\"ע למ\"ת שזהו\nח\"ע וח\"ת, דח\"ת בהיותה כלולה בח\"ע ה\"ה במדרי' ח\"ע וכשנבדלה במדרי' בפ\"ע ה\"ה במהות ח\"ת כו', ומ\"ש ויעש אלקים את הרקיע ויבדל זהו הפרסא שבין אצי' לבי\"ע כו'. וכללות ענין הפרסאות הוא שהמשכת האור מן העליון לתחתון הוא ע\"י הפרסא דוקא שעי\"ז יהי' האור באופן אחר מכמו שהי' קודם כו'.\n<b>ולהבין</b> ענין ההפסק והעכבה של הפרסא ואיך שעי\"ז שאיב מעילא ויהיב לתתא כו', שהרי ענין הפרסא הו\"ע הפסק דבר וצריכים לומר שע\"י ההפסק דוקא הוא דשאיב מעילא ויהיב לתתא, וצ\"ל איך הוא. דהנה ידוע דע\"י צמצום העליון נמצא האור השייך אל התחתון כו', וכידוע בהשפעת השכל מהמשפיע אל המקבל שבתחלה הרי אצל המשפיע אינו ניכר כלל האור שכל השייך אל המקבל רק ע\"י שמצמצם ומעלים אור שכלו בעצמו נמצא בו האור שכל השייך אל המקבל כו', והוא אשר נמצא אצל המשפיע ואין זה עדיין גילוי אל המקבל, אך בענין הפרסא הרי ע\"י ההפסק נמשך האור מן המשפיע שז\"ע דשאיב מעילא כו', וצריכים לומר שזהו שהפרסא כלולה מהעליון והתחתון וכמו שנזכר לעיל בענין חצר הכבד שכלול מרוחני וגשמי וע\"כ כולל חלקי הגשמי שברוחני ובא בהגשמה כו', וצריכים לומר שכלול מההגשמה שבעליון ומהרוחני שבתחתון (ובאמ\"ב כ'"],[3601331103,"שכלול גם מהרוחני שבעליון כו') ועי\"ז הוא שאיב מעילא ויהיב כו', וצ\"ל מה\"ע שכלול משניהם ושכ\"ז הו\"ע ההפסק ועי\"ז דוקא שאיב מעילא ויהיב לתתא כו'. ויובן זה עד\"מ תלמיד היושב לפני רבו ששומע ומאזין השכל הנשפע לו, הנה אז שכלו בטל ונכלל בתכלית בשכל הרב (ענין ההתכללות בשכל הרב הוא הנתינה והמסירה די איבער גיגעבינקייט אין גאנצן אל שכל הרב), ואין שכלו באותו שעה בבחי' יש ודבר בפ\"ע, דכמו בגשמי' בכלים מקבלים ידוע שכלי ריקן מחזיק וכלי מלא אינו מחזיק וכל מה שיהי' הכלי יותר ריקן יהי' ביכולתה לקבל יותר כו', כך הנה התלמיד שצריך לקבל השכל מרבו המשפיע לו א\"א לו לקבל בתוכו ההשפעה של הרב אם הוא מלא על כל גדותיו, דהיינו שהוא בבחי' יש ודבר בפ\"ע שהוא ג\"כ בעל שכל בעיני עצמו ואינו בטל ואינו מסור לשכל הרב, או שמשתמש בשכלו בעת ההשפעה בהבנת והשגת הדבר דהיינו שהוא בבחי' משפיע לעצמו כו', וזהו ג\"כ מצד הישות שלו שהוא בעל שכל בעצמו ע\"כ הוא משמש בשכלו בגילוי והתפשטות השכל להבין ולהשיג איך ומה הוא כו', דבאופן כזה א\"א שיקבל את\nההשפעה ולא יבין כלל כו', ומה שמקבל אינו כלל אמיתת השפע כו', אלא צ\"ל כלי ריקן דהיינו שיהי' שכלו אז בעיניו ריקן כאלו אין לו שכל מצ\"ע כלל רק מה שמקבל מרבו, כי באמת אין לו אז בשכלו רק שכל הרב לבד, כי לא יש שום התפשטות והתגלות משכלו כלל כאלו אינו בעל שכל כלל, ואינו נמצא אצלו רק שכל הרב הנשפע לו, ומשתמש בשכלו אז רק לקבל מה שמשפיע לו הרב, ואז אופן הקבלה אינו שמכווץ ומצמצם עצמו לקבל כ\"א שזהו בדרך ממילא, והיינו דכאשר הוא בעל שכל בעצם הנה זה שהוא מבטל עצמו ושכלו בעת ההשפעה כאלו אין לו שכל בפ\"ע (וז\"ע הכיווץ שהוא הביטול) ממילא הוא מקבל את השכל של הרב, כי יש מקום להשפעת השכל לשכון ולהקלט בכלי התלמיד (והמקום הוא השכל של התלמיד מה שהוא בעל שכל בעצם אבל זהו דוקא כשהוא בבחי' כלי ריקן דהביטול זהו עיקר המקום לקליטת ההשפעה). ולכן אנו רואין שבעת ששומע ההשכלה מהרב הנה גם התשוקה שמשתוקק ובוער כאש לשמוע את השכל ג\"ז מבלבל אותו ומונע אותו מקבלת השכל, ואף שתשוקה זו היא השתוקקות אל שכל המשפיע, עכ\"ז התשוקה היא\nהתפשטות מהותו שרוצה ומשתוקק ואינו בבחי' הביטול והתכללות מכל וכל, וע\"כ א\"א לו לקבל היטב השפעת השכל כי אינו כלי ריקן אמיתי אחרי שיש לו תשוקה שהוא בחי' התפשטות והרגשת מהותו. והגם שהמקבל צ\"ל לו תשוקה אל ההשפעה, דבלא זה הרי אינו רוצה בההשפעה ואינו בבחי' מקבל, והעיקר הוא כי התשוקה של המקבל מעורר חפץ המשפיע להשפיע, שהרי המשפיע מצ\"ע אינו רוצה כלל להשפיע שהרי זה ירידה ממהות עצמו, וצריך לצמצם עצמו להשפיע שכ\"ז כבד מאד להמשפיע, וכאשר רואה תשוקת המקבל אל ההשפעה ה\"ז מעורר אותו בפנימיותו ברצון וחשק להשפיע לו בעין טובה כו' (וגם שזה מעורר גילוי השכל אצל המשפיע שמתגלה ביותר ממקורו כו'), הנה זהו קודם ההשפעה שזהו בבחי' העלאת מ\"ן לגרום ההשפעה ביותר, אבל בעת ההשפעה התשוקה מבלבלת וצ\"ל בבחי' קרירות ובבחי' ביטול בתכלית כו', והביטול שלו לקבל ה\"ז מעורר ג\"כ ההשפעה מהמשפיע, דע\"י שהוא כלי לקבל רוצה המשפיע להשפיע וגם בהשפעה ביותר, וכמו זכאה מאן דמליל על אודנין דשמעין, דעם היות שהמקבל הוא בעל שכל אם"],[3601331104,"אינו כלי לקבל אין המשפיע יכול להשפיע ואינו רוצה להשפיע, כ\"א כאשר הוא כלי לקבל אז הוא משפיע לו ובהשפעה יתירה כו' (ויכול להיות שתשוקת המקבל מעורר בתחלה ירידת וצמצום המשפיע, וכלי המקבל פועל כאשר נמשכה ההשפעה שיהי' הגילוי אל המקבל ובהשפעה בריבוי יותר כו', ואיך שיהי' הרי הביטול שלו מה שהוא כלי לקבל ה\"ז גורם השפעת המשפיע), וגם שעי\"ז נעשה כלי לקבל את ההשפעה כו'. והנה אנו רואין שבעת שמקבל השכל אם ישאלנו אחר איזה שאלה אע\"פ שיודע להשיב לא יוכל להשיב לו כלום והיינו מצד שהוא כלול ובטל לשמוע את השכל ולקבלו שצריך להתבטל במציאותו כנ\"ל, ע\"כ זהו ממילא תכלית ההיפך מלהשיב לאחר ולהיות משפיע שהוא בחי' התפשטות והרגשת מהותו וכמא' איידי דטריד למיבלעי לא פליט כו' (דהטרדא למבלע זהו הביטול כו' וכמשנת\"ל ד\"ה ויגש אליו). אך הנה צמצום זה אינו צמצום אמיתי שאין לו רצון בהשפעה זו והיינו שהוא למעלה מגדר השפעה כו', שהרי אחרי שפסק מלשמוע ומכיל בתוכו השכל שקבל אז ישיב לו, וגם את השכל הזה הרי הוא משפיע אח\"כ, וגם תחלת קבלתו\nהשכל הוא בשביל להשפיע לזולתו כו', דכל מקבל הוא משפיע דכאשר מקבל וקולט ה\"ה משפיע ומוליד כו', רק מצד שכלול ובטל בהמשפיע הוא שאינו יכול להיות אז משפיע כו'. ונמצא שמניעת ההשפעה לשואלו הוא עצמו בחי' הכיווץ והביטול שהוא בטל לרבו כו', ומניעת ההשפעה הוא רק עכבה שמעכב עצמו מלהשפיע לעצמו ולזולתו כו', דבעצם ה\"ה שייך להשפעה כנ\"ל רק שמעכב עצמו כו', וא\"כ ה\"ז כמו הסתר רק שההסתר הוא ע\"י הביטול, וזהו הביטול לעכב עצמו שלא יהי' התגלות לא לעצמו ולא לזולתו כו', וביטול ועכבה זאת היא גורמת ההשפעה מהמשפיע, ועי\"ז הוא מקבל את ההשפעה, ועי\"ז דוקא נקלט אצלו ההשפעה כו'. והנה מה שמקבל הוא ההשפעה שבערך המקבל היינו בחי' חיצוני' השכל של הרב, וכשמקבל את ההשפעה ה\"ז בא אצלו כפי מהותו היינו כפי חושי השכל וההשגה שלו כו', שז\"ע הקליטה דכאשר הדבר נקלט בו הרי ביכולתו להביא ענין ע\"פ חושים שלו שאינם כמו חושי הרב כו'. וכ\"ז הוא ע\"י הביטול והכיווץ שלו דוקא, שעי\"ז דוקא נעשה כלי לקבל שיוקלט בו ההשפעה כו'.\n<b>ובזה</b> יובן מה שבחי' מל' היא בחי' מקבל, דמדרי' שלמעלה מבחי' המל' אינם בבחי' מקבל וכמ\"ש בזהר דכד סלקא מילין מכנס\"י ולעילא כולהו דכורין אינון, רק מל' היא בחי' מקבל כו' (דעם היות שכל הספי' מקבלים זמ\"ז וכן כולם מקבלים מאוא\"ס המאציל, זהו שהם בבחי' השתל' זמ\"ז וכולם משתלשלים ונאצלים מאוא\"ס המאציל כו', שאין זה ענין הקבלה כו', ולעיל (ד\"ה ויגש אליו) נת' שהן ג\"כ בבחי' מקבלים לגבי אוא\"ס וכמו שהקו בכלל נק' שכינה כו', ומ\"מ אין זה בבחי' מקבל ממש כו', דבד\"כ ענין עו\"ע אין זה אמיתי' ענין משפיע ומקבל שהרי זהו בבחי' קירוב הערך, שהעילה היא שמשפעת בבחי' קירוב וכן העלול הוא בערך העילה כו', וענין משפיע ומקבל הוא שנבדלים זמ\"ז שהמקבל הוא מהות אחר מן המשפיע והוא בבחי' מקבל כו' ובעו\"ע אינו באופן כזה כו', וכמו\"כ למעלה הרי המשכת האורות מאוא\"ס ב\"ה הן בבחי' קירוב דהגם שזהו ע\"י הצמצום מ\"מ ה\"ז ע\"י שהאוא\"ס חזר והאיר וכמ\"ש בע\"ח המשיך אוא\"ס קו א' כו' וכמ\"ש במ\"א, וכן הקו הוא נוגע ודבוק כו' (ובודאי צריכים לחלק בין מה שהן בבחי' נאצלים מאוא\"ס ב\"ה ובין מה שהן"],[3601331105,"בבחי' מקבלים כו', ואפשר זהו ההפרש בין מה שהאור הוא בבחי' גילוי מן העצם ומעין העצם ובין מה שהאורות הן ג\"כ בבחי' לבושים לגבי אוא\"ס ב\"ה וכמ\"ש במ\"א, ומ\"מ אין זה בבחי' מקבל ממש), אבל בחי' מל' אין זה בבחי' אצי' שלה ולא בקבלה שלה בבחי' קירוב כ\"א שהוא בחי' מקבל כמו מהות אחר המקבל כו') שמקבלת מהספי' העליונות וכמ\"ש כל הנחלים הולכים אל הים שזהו ההמשכה מבחי' הששה מדות דז\"א שמשפיעים בבחי' מל' (ומל' משפעת האור בעולמות בי\"ע כו'), וה\"ה מקבלת כל האורות העליונים ועוד איננו מלא מהם וכמ\"ש והים איננו מלא כו', והיינו שהמל' היא בבחי' כלי לקבל כל האורות כו'. וזהו לפי שהמל' יש בה בחי' הכיווץ והביטול ביותר דמשו\"ז היא בבחי' כלי לקבל ולא יספיק כל ההשפעות אלי' מבחי' ז\"א כי תוכל לקבל יותר ועז\"נ ארץ לא שבעה מים כו', והגם שמל' היא בחי' יש וכמשנת\"ל, הנה מ\"מ יש בה כח ביטול היש ביותר כו', והוא הביטול בבחי' הנחת עצמותו (מיט א אוועקלייג) כו'. וכמו דוד המע\"ה שהי' מרכבה לבחי' המל' הרי הי' בבחי' ביטול ושפלות ביותר וכמ\"ש ואנכי\nתולעת ולא איש, כי עני ואביון אני, אם לא שויתי ודוממתי כו', לפי שהמל' היא בבחי' ביטול היש ביותר כו', והראי' שהרי הנשמות ע\"י העבור שלהם בבחי' המל' נעשה בהם ביטול היש שלהם כו', די\"ל שזהו בכללות הנשמות גם בנשמות דמ\"ה שהן בבחי' עבור במל', הנה לבד זאת שזהו בכדי שיוכלו לבא בעולם התחתון כו' (שזהו שיהיו בבחי' מציאות כו') ה\"ז ג\"כ בשביל ביטול היש דהיינו הלבושים שהנשמה מתלבשת בהם כו', ובפרט בנשמות דב\"ן שנעשה בהם הביטול ע\"י העבור, וכל מה שהן בעבור יותר ה\"ה בבחי' ביטול יותר בהישות שלהם כו', וכמו אלי' שהי' בעבור יב\"ח הרי הי' גופו בבחי' ביטול בתכלית וכמו ורוח אלקים ישאך שהגוף נתעלה עם הנפש ועלה בסערה השמימה כו'. וזהו ג\"כ ענין תיבת נח דכתי' לחיות זרע על הארץ ואי' בזהר נח איצטרך לתיבה לאתחברא בה ולקיימא זרעא דכולא כו', דבכדי שיהי' קיום לנשמות הנמשכים לבי\"ע ולא יפלו ממדריגתן הוא ע\"י שהיו בתיבה יב\"ח שהתיבה היא בחי' מל' כו', דכמו שלמעלה צ\"ל עיבור בבחי' מל' כמו\"כ בבריאת והתהוות העולמות הי' צ\"ל ההעכבה בתיבה\nיב\"ח שעי\"ז הי' הקיום שלהם כו', כי הנפילים היו בארץ כתי' בהם אנשי השם בחי' דכר שהוא בחי' ז\"א כו' והן נצוצות שנפלו מבחי' ז\"א שלא ע\"י עבור המל' כו', וע\"י המל' הוא הקיום לפי שעי\"ז נעשה ביטול היש כו', והכלי לקבל הוא דוקא בחי' ביטול היש, שהרי מה שבבחי' ביטול במציאות לגמרי שאינו בבחי' יש כלל הרי אינו בבחי' כלי ואינו בבחי' מקבל כו', ולהיפך בחי' המציאות לגמרי אינו כלי כו' (וזהו דבמדרי' העליונות דאצי' ה\"ה בבחי' ביטול במציאות לגמרי ונק' ע\"ס בלי מה כו', שאינם בבחי' מקבל כו', והניצוצות שנפלו מזה נעשו בבחי' נפילים כו', וי\"ל דזהו ג\"כ מה שהשבירה הי' בבחי' מדות דתהו אבל בחי' מל' רק ארעא אתבטלית לבד כו'), ורק מה שהוא בבחי' יש ובבחי' ביטול היש ה\"ז בבחי' כלי לקבל כו', וע\"כ בחי' המל' שהיא בחי' יש ומ\"מ היא בבחי' ביטול היש בתכלית ה\"ה בבחי' כלי לקבל כל האורות העליונים והים איננו מלא מהם כו', ובחי' הביטול של המקבל שעי\"ז הוא בחי' העצרה והעכבה שאינו בבחי' משפיע כו', ה\"ז הפסק האור שאין כאן גילוי אור כו', וההפסק דוקא הוא שגורם ההשפעה מן המשפיע, ועי\"ז הוא כלי לקבל שנקלטה בו ההשפעה ובאה"],[3601331106,"בבחי' מהות אחר ממהות המשפיע והיינו שנעשה כפי חושי המקבל כו', וז\"ע דשאיב מעילא כו' שע\"י הפרסא שהוא בחי' הפסק עי\"ז דוקא שאיב מעילא ויהיב לתתא כו'.\n<b>ועפ\"ז</b> יובן ג\"כ משנת\"ל (ד\"ה ויקחו לי תרומה) בענין המשכת המוחין למדות שזהו ע\"י הפסק מיצר הגרון והוא ההעלם שמתעלם האור קודם שבא ללב כו', הנה העלם זה י\"ל שזהו ג\"כ בחי' הביטול והוא שאחר ההתבוננות וההתפעלות שכלו בהענין כשבא האור להתגלות בלב הנה ע\"י הדעת המתפשט נמשך הלב אל המוח דבעת שמתפעל במוחו יש גם המשכת הלב אל הענין רק שזהו בהעלם לא בבחי' אהבה עדיין כו', והוא בבחי' הבל פנימי שבלב כו' כמ\"ש במ\"א, ועי\"ז נעשה הביטול בהמדות שמתבטלים מכל גילוי אור כו', וזהו ההפסק שאין כאן גילוי אור כלל כו', אך זאת הוא דוקא הסבה להתגלות המוחין במדות שע\"י הביטול וההפסק הזה ה\"ה בבחי' כלים לאור המוחין, ועי\"ז בא הגילוי מהמוחין בלב כו', רק שבאים באופן אחר מכמו שהן במוח וה\"ה כמהות המדות כו' וכמשנת\"ל שם. וז\"ע הרקיע שע\"ג ראשי החיות שנא' ע\"ז רקיע כעין הקרח הנורא, דקרח הוא שנגלד ונקרש המים וה\"ז הפסק ההמשכה דמים נמשכים ונגרים, וכאשר נקרשו המים הרי נפסק המשכתם והתפשטותם כו', וז\"ע הרקיע דאגלידו מיא שהוא ההפסק שבין\nהמוחין אל המדות כו', וידוע דקרח הוא אותי' חרק שהו\"ע הביטול כו', והיינו ביטול המקבל אל המשפיע שעי\"ז הוא העצרה והעכבה בהתפשטות שלו (ובמדות הו\"ע הביטול במהות העצמות שלהם כו' כנ\"ל), ובזה דוקא הוא מקבל את האור שבא כפי הכלים והחושים שלו כו', וז\"ע הפרסא שבין בינה לז\"א דאצי' שהוא הרקיע המפסיק ביניהם כו'. והנה מה שההפסק הוא ביטול זהו בד\"כ בפרסאות דאצי', אבל בהפרסא שבין אצי' לבי\"ע הפרסא היא בחי' העלם כו', אך באמת צ\"ל דכל פרסא היא כלולה מהב' מדרי' והוא ההפסק שבבחי' העלם וההפסק שבבחי' ביטול כו', והוא כמו שהוא מצד המשפיע ומצד המקבל, דמצד המשפיע הוא בחי' העלם שהאור מתעלם בהפרסא וכמו התלבשות השכל בלבושי השגה ובמשלים וכה\"ג, ומצד המקבל הוא בחי' ביטול כו', דכן הוא בפרסאות דאצי' ובפרסאות דבי\"ע כו', דבאצי' ג\"כ יש בחי' בהפרסא שהוא בחי' העלם שהאור מתעלם בה כו', וכמו\"כ בבי\"ע יש ג\"כ בהפרסא שהיא בבחי' ביטול, וז\"ע הרקיע שע\"ג חיוון תתאין דחיות המרכבה דעולם הברי' הן בבחי' ביטול, וכמו בעמדם תרפינה כנפיהם שמתבטלים\nמהתשוקה שלהם כו', שהו\"ע העצרה והעכבה כו', ועי\"ז דוקא נעשים כלים לקבל את האור כו', וכן הוא במרכבה דיצי' ועשי' דבכולם הו\"ע הביטול וזהו בחי' הפרסא כו', לבד הפרסא האחרונה שמתברר הפסולת ממש דשם הוא רק העלם כו', והרי שם אינו בחי' מקבל ולא בבחי' שאיב מלעילא כו', אבל במדרי' הקדושה הכל הוא בבחי' ביטול כו', וזהו שהפרסא היא ממוצע וכוללת ב' המדרי' דהיינו שהיא בחי' התעלמות אור המשפיע ובחי' הביטול של המקבל כו'. והנה כשם שההמשכה ממוחין למדות הוא ע\"י הפסק הפרסא, כמו\"כ ההמשכה במוחין ממקורם הוא ג\"כ ע\"י הפרסא והן הפרסאות שלמעלה מאצי' כו' שעז\"נ והבדילה הפרוכת לכם בין הקדש ובין קדה\"ק כו'. והענין הוא דהנה כתי' לבושי' כתלג חיוור וידוע שזהו בחי' יגת\"ד דמו\"ס כו', ואומר שהן כתלג חיוור דוגמת השלג שזהו שהמים נקפאים ונעשה שלג כו' (וידוע דמי גשמים בתחלה הם שלג בהעננים שהן באויר האמצעי"],[3601331107,"שהוא קר ונמס באויר התחתון ונעשה מים כו'), וצ\"ל ההפרש בין שלג לקרח שזה גילודו קל וזה גילודו קשה (ובמשנה דמקוואות דמשלג יכולים לעשות מקוה בתחלה, וקרח לדעת הרמב\"ם בה' מקוואות פ\"ז ה\"ג רק מעלה ומשלים כו', ומבו' במ\"א מפני שקרח הי' תחלה מים ונגלד ושלג לא הי' תחלה מים וכנ\"ל שבענן הוא שלג, וי\"ל דשלג הוא מבחי' אור כמשי\"ת, ומיהו שארי הפוסקים אין מחלקים ביניהם, ולדעת רש\"י גם משלג אין עושין מקוה בתחלה וכמ\"ש הב\"י).\n<b>ולהבין</b> זה ילה\"ק תחלה ענין אור מים רקיע, הנה אור ומים הן ענין א' דשניהם בחכ' כידוע, רק שהמים הוא בחי' חכ' הגלוי' והוא מה שמשכיל בשכלו איזה השכלה דנקודת ההשכלה היא כדוגמת המים כו' (והיינו כמו שהמים ניידי אנה ואנה, וגם הן בגוון פשוט כו', כמו\"כ הנקודה אין בה גוון עדיין ויכולה לבא בכמה אופנים שונים, וכמשנת\"ל ד\"ה הנ\"ל דנקודה אחת באה בנטיות שונות כו'), ואור הוא מקור החכ' והוא כח המוליד ההשכלות שממנו נובעים ונמשכים כו', דאותו כח הוא כח היולי שאינו נרגש ונתפס במציאות דבר מה כו', ועש\"ז נק' אור שאינו במציאות דבר עדיין כו'. ויובן עד\"מ המשכת הטפה ממוח האב, דהנה עיקר משכן יסוד המים הוא במוח, דלב הוא יסוד האש ומוח יסוד המים כו', דמי שיש בו הרבה לחלוחית במוחו הוא בר הבנה ביותר ויכול לחדש השכלות והמצאות חדשות לפי שהשכלים נובעים מהלחלוחית שבמוח, והנה הלחלוחית הזאת אינה לחלוחית גשמי כמים אלא שהוא רק כח הלחלוחית ונק' יסוד המים כו', וכמו המים היסודי שאינו מים ממש כו' (וכמשנת\"ל ד\"ה אז ישיר דהכנת\nחומר המוח לקבל אור השכל הוא בהרוחניות שבחומר המוח כו'), וה\"ז כמו הטל שהוא ג\"כ לחלוחית ומ\"מ אינו כמים שהוא לחלוחית דקה ורוחני כו', כמו\"כ הלחלוחית שבמוח הוא כח רוחני, וממנו נתהווה הטפה שהוא שנתגשם מהכח הלחלוחית הרוחני שבמוח. והנה גם כשנמשכה הטפה ממוח האב הרי כשנקלטה בבטן הנוק' ומתהווה ציור הולד באברים וגידים ה\"ז הגשמה שנית, והרבה יותר מהגשמת הטפה דעם היותה גשמי ורחוקה מאד מערך הלחלוחית הרוחני שבמוח מ\"מ ה\"ה מופשטת עדיין מתואר גשמי עד שיתכן לומר ע\"ז שיהי' כך או כך, וכמארז\"ל דמלאך הממונה על ההריון מביא הטפה לפני הקב\"ה ואומר טפה זו מה תהא עלי' כו', אמנם כמו שהיא בלחלוחית שבמוח איך שייך לומר מה תהא עלי', מפני ששם הוא לא בבחי' מהות ומציאות דבר כלל, רק כמו שבא בבחי' טפה שנתגשמה במהות ומציאות דבר שייך לומר מה תהא עלי' כו'. ומ\"מ מזה שיכולה להיות בכמה אופנים שונים מובן שהיא מופשטת עדיין מאיזה תואר וה\"ה בבחי' פשיטות עדיין, וכשנתהווה ממנה ולד ה\"ז מתגשם ממש ואינו שייך בזה שינוי כלל כו'. וכמו\"כ הוא\nבענין אור מים רקיע דאור הוא עדיין כח היולי בתכלית הפשיטות לגמרי שאינו נתפס בשום מציאות כלל, ומים הוא שבא בבחי' מציאות דבר שנרגש במישוש ומתפשט ממקום למקום כו' (וזהו דאור יכול להיות בכ\"מ ואינו מקבל שינוי משום דבר, וכמו אור השמש שיכול להיות במקום האשפה ואינו מקבל שום עכרורית מזה מפני שאינו במציאות דבר ובכ\"מ שהוא ה\"ה בבחי' הבדלה כו', משא\"כ המים מקבלים שינוי אם יהיו במקום האשפה וכה\"ג להיותם בבחי' מציאות כו'), ומ\"מ גם המים הוא בבחי' רוחני לגבי רקיע שהוא מה שאגלידו מיא שזהו כמו הקרח שנקרש המים ונצב כמו נד שנעשה כדומם ממש"],[3601331108,"שעומד במ\"א ואינו ניזוז כלל, אבל מיא ניידי שמתפשט אנה ואנה כו'. והדוגמא למעלה ידוע דאור הוא בחי' ח\"ס שאינו בבחי' מהות חכ' כלל, וכמו עד\"מ כח המשכיל שאינו במציאות שכלי עדיין כלל כידוע, ומים הוא בחי' חכ' דאצי' שהיא בבחי' מהות חכ' ומ\"מ היא בבחי' פשיטות עדיין כו', ורקיע בחי' בינה שזהו כענין השגה שבא בבחי' ציור ממש כו'. אמנם יובן ג\"כ דבחי' מים ורקיע זהו\"ע שלג וקרח דשלג הוא שע\"י הקרירות נקרש המים ונעשה שלג, ובאמת אין זה שהמים נקרשים וכנ\"ל שבעננים מתהווה שלג ואח\"כ באויר התחתון נעשה מים, וא\"כ מתחלתו הוא שלג כו', רק שהשלג גילודו הוא דק ובקל ה\"ה נמס ונעשה למים כו', וה\"ז כדוגמת המים שזהו הגשמה לגבי אור, ומ\"מ מיא ניידי ובבחי' פשיטות עדיין כו', כמו\"כ השלג הוא שנגלד אבל גילודו קל ודק כו', וקרח הוא שנקרש הרבה שזהו כדוגמת הרקיע וכמ\"ש רקיע כעין הקרח כו'. והענין יובן למעלה עפמ\"ש בזהר תרומה דקס\"ז ע\"ב בענין התהוות או\"א וז\"ל אדם קדמאה אתצייר ואתגליף בלא נוקבא כו', אינון אתוון אגלימו גו משחתא כו', מרזא דאור\nקדמאה שריאו לאתגלפא ולאתציירא ואזדרע האי אור בגוי' גו משחתא, כד מטא גו משחתא אתהדר מיא גו מיא אתפשט רקיע ציורא דאדם כו', ופי' במק\"מ אדם קדמאה הוא או\"א דאתגליף תוך שערות דאריך דרישא ודיקנא יקירא הנק' משחתא כו', ועז\"א מרזא דאור קדמאה חסד דאריך (ואפ\"ל דאור קדמאה הוא בחי' ח\"ס וכידוע דאור הוא בחי' חכ' ואור קדמאה הוא בחי' ח\"ס כו'), ושם היו אתוון שמהם נעשה אבא כו', דח\"ס היא מקור החכ' כו', ושם הוא בבחי' אור כו', וכד מטא גו משחתא פי' במק\"מ בחי' דיקנא דאריך כו', נעשו מים שזהו בחי' הגלמת האור כו', וזהו בחי' שלג הו\"ע המים כנ\"ל, וגוי מיא אתפשט רקיע היינו שע\"י הרקיע נמשך גילוי בחי' החכמה כו' וכמשי\"ת. וזהו לבושי' כתלג חיוור שזהו בחי' הפרסא שבין ח\"ס לחכ' דאצי', דבכדי שיהי' התהוות החכ' מח\"ס צ\"ל ג\"כ ע\"י פרסא, רק שהיא דקה ורוחני יותר מבחי' הקרח שזהו הפרסא שבין או\"א לז\"א כו'.\n<b>ועפ\"ז</b> יובן מ\"ש ואתה תצוה כו' ויקחו אליך שמן זית כו', דהנה ידוע דשמן המנורה הוא בחי' ח\"ס, דסתם שמן הוא בחי' חכ' ושמן המנורה בחי' ח\"ס וכמ\"ש שמן משחת קדש שמושח את הקדש כו', וכמ\"ש בלק\"ת בהביאור דבהעלותך, דהנה ג' שמנים הן, הראשון למנורה והשני למנחות כו', פי' הראשון הוא בחי' ח\"ס שזהו הראשית לכל בחי' חכ' ונק' שכל הנעלם מכל רעיון שזהו בחי' המשכה נעלמת בבחי' מקור לחכ' כנודע, ושמן השני הוא בחי' חכ' דאצי' והוא למנחות דמנחות הן לאכילה שזהו בחי' או\"פ וכמו ותורתך בתוך מעי בחי' מזון פנימי כו', והו\"ע אכלו רעים בחי' חו\"ב כו', אבל בחי' ח\"ס הוא בחי' אור שלמעלה מבחי' גילוי ולא בבחי' או\"פ ממש כו' ה\"ז למנורה בחי' אור כו'. ועז\"א ויקחו אליך שמן זית זך, דהנה משה הוא בחי' חכ' דאצי' ויקחו אליך היינו ההמשכה מבחי' ח\"ס הנק' שמן זית זך כו', והוא שיהי' גילוי בחי' ח\"ס בחכ' דאצי' כו', להיות דהמשכת החכ' מח\"ס הוא ג\"כ ע\"י הפרסא כו' ע\"כ ויקחו אליך גילוי בחי' עצמו' ח\"ס כו'. וזהו ואתה תצוה דהנה כתי' כי אתה נרי הוי' והוי' יגי' חשכי, וידוע דכי אתה נרי הוי' הוא הוי' דסדר השתל' בחי' והוי' בחכ' כו', והוי'"],[3601331109,"יגי' חשכי הוא ש' הוי' שלמעלה מהשתל' כו', וזהו ואתה אתה הוא ענין כי אתה נרי ה', והוא\"ו הנוסף הו\"ע והוי' יגי' חשכי, והיינו התחברות ב' שמות הוי' דהוי' שלמעלה מהשתל' יאיר בגילוי בהוי' דהשתל' כו'. וזהו תצוה ל' צוותא וחבור כו', וכ\"ז הוא הגילוי למשה דהיינו באצי' כו', ואח\"כ אומר מחוץ לפרוכת כו' יערוך אותו אהרן כו', הנה פרוכת הוא פרסא וקאי על הפרסא שבין אצי' לבי\"ע והוא מ\"ש כי שמש ומגן ה' אלקים ש' אלקי' המעלים על הש' הוי' כו', דבאצי' מאיר גילוי ש' הוי' אבל בבי\"ע אינו מאיר ש' הוי' כ\"א ש' אלקים כו', וזהו מחוץ לפרוכת יערוך כו' דאהרן הוא שושבינא דמטרוניתא, פי' מטרוניתא הוא בחי' מל' כנס\"י מקור נש\"י דכל ישראל בני מלכים הם כו', ושושדמ\"ט הוא שמעלה נש\"י מברי' לאצי' כו', דנשמות דבי\"ע הביטול שלהם הוא בבחי' ביטול היש ומעלה אותם באצי' להיות בהם ביטול האמיתי כמו שהוא מצד החכ' כו', וזהו כאשר תחלה נמשך תוס' אור באצי' שז\"ע ואתה תצוה כו' ויקחו אליך למשה אז ע\"י אהרן נמשך האור גם בבי\"ע להיות העלי' בנשמות דבי\"ע כו',\nוזהו שמודיע כאן מחוץ לפרוכת יערוך אותו כו' דאין הכוונה בזה מקום עמידת המנורה דהרי עמידתה הי' בהיכל וידוע שזהו מדרי' האצי' כו', וכידוע דהג' דיורים שבמקדש הן התלת עלמין שבזהר פ' שלח, דקדה\"ק הוא נגד עולמות הא\"ס שלמעלה מאצי', וההיכל נגד עולם האצי' והחצר נגד בי\"ע כו', ובכאן הכוונה להודיע ענין ההעלאה שהוא דבנשמות דבי\"ע יהי' בהם הביטול כמו באצי', וזהו כאשר נמשך תוס' אור באצי' כו', ע\"כ באומרו ויקחו אליך שמן כו' או' אח\"כ מחוץ לפרוכת יערוך אותו כו'. וזהו דבפסוק הראשון אומר להעלות נר תמיד ואח\"כ אומר מערב עד בקר, דהנה ענין הנר להאיר שייך במקום החשך והיינו במדת לילה בחי' מל' המקור לבי\"ע שהוא בחי' חשך והעלם כו' צריכים להאיר ע\"י בחי' נר כו', אבל מדת יום א\"צ להאיר דשרגא בטיהרא כו', אבל יש אור שצריכים להמשיך ולהאיר בו גם בחי' מדת יום והיינו בחי' האור דח\"ס שזהו בחי' תוס' אור גם לגבי אצי' בחי' מדת יום כו', וזהו דגבי ויקחו אליך אומר להעלות נר תמיד היינו גם במדת יום, וגבי מחוץ לפרוכת אומר מערב עד בקר היינו\nלהאיר בחי' מדת לילה כו'. וזהו ואתה תצוה דאומר כסדר המדרי' מלמעלמ\"ט תחלה ואתה תצוה חבור ב' השמות דהוי' כו' ויקחו אליך תוס' אור למשה גילוי בחי' עצמות ח\"ס כו', ואח\"כ מחוץ לפרוכת יערך אותו אהרן מחוץ לפרסא המפסקת בין אצי' לבי\"ע כו', מערב עד בקר להאיר מדת לילה דנשמות דבי\"ע יהי' הביטול כמו באצי' כו'."],[3601331110,"<h3>בס\"ד. ש\"פ תשא, העת\"ר</h3>\n<b>כי</b> תשא את ראש בנ\"י לפקודיהם ונתנו איש כופר נפשו לה', זה יתנו כו' מחצית השקל כו' עשרים גרה השקל כו', וצ\"ל מה\"ע כי תשא למה לא נא' כי תפקוד. גם מהו לפקודיהם דלכאו' הוא מיותר אחרי שכבר כי תשא את ראש כו'. גם צ\"ל מ\"ש ונתנו איש כופר נפשו איזה חטא יש כאן שצריכים כופר לנפשו כו'. גם מהו אומרו עשרים גרה השקל, מאחר שצריכים ליתן מחצית השקל מה נצרך להודיע כמה הוא שקל שלם. ורש\"י פי' על כי תשא ל' קבלה וכמו שת\"א ארי תקבל חושבן בנ\"י, וצ\"ל מה\"ע קבלת ראש בנ\"י כו'. ולהבין כ\"ז ילה\"ק משנת\"ל בענין לבושי' כתלג חיוור שזהו הפרסא שבין ח\"ס לחכ' דאצי' דכשם שיש פרסא בין מוחין למדות דהיינו בין בינה לז\"א כמו\"כ יש פרסא בין ח\"ס לח\"ע, וזהו לבושי' כתלג חיוור שהיא כדוגמת השלג שהוא דבר הנקפא ונגלד רק שגילודו קל דקרח גילודו קשה ושלג גילודו קל, והיינו שאינו העלם כ\"כ כו', והו\"ע מים ורקיע, וכמ\"ש בזהר פ' תרומה בענין התהוות או\"א דמרזא דאור קדמאה בחי' ח\"ס שריאו לאתגלפא ולאצטיירא ואזדרע האי גו משחתא בחי' דיקנא דאריך, וכד מטא\nגו משחתא אתהדר למיא שזהו הגשמת בחי' האור והו\"ע השלג כו', גו מיא אתפשט רקיע ציורא דאדם בחי' אדם עילאה חכ' דאצי' כו'.\n<b>והנה</b> י\"ל דכוונת הזהר הוא דבחי' רקיע זהו ג\"כ בחי' ממוצע בין ח\"ס לח\"ע כו', דמש\"א גו מיא אתפשט רקיע אין הכוונה דרקיע הוא בחי' אדם עילאה, כ\"א דבחי' מיא ורקיע זהו הכל בחי' ממוצע להיות הגילוי מבחי' ח\"ס בח\"ע דאצי' כו'. דהנה אי' בזהר שם דהתהוות או\"א הוא תחות עלמא דאתי, ופי' המק\"מ עלמא דאתי בחי' בינה דאריך דמגרון דאריך שזהו בינה שבו נעשו כתרים דאו\"א, ובע\"ח שט\"ו פ\"א שזהו מיחוד חיך וגרון דהיינו חו\"ב דאריך כו', וענין חו\"ב דאריך הוא הרצון להשכיל והרצון להשיג כו', דהרי יש כל ע\"ס כמו שהן כלולים בכתר שהוא מקור האצי' כו', וידוע דכתר הוא בחי' הרצון כו', ואנו רואין דכל הכחות תלוים ברצון וכמו כאשר רוצה להתחכם או שרוצה באיזה ענין לייגע ולהעמיק בו ישכיל ויתחכם בו, אבל כאשר אינו רוצה להתחכם בכלל או שאינו רוצה בהענין הזה לא ישכיל ויתחכם מאומה, וכן בכח הבינה כאשר רוצה להשיג ישיג וכשאינו להשיג לא ישיג כלום כו', וכן הדבור תלוי ברצון דכשרוצה להרחיב הדבור ירחיב אותו וכשרוצה למעט ולקצר ימעט ויקצר כו',\nונמצא דחו\"ב שבכתר זהו מה שרוצה להשכיל ולהשיג כו'. והרי יש בחי' חו\"ב ממש בכתר לא רק הרצון להשכיל ולהשיג, זהו כי הרצון למעלה הרי ע\"י הרצון נתהווה ממש אותו הדבר דלא מחשבותי מחשבותיכם כו', וע\"י הרצון בחו\"ב נעשה ממש בחי' חו\"ב ברצון כו', ומבחי' בינה דאריך ע\"י יחוד חיך וגרון נעשו כתרים דאו\"א כו'. וענין כתר דחכ' זהו מה שנמשך מח\"ס להיות בחי' מקור לחכ' כו', והוא בחי' האין של גילוי היש דחכ' שזהו המשכה מבחי' ח\"ס כו', דח\"ס היא מקור החכ' אבל אינו בבחי' המשכה עדיין והוא המשכה נעלמת מבחי' כח היולי העצמי דהיינו בחי' חכ' דעקודים או חכ' דא\"ק כו', אבל אינו נמשך עדיין להיות מקור ממש לחכ' הגלוי' כו', ובחי' כתר שבחכ' הוא מה שכבר נמשך מבחי' ח\"ס בבחי' מקור ממש לחכ' הגלוי' כו', והוא בחי' גילוי רק שזהו העלם עדיין לגבי"],[3601331111,"החכ' כו', ובשכליים פרטי' הוא מה שמאיר הענין בשכלו קודם שבא ההשכלה בגילוי כו'. וכמו המייגע באיזה ענין הרי שיודע הענין הנה העדר ההשגה הוא בחי' חשך, ואח\"כ מתחיל להאיר במוחו אף שאינו משיג עדיין (עס ווערט עם ליכטיג במוחו דער שכל הייבט אן צוא לייכטין כו'), ויותר מזה הוא שנרגש במוחו הבנת הענין קודם שמבין הענין (עס הערט זעך רעכטקייט במוחו דמתחלה הוא שהענין מוקשה אצלו ואח\"כ מתחיל להרגיש רעכטקייט בהענין אף שאינו יודע עדיין איך ומה כו'), ויותר מזה הוא בחי' ניצוצי אור שמאירים במוח קודם שבא ההשכלה בגילוי ממש כו' וכמ\"ש במ\"א. וכמו\"כ בחי' כתר דחכ' בכלל הוא בחי' גילוי אור שמאיר בחכ' בבחי' העלם ובבחי' מקיף כו', ומזה נעשה בחי' הרקיע דחכ' כו'. והענין הוא דכשם שהרקיע שע\"ג חיוון עילאין הוא מבחי' בינה וכמ\"ש מבטן מי יצא הקרח הנורא כו', וביאור הענין מובן ע\"פ משנת\"ל (ד\"ה ואתה תצוה) דאור המוחין מאירים בלב ע\"י דעת המתפשט כו', דההתפעלות שכלי מאיר בלב ע\"י הדעת כו', שזהו ג\"כ בהעלם עדיין בלב כי לא יש כאן התפעלות המדות\nשבלב כו', ומזה נעשה הרקיע דהיינו ביטול המדות כו', כמו\"כ מבחי' גרון דאריך דהיינו בחי' בינה שבו (שממנו נעשה כתר דחכ') נעשה בחי' רקיע דחכ' שזהו בחי' הביטול דחכ' שעי\"ז נעשה כלי לקבל הגילוי מבחי' ח\"ס כו', והו\"ע ההשתוממות וכמו אשתומם כשעה אחד דלהיות שהענין למעלה מערך חכמתו וצריך להמשיך אור חדש ממקור השכל כו', ע\"כ אשתומם שזהו העלאת וביטול כלי שכלו למקור לקבלו גילוי אור חדש ממקור השכל כו'. וכמו המייגע א\"ע בענין עמוק שלא יוכל להשיגו מפני עומקו כו', ומעמיק א\"ע בהשגה זו איך ומה הוא כו', הנה לאחר ההעמקה משתומם לגמרי, שזהו כמו הפסק השכל לגמרי, דכאשר מעמיק א\"ע ומייגע בהענין הרי נמצא אור שכל במוחו, וכאשר משתומם הוא הפסק האור שלא יש כלל אור שכל במוחו כו' והוא ביטול ההשגה שלו לגמרי, והשתוממות זאת היא ממוצע שעי\"ז בא על ההשגה הנפלאה כו', וכנראה בחוש שאחר ההשתוממות נופל בדעתו השכלה והמצאה חדשה שהענין הוא באופן כך וכך והוא בא על עומק הענין כו', ובאמת ההשתוממות הוא מפני שמאיר ממקור השכל כו', דבתחלה כאשר\nמעמיק ומעיין בהענין שאז יש אור שכל במוחו הוא שהענין הזה הוא רחוק עדיין ממנו, וכאשר האור שכל נמשך ממקור השכל (קודם שבא לידי גילוי ממש) זהו סבת ההשתוממות שמשתומם לגמרי והוא ביטול ההשגה שלו, ועי\"ז דוקא נעשה כלי שמאיר האור ממקור השכל כו', וכמו\"כ הוא בחכ' בחי' ביטול החכ' ועי\"ז נעשה בבחי' כלי לקבל האור מבחי' ח\"ס כו'. והענין הוא דבכדי לקבל גילוי אור עליון צ\"ל ביטול הכלי דוקא כו', וע\"ד דר\"ז צם מאה תעניתא בכדי לישכח תלמוד בבלי, דלכאו' אינו מובן מה הוצרך לשכוח דוקא ולמה לא יהיו שניהם. אך הענין הוא דהרי אין תורה כתורת א\"י כו', דכל רב מבבל וכל רבי מא\"י שנתוסף אות יו\"ד שהוא בחי' החכ' כו', ולכן על תלמוד בבלי אמרו במחשכים הושיבני זה תלמוד בבלי, שמתלבש בבחי' החשך לברר כו', שזהו אריכות הפלפול דת\"ב בריבוי הקושיות ותירוצים שזה\"ע הבירור כו' כנודע, וזהו מפני שת\"ב הוא בחי' מוחין דאימא וע\"י הארת החכ' במוחין דבינה עי\"ז הוא הבירור כו', אבל הוא ע\"י ההתלבשות במקום החשך לתקנו ולבררו כו', משא\"כ בת\"י אין בו אריכות הפלפול רק בקיצור נמרץ, וע\"פ הרוב הוא הלכות"],[3601331112,"פסוקות והיינו שזהו בחי' החכ' שאינו מתלבש בבחי' חשך כו', אבל האור בזה הוא נעלה ביותר כו' והבירור הוא בדרך ממילא כו', והוא בחי' בירור שני דש' מ\"ה המברר כו' וכמ\"ש במ\"א, וזהו דר\"ז צם כו' בכדי לישכח תלמוד בבלי היינו בחי' הביטול בת\"ב בכדי לקבל האור דת\"י כו'. וכן הוא בעליית הנשמות מגעה\"ת לגעה\"ע שהעלי' היא דרך העמוד שזהו ביטול הנשמה בכדי לקבל ההשגה העליונה דגעה\"ע כו', והיינו שע\"י העמוד מאיר הארה מגעה\"ע בבחי' העלם ומקיף על הנשמה והוא בבחי' רוממות והפלאה כו', וזהו פועל בהנשמה בחי' הפשטה וביטול התענוג שלה דגעה\"ת ועי\"ז נעשית כלי לקבל ההשגה דגעה\"ע כו', וכ\"ה בבחי' החכ' שצ\"ל ביטול החכ' בכדי לקבל האור דבחי' ח\"ס כו'. וז\"ע הרקיע שהוא כעין הקרח דקרח אותי' חרק והוא בחי' הביטול של המקבל שעי\"ז דוקא נעשה כלי לקבל את האור כו'. ונמצא דיש ב' בחי' רקיע, הא' בחי' השגה דבינה דאגלידו מיא דחכ' כו', והב' בחי' רקיע שהוא ביטול ההשגה כו', והוא בבחי' החכ' דבכדי להיות גילוי החכ' ממקורו זהו ע\"י הביטול דחכ', שזהו כענין\nההשתוממות שעי\"ז נופל לו השכלה החדשה ממקורה כו', והוא בחי' הרקיע שלמעלה מבחי' מים דחכ' כו', ולפ\"ז י\"ל דשלג זהו הגשמת האור שבמשפיע בכדי שיוכל להתקבל כו', ורקיע הוא ביטול המקבל בכדי שיהי' כלי לקבל כו'. וידוע דאור מים ורקיע יש עד רום המעלות, דבחי' כח\"ב דאריך זהו ג\"כ בחי' אמ\"ר דכתר דאריך בחי' אור וחכ' דאריך בחי' מים ובינה רקיע כו', וכן בעתיק בחי' ג\"ר דעתיק שהו\"ע ג' שעות הראשונות הקב\"ה יושב ועוסק בתורה כו' ה\"ז ג' בחי' אור מים רקיע כו', או י\"ל שהן בחי' ג' ראשין לראשין בחי' אור צח אור מצוחצח אור קדמון, רק ששם הכל הוא בבחי' אור כו', ובכל המדרי' הנ\"ל יש בחי' הרקיע שלמטה מהמים ורקיע שלמעלה מבחי' המים כו', והיינו דבחי' מים ורקיע זהו ממוצע להיות גילוי בבחי' החכ' כו'.\n<b>והיוצא</b> מזה דכל ההמשכות דסדר השתל' מרוכ\"ד עד סוכ\"ד הנה בכדי שיהי' בחי' ציור אדם זהו ע\"י מסכים ופרסאות כו' דגם בחי' אדם עילאה (בחי' חכ' דאצי' כו') הוא ע\"י הפרסא כו', ובמדריגה העליונה יותר אין המסך בבחי' העלם כ\"כ כו', וכמו שאמר רע\"ק לתלמידיו כשתגיעו לאבני שיש טהור אל תאמרו מים מים דהפרסא היא בחי' אבני שיש היינו שהן מאירים והן כמו מים כו', אבל מ\"מ ה\"ז בחי' העלם יותר מבחי' צמצום וגם מבחי' ההעלם דרך הכלים להיות שזהו בחי' התעלמות שנפסק האור כו', והיינו שיש כאן דבר המפסיק שעי\"ז הוא ההתעלמות יותר כו'. אך הנה הפרסאות שבאצי' ושלמעלה מאצי' זהו להיות בחי' אדם שאדמה לעליון כו', אבל להיות בחי' ציור אדם דבי\"ע בבחי' מציאות ממש כו', זהו ע\"י הפרסא שבין אצי' לבי\"ע שהיא בבחי' מסך המסתיר לגמרי על האורות דאצי', וכמו הנעל של עור שנת\"ל שמעלים לגמרי כו'. וזהו ועל דמות הכסא דמות כמראה אדם, דהנה מראה אדם זהו בחי' אדה\"ע דאצי' שהוא בבחי' אדמה לעליון כו', וי\"ל דמראה אדם זהו בחי' מל' דאצי' שהיא רק בחי'\nמראה ודמיון דאדה\"ע וכמשנת\"ל דמל' היא בחי' כה כו', ומ\"מ גם היא בחי' אדם שלמעלה מבי\"ע וכמשנת\"ל (סד\"ה בא) בשם הרמ\"ז דבחי' מל' היא בחי' דכר לגבי בי\"ע כו', אבל דמות כמראה אדם זהו בחי' אדם דברי' וכמ\"ש בכס\"מ בת\"ז ד\"ד דממעל לרקיע דיצי' ראה יחזקאל דמות אדם שהיא בחי' מל' דברי' כו'. והענין הוא כמשנת\"ל דאדם א' דם הוא"]]});
